-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODExad3ea40f2dbb$doc_companies_act_2063_2006__2063_company_act_pdf$CODExad3ea40f2dbb$,$CODEx67a243683e78$Companies Act, 2063 (2006)$CODEx67a243683e78$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2063,2006,166,$CODEx384c298a9e24$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np \n \nwww.lawcommission.gov.np 1 \nCompanies Act, 2063 (2006) \nDate of Authentication :  \n2063.7.7 (3 November 2006)", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Some Nepal Act (Amendment) Act, 2064    2064.5.9  (26 August 2007)", "content": "Act Number 18 of the Year 2063 (2006) \nAn Act made to amend and consolidate the law relati ng to companies  \nPreamble : Whereas, it is expedient to amend and consolidate t he law relating to \ncompanies in order to bring about dynamism in the e conomic development of the \ncountry by promoting investment in the industry, tr ade and business sectors through \neconomic liberalization and make the incorporation,  operation and administration of \ncompanies much easier, simpler and more transparent; \n Now, therefore, be it enacted by the House of Repr esentatives in the First Year \nof the issuance of the Proclamation of the House of Representatives, 2063 (2006).", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 1", "title": "Chapter 1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short title and commencement : (1) This act may be called as the “Companies", "content": "Act, 2063(2006)”. \n(2) This Act shall be deemed to have come into forc e on 20 Ashwin  \n2063 (6 October 2006).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions : In this Act, unless the subject or the context otherwise requires,", "content": "(a) “Company” means a company incorporated under this Act.  \n(b) “Private company” means a private company incorpora ted under this \nAct.  \n(c) “Public company” means a company other than a private company.  \n(d) “Holding company” means a company-having control ov er a subsidiary \ncompany.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 2 \n(e) “Subsidiary company” means a company controlled by a holding \ncompany.  \n(f) “Foreign company” means a company incorporated outside Nepal.  \n(g) “Listed company” means public company which has its  securities listed \nin the stock exchange.  \n(h) “Company not distributing profits” means company in corporated under \nChapter 19 on conditions that it shall not be entit led to distribute or pay \nto its members any dividends or any other moneys ou t of the profits \nearned or savings made for the attainment of any objectives.  \n(i) “Promoter” means a person who, having consented to the matters \ncontained in the memorandum of association and the articles of \nassociation to be furnished in the Office for the i ncorporation of a \ncompany, signs the same in the capacity of promoter.  \n(j) “Officer” includes director, chief executive, manag er, company \nsecretary, liquidator and any employee undertaking departmental \nresponsibility of the company.  \n(k) “Memorandum of association” means the memorandum of  association \nof a company.  \n(l) “Articles of association” means the articles of association of a company.  \n(m) “Prospectus” means a prospectus to be published by a company pursuant \nto Section 23.  \n(n) “Share” means the divided portion of the share capital of a company.  \n(o) “Preference share” means a share issued as a prefer ence share pursuant \nto this Act.  \n(p) “Ordinary share” means a share other than a preference share.  \n(q) “Bonus share” means a share issued as an additional  share to \nshareholders, by capitalizing the saving earned fro m the profits or the \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 3 \nreserve fund of a company, and this term includes t he increase of the \npaid up value of a share by capitalizing the saving or reserve fund.  \n(r) “Shareholder” means a person having ownership in th e share of a \ncompany.  \n(s) “Debenture” means any bond issued by accompany whet her putting its \nassets as collateral or not.  \n(t) “Debenture trustee” means a body corporate undertak ing the \nresponsibility for the protection of interests of d ebenture-holders at the \ntime of issuance of debentures by a company. \n(u) “Register” means a register of shareholders or debe nture-holders \nmaintained under Section 46.  \n(v) “Seal of company” means the seal of a company to be used by it.  \n(w) “Securities Board” means the securities board estab lished under the \nprevailing law to regulate and manage securities.  \n(x) “Securities” means any shares, bonds, debentures or  stocks issued by a \ncompany, and this term includes the receipt relatin g to deposits of \nsecurities and the rights and entitlement relating to securities.  \n(y) “Director” means any director of a company and this  term includes any \nalternate director.  \n(z) “Board of directors” means the board of directors of a company.  \n (z1) “Managing director” means a managing director  of a company.  \n (z2) “Premium share” means a share so issued by a c ompany as to sell it for \na value in excess of its face value.  \n(z3) “Net worth” means the assets of a company rema ining after deducting \nthe paid up capital, reserve, fund or free reserve of whatever designation \nto which shareholders have right or all other liabi lities other than \ngoodwill, if any, of the company as well as loss pr ovisions , if any, from \nthe total assets of the company for the time being.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 4 \n(z4) “Consensus agreement” means an agreement made unanimously by all \nthe shareholders of a private company existing for the time being in \nrespect of the operation of the company.  \n(z5) “Office” means the Company Registrar’s Office set up by the \nGovernment of Nepal for the administration of companies.  \n (z6) “Register” means the Registrar of the Office.   \n (z7) “Independent director” means any independent director appointed under \nSub-section (3) of Section 86. \n(z8) “Court” means the commercial bench of a court specified by the \nGovernment Nepal by a notification in the Nepal Gaz ette, with the \nconsent of the Supreme Court.  \n(z9) “Close relative” means a partition shareholder  in joint family or husband, \nwife, father, mother, mother-in -law, father-in- la w, elder brother, \nyounger brother, elder sister, younger sister, sist er-in–law ,(elder or \nyounger brother’s wife), brother-in–law , sister–in –law, brother-in- law, \n(husband of elder sister), uncle, aunt,  maternal u ncle, maternal aunt, son, \ndaughter, daughter-in-law ,grand–son, grand-daughte r, grand-daughter-\nin– law or son-in–law . \n(z10) “Prescribed” or “as prescribed” means prescri bed or as prescribed by the \nGovernment of Nepal by a notification  in the Nepal  Gazette.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 2", "title": "Chapter 2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Incorporation of Company : (1) Any person desirous of undertaking any", "content": "enterprise with profit motive may, either singly or  jointly with others, \nincorporate a company for the attainment of one or more objectives set forth in \nthe memorandum of association. \n(2) There shall be a minimum of seven promoters for  the incorporation \nof a public company.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 5 \nProvided, however, that seven promoters shall not b e required for the \nincorporation of another public company by any publ ic company.  \n(3) Notwithstanding anything contained elsewhere in  this Section, a \ncompany not distributing profits may, subject to th e provisions contained in \nChapter-19, be incorporated for the attainment of one or more objectives.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Application to be made for incorporation of compa ny : (1) Any person", "content": "desirous of incorporating a company pursuant to Sec tion 3 shall make an \napplication to the Office, in such format and accom panied by such fees as \nprescribed, and along with the following documents, as well:   \n(a) The memorandum of association of the proposed compa ny,  \n(b) The articles of association of the proposed company, \n(c)   In the case of a public company, a copy of the agreement, \nif any, entered into between the promoters prior to  the \nincorporation of the company,  \n(d) In the case of a private company, a copy of the con sensus \nagreement, if any, entered into ,  \n(e) Where prior approval or license has to be obtained from \nanybody under the prevailing law prior to the regis tration \nof a company carrying on any particular type of bus iness \nor transaction pursuant to the prevailing law, such  \napproval or license,  \n(f) Where the promoter is a Nepalese citizen, a certifi ed copy \nof the citizenship certificate and where a corporat e body is \na promoter, a certificate of registration of incorp oration, \ndecision of the Board of directors, regulating the \nincorporation of the company and major documents \nregarding incorporation.  \n(g) Where the promoter is  a foreign person or company or \nbody, permission obtained under the prevailing law to \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 6 \nmake investment or carry on business or transaction  in \nNepal, \n(h) Where the promoters is a foreign person, a document  \nproving the country of his/her citizenship,  \n(i) Where the promoter is a foreign company or body, a \ncertified copy of the incorporation of such company  or \nbody and major documents relating to such incorporation.  \n(2) Notwithstanding anything contained in Sub-secti on(1), if the      \npromoter agrees to accept the articles of association in the format prescribed for \nthe incorporation of a company with a single promot er of single shareholder, it \nshall not be required to submit the articles of ass ociation of the proposed \ncompany.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Registration of company", "content": ": (1) Where an application is made for the \nincorporation of a company pursuant to Section 4, t he Office shall, after \nmaking necessary inquiries, register such company w ithin 15 days after the \ndate of making of the application and grant the com pany registration certificate \nto the applicant, in the format as prescribed. \n(2) After a company has been registered pursuant to  Sub-section (1), the \ncompany shall be deemed incorporated.  \n(3) The office shall maintain company register in t he format as \nprescribed, for purpose of Sub-section (1). \n(4) After the incorporation of a company under this  Section, subject to \nthis Act, the matters contained in the memorandum o f association and the \narticles of association shall be binding on the com pany and its shareholders as \nif these where the provisions contained in separate  agreements between the \ncompany and every shareholder and amongst its shareholders.  \n(5) Without registering a company under this Act, n o person shall use \nthe name company and carry on any kind of transacti on by the name of any \nfirm or institution. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 7", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Power to refuse to register company : (1) The Office may refuse to register a", "content": "company in any of the following circumstances:  \n(a) If the name of the proposed company in identical wi th the \nname by which a company in existence has been \npreviously registered or so resembles the name of t hat \ncompany as it might cause misleading, \n(b) If the name or objective of the proposed company is  \ncontrary to the prevailing law or appears to be imp roper or \nundesirable in view of public interest, morality, d ecency, \netiquette etc. or reflects criminal motive , \n(c) If the name of the proposed company is identical wi th the \nname of a company of which registration has been \ncancelled pursuant to this Act or that of a company  which \nhas been insolvent under the prevailing law or so \nresembles such name as it might cause misleading an d a \nperiod of five years shall not expired after such \ncancellation of registration or insolvency,  \n(d)  If the requirements for the incorporation of a com pany \nunder this Act are not fulfilled. \n(2) If the office refuses to register company in an y of the circumstances  \nas referred to in Sub-section (1) it shall give a n otice there of, accompanied by \nthe reasons therefore, to the applicant no later th an 15 days after the date of \napplication made for the incorporation of company pursuant to Section 4. \n(3) If the office refuses to register any company p ursuant to Sub-section \n(1) or fails to give a notice pursuant to Sub-secti on (2), a person who is not \nsatisfied may file a complaint in the court within fifteen days.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Company to be a body corporate", "content": ": (1) Any company incorporated under this \nAct shall be an autonomous and corporate body with perpetual succession. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 8 \n(2) Subject to this Act, company like an individual , acquire, hold, sell, \ndispose of or otherwise deal with, any movable or immovable property. \n(3) A company may sue and be also sued by its own name. \n(4) A company may, like an individual, enter into a  contract and \nexercise the rights and perform the obligations as referred to in the contract.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Limited liability : The liability of a shareholder of a company incor porated", "content": "under this Act in respect of its transactions shall  be limited on to the maximum \nvalue of shares which he has subscribed or undertaken to subscribe .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Number of shareholders : (1) The number of shareholders of a private compa ny", "content": "shall not exceed fifty. \n(2) Subject to the proviso to Sub-section (2) of se ction 3, the number of \nshareholders of a public company shall be seven in minimum and a maximum \nof any number. \n(3) Notwithstanding anything contained in Sub-secti on (1), any \nemployee who has purchased a share of a company und er scheme of selling \nshares to employees or any employee who has already  purchased a share under \nsuch scheme but is not in service of the company for the time being shall not be \ncounted as a shareholder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Terms to be abided by company:  An company incorporated under this Act", "content": "shall abide by the following terms, in addition to t hose set forth in this Art, \nmemorandum of association or articles of association: \n(a) The company shall carry on all of its activities an d transactions by its \nname. \n(b) A private company shall add the words “private limi ted’’ to its name as \nthe last words and a public company shall add the w ord “limited” to its \nname as the last word. \n Provided, however, that this provision shall not a pply to a \ncompany not distributing profit. \n(c) A private company shall not sell its shares and debentures publicly. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 9 \n(d) A private company shall not pledge, or otherwise tr ansfer title to, its \nsecurities to any person other than its shareholder  without fulfilling the \nprocedures contained in the memorandum of consensus agreement, \n(e) A company shall not open a partnership or private firm.  \n(f) Except as otherwise provided in this Act, a company  not distributing \nprofits shall not distribute dividends among its me mbers or pay, directly \nor indirectly, any amount to a member or his/her close relative.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Paid up capital of public company : (1) The paid up capital of a public", "content": "company shall be a minimum of ten million rupees, e xcept as otherwise \nprovided in the prevailing law or in a notification  by the Government of Nepal \nin the Nepal Gazette that the paid up capital of an y particular company shall be \nin excess of the said required minimum.  \n(2) Notwithstanding anything contained in subsectio n (1), a public \ncompany which does not have the paid up capital as mentioned in that Sub-\nsection at  the time of commencement of this Act sha ll maintain the capital \nreferred to in Sub-section (1) no later than 22 Ash win 2065 (8 December 2008).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "To be incorporated as public company to carry on so me specific", "content": "transactions : Notwithstanding anything contained elsewhere in t his Act, a \ncompany carrying on the business of banking, financ ial transactions, insurance \nbusiness related transactions, stock exchange busin ess, pension fund or mutual \nfund or a company carrying on such other business o r transactions as may be \nprescribed shall be incorporated as a public company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Conversion of private company into public company : (1) In the following", "content": "circumstances, a private company shall be converted into a public company \nunder this section:  \n(a) If the general meeting of the private company, by a dopting \na special resolution, decides to convert that compa ny into \na public company, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 10  \n Provided, however, that no private company shall \nbe capable of being converted into a public company  \nunless and until it fulfills the requirements to be  fulfilled \nunder this Act for being a public company \n(b) If twenty five percent or more of the shares of a p rivate          \ncompany are  subscribed by one or more than one pub lic \ncompany, \n Provided, however, that in computing the \npercentage as referred to in this Clause, the share  passed \nby any banking or financial company as a trustee sh all not \nbe calculated. \n(c)  If a private company subscribes twenty five percen t or \nmore of the shares of a public company. \n(2) In the circumstances as refer to in Clause (a) of Sub-section (1), the \nconcerned private company, shall for being converte d into a public company, \nmake an application as prescribed, accompanied by a  copy of the resolution \nmentioned in that Clause and by the fees as prescri bed , to the office within \nthirty days after the date of such resolution. \n(3) On receipt of an application pursuant to Sub-st ation (2), the office \nshall, if the concerned private company has fulfilled the necessary requirements \nfor carrying on transactions as a public company, m ention in the company \nregister the contents of conversion of such company  into a public company and \ngive a company conversion certificates as prescribed within sixty days. \n(4) If any private company has to be converted into  a public company \nowing into the circumstances referred to in Clause ( b) or (c) of Sub-section (1), \nthe concerned private company shall make an applica tion, as prescribed, setting \nout all details, accompanied by the fees as prescri bed, to the Office for being \nconverted into a public company within seven days a fter the date of occurrence \nof such circumstances. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 11  \n(5) On receipt of an application pursuant to Sub-se ction(4), the Office \nshall, if such company has fulfilled the requiremen ts to be fulfilled by a  public \ncompany under this Act to carry on transactions, me ntion in the company \nregister the contents of conversion of company into  a public company and give \na company conversion certificate as prescribed. \n(6) If private company is converted into a public c ompany pursuant to \nthis Section, any subsidiary company of that compan y, as well, shall, ipso facto \nbe deemed to have been converted into a public company in the same date. \n(7) In the event of conversion into a public compan y pursuant to Sub-\nsection (6), it shall be the obligation of the conc erned company to make an \napplication, accompanied by the required documents,  to the Office to get \nrecorded in the company register the contents of co nversion of such subsidiary \ncompany into a public company and obtain the certificate. \n(8) In the event of conversion of any private compa ny into a public \ncompany pursuant to this Section, the provisions ap plicable to the public \ncompany under this Act shall be deemed to be, ipso facto , applicable to that \ncompany after the date of such conversion. \n(9) In the event of conversion of any private compa ny into a public \ncompany pursuant to this Section, all the assets an d liabilities of the private \ncompany so converted shall devolve on the successor company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Conversion of public company into a private company : (1) In the following", "content": "circumstance, a public company shall be converted in to a private company \nunder this Section:  \n(a) If the number of shareholders of the public company  \nbecomes less than seven,  \n(b) If the public company fails to maintain its paid-up  capital \nunder Section 11 or the paid-up capital as referred  to in \nsection 11 is not maintained because of reduction i n \ncapital pursuant to section 57. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 12  \n Provided, however, that this provision shall not \napply to the company as referred to in Sub-section (2) of \nSection 11. \n(2) In the event of occurrence of a circumstance as  referred to in Sub-\nsection (1), the concerned public company shall mak e necessary amendments \nto its memorandum of association and articles of as sociation and convert it into \na private company within six months.  \n(3) The concerned public company shall make an appl ication, \naccompanied by copies of the memorandum of associat ion and articles of \nassociation amended pursuant to sub- section (2) an d the prescribed fees, to the \nOffice for being converted into a private company, within thirty days after the \nmaking of such amendment. \n(4) On receipt of an application pursuant to Sub-se ction(3),the Office \nshall mention in the company register the contents of conversion of such \ncompany into a private company and give a company c onversion certificate, as \nprescribed, within sixty days. \n(5) In the event of conversion of any public compan y into a private \ncompany pursuant to Sub-section (4), all the assets  and liabilities of the public \ncompany to be so converted shall devolve on the successor company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Service of summons, notice etc", "content": ": (1) Notwithstanding anything contained in \nthe prevailing law, if any notice, summons, letters rogatory etc. required to be \nserved on a company, director, shareholder, debentu re-holder or employee in \nregard to the transactions of, or any matter relate d with, the company, is \ndelivered at the registered office of the company o r sent by registered post or \nsent through the tale-fax, email, telex or similar other electronic device \ninstalled in such office, such notice, summons or l etter oratory shall be deemed \nto have been  duly served. If any notice, summons, l etters rogatory etc. cannot \nbe so served, the concerned company, director or em ployee may be informed \nthereof by broadcasting or publishing a notice pert aining there to by radio, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 13  \ntelevision or in any newspaper circulating at natio nal level. In such a case, he/ \nshe shall be deemed to have been informed thereof.  \n(2) Notwithstanding anything contained in the preva iling law, if any \nnotice, summons, letter rogatory etc. is required to  be served by a company or \nby any competent authority or court on any director , shareholder, debenture-\nholder or employee or the company in any matter rel ated with his/her duties of \noffice, it may be sent to the telex, email, telefax  address, if any, given by such \ndirector, shareholder or employee and where such ad dress has not been given, \nit may be sent by registered post to the address su pplied by him/her for \ncorrespondences by post and where such summons, noti ce, letters rogatory etc. \nis so sent, the same shall be deemed to have been duly served. \n(3) Notwithstanding anything contained elsewhere in  this Act, in \nproviding a notice or information required to be se nt by accompany to its \nshareholder debenture-holder or director under this  Act or receiving any \ninformation from them, such notice or information m ay be sent to an electronic \ncommunication address supplied by them, by using ele ctronic communication \ndevice as provided in the articles of association o f the company or if they so \nagree.  \n Provided, however, that such notice or information  shall be sent by post \nor through other reliable means to the shareholder,  debenture-holder or director \nwho does not consent to the service of such notice or information on him/her \nby electronic communication device.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Functions and duties of Registrar", "content": ": (1) It shall be the duty of the Registrar to \nimplement this Act and carry out company administration.  \n(2) Without prejudice to the generality of Sub-sect ion (1), the Registrar \nmay frame and issue necessary directives for the im plementation of this Act \nand the carrying out of company administration rela ted functions in an \neffective or systematic manner: and it shall be the  duty of each company and \nofficer to abide by such directives.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 14  \n(3) The directives issued pursuant to Sub-section ( 2) shall be published \nin such a manner that such directives are available to the general public. \n(4) The Registrar may, as per necessity, delegate a ny of the powers \nconferred to him/ her under this Act to any officer  employee subordinate to \nhim/her. \n(5) Notwithstanding anything contained elsewhere in  this Section, \nnothing in this Section shall be deemed to limit th e direction given by any \nregulatory body to a company under the prevailing l aw or the authority to be \nexercised by that body in respect of such company under the prevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Pre-incorporation contract:  (1) A contract made prior to the incorporation of", "content": "a company shall be a proposed contract only, and su ch contract shall not be \nbinding on the company. \n(2) If, prior to the incorporation of a company, an y person carries on any \ntransaction or borrows money on behalf of the compa ny, such person shall be \npersonally liable for any contract related with the  transaction so carried on, \nsubject to Sub-section (3). \n(3) If, within the time mentioned in any transactio ns or within the \nreasonable time after the incorporation of a compan y, the company, through its \nact, action or conduct, accepts any act, action or conduct, accepts any act, \naction to borrowing done or made prior to the date of authorization to \ncommence its transactions or endorses such act or ac tion, that transaction shall \nbe binding on the company and the other contracting  party; and the person \ncarrying out such act to action shall be released f rom the personal liability to be \nborne pursuant to Sub-section(2). \n(4) Notwithstanding anything contained elsewhere in  this Section, the \nconsensus agreement of a private company shall gove rn any contracts made \nprior to the incorporation of such company.  \n \n \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 15", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 3", "title": "Chapter 3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "18", "title": "Memorandum of Association : (1) The Memorandum of Association of a", "content": "company shall state the following matters:  \n(a) The name of company, \n(b) The address of the registered office of the company, \n(c) The objectives of the company, \n(d) The acts to be carried out to accomplish the object ives of \nthe company, \n(e) The figure of the authorized capital of the company  and \nthe figure of the share capital to be issued by the  company \nfor time being and the figure of undertaken to be p aid by \nthe promoter of the company, \n(f) Types of shares of the company, the rights and powe rs \ninherent in such shares, value of each share and nu mber of  \nshares of different types, \n(g) Restrictions, if any, in the purchase  or transfer of shares, \n(h) Number of shares which the promoters have undertake n to \nsubscribe for the time being, \n(i) Terms of payments of share amounts, \n(j) Statements that the liability of shareholders shall  be \nlimited, \n(k) The maximum number of shareholders in case of a pri vate \ncompany, \n(l) Other necessary matters. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 16  \n(2) If any of the following matters shall be done o r provided, in addition \nto those mentioned in Sub-section(1), the memorandu m of association shall \nalso state such matters: \n(a) If the promoter or any other person is entitled to subscribe \nshares or acquire title thereto in any manner other  than by \nmaking payment in cash, such matter, \n(b) If the company is to acquire any property in any ma nner \nfrom the promoter or any other person at the time o f \ncommencement of its transactions such matter, \n(c) If the company itself to bear the expenses incurred     on its      \nincorporation, such matter, \n(d) If the promoter or any other person is entitled to any \nspecial privilege or right from the company, such matter. \n(3) In subscribing shares or acquiring title theret o by the promoter or \nany     other person in consideration fit other tha n cash payment as mentioned \nin Clause (a) of Sub- section (2) and in acquiring any property by he company \nfrom the promoter or any other person at the time o f commencement of its \ntransactions as mentioned in cause (b), in the case  if a public company, such \nconsideration  other than cash and such property sh all be caused to be valuated \nby an engineer or accountant holding certificate to  conduct valuation work \nunder the prevailing law. \n(4) The criteria for the valuation of any property pursuant to Sub-section \n(3) shall be as prescribed; and unless such criteri a are prescribed, the person \nvaluating such property shall mention the criteria employed by him/her to \nvaluate the property.  \n(5) If the memorandum of association is inconsisten t with this Act it   \nshall ipso facto  be void to the extent of such inconsistency.  \n(6) The format of memorandum of association shall be as prescribed.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 17", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "Signature to be affixed on memorandum of associatio n : (1) The", "content": "memorandum of association of a company shall state the full names and \naddresses of its promoters, indicate the number of shares which each promoter \nhas undertaken to subscribe and be signed by each of them.  \n(2) The memorandum of association shall clearly con tain the names and \naddress of a witness for each promoter and also bea r the signature of such \nwitness.  \n(3) Each promoter shall undertake to subscribe the shares as mentioned \nin the articles of association of the company and a t least one hundred shares if \nno provision is so mentioned.  \n(4) No later than one year after the incorporation of a company, an \napplication may be made, pursuant to a decision of the board of directors of the \ncompany, to the Office for the rectification of any  minor mistake or printing or \ntyping error appearing in the memorandum of associa tion and articles of \nassociation submitted along with an application made under Section 4. \n(5) If an application is made pursuant Sub-section( 4),the Office shall, if \nit deems proper after examining it, rectify such mis take or error and record the \nsame. \n Provided, however, that no matter shall be rectifi ed in a manner to alter \nthe main objectives of the company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Articles of association", "content": ": (1) A company shall frame the articles of associa tion \nin order to attain the objectives set forth in its memorandum of association and \ncarry out its activities in a well–managed manner. \n(2) The articles of association shall state the following matters:  \n(a) Procedures for convening the general meeting of the  \ncompany and notice to be given for such meeting,  \n(b) Proceedings of general meeting,  \n(c) Number of directors, provision of alternate  direct or, if any, \nand tenure of directors, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 18  \n(d) Provisions relating to the minutes of decisions of the \ngeneral meeting and the board of directors, and dup licate \ncopies and inspection thereof,  \n(e) If a person has to subscribe shares to become a dir ector of \na company, minimum number of shares, \n(f) In the case of a public company, qualifications and  \nnumber of independent director,  \n(g) Where any professional persons, other than sharehol ders, \nare to be appointed as directors, provisions relati ng to the \nnumber, tenure, qualifications and procedures of \nappointment of such persons,  \n(h) Powers and duties of the board of directors and the  \nmanaging director,  \n(i) Authority of directors and delegation of authority,  \n(j) Quorum for a meeting of the board of directors, not ice of \nmeeting and proceedings of meeting,  \n(k) Lien on shares,  \n(l) Different classes of shares and the rights, powers and  \nrestrictions attached to such shares,  \n(m) Provisions relating to calls on shares and forfeitu re of \nshares,  \n(n) Provisions relating to the transfer of shares,  \n(o) Matters on alteration in share capital,  \n(p) Matters on buying back of shares by the company, if  the \ncompany is to buy back its shares, \n(q) Appointment of a company secretary, \n(r) Provisions relating to remuneration, allowances and  \nfacilities of directors, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 19  \n(s) Use of the company’s  seal in its transactions, if it is to be \nso used,  \n(t) Accounts, books of accounts and audit of the company,  \n(u) Provisions on powers to raise loans or debentures,  \n(v) Amalgamation of the company, \n(w) Such matters, if any, as required by the prevailing  law to \nbe mentioned in the articles of association of a co mpany \ncarrying on any specific business,  \n(x) Such other necessary matters as required to be ment ioned \nin the articles of association. \n(3) If any provision contained in the articles of a ssociation of the \ncompany, inclusive of a provision on the saving of its directors or officers, is \ninconsistent with this Act and the memorandum of as sociation, such provision \nshall be void to the extent of such inconsistency. \n(4) The format of articles of association shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "Amendment to memorandum of association and articles  of association : (1)", "content": "The general meeting of a company may, subject to Se ction 6, amend the \nmemorandum of association or articles of associatio n, by adopting a special \nresolution to that effect.  \n(2) The company shall give information of any amendm ent made to the \nmemorandum of association or articles of associatio n pursuant to Sub-section \n(12) to the Office within thirty days; and the Offi ce shall record the same and \ngive information thereof to the concerned company, within seven days after the \nreceipt of such information. \n(3) Notwithstanding anything contained in Sub-secti on (2), if any \ncompany has to amend its name, it shall adopt a spe cial resolution to that effect \nat its general meeting and make an application, acc ompanied by the fees as \nprescribed, for prior approval of the Office: and i f the Office gives approval to \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 20  \namend the names as per the application so received,  the name of that company \nshall be amended. \n(4) If a shareholder of a public company who is not  satisfied with an \namendment made to the objectives of the company may , on fulfilling the \nfollowing requirements, file a petition, setting ou t the reasons therefore, in the \ncourt to have that amendment declared null and void: \n(a) A shareholder or shareholders holding at least five  percent \nshares of the paid-up capital of the company, excep t the \nshareholders who consent to or vote for the amendme nt or \nalteration, has to make a petition,  \n(b) A petition has to be filed within twenty one days a fter the \nadoption of the resolution to amend the objectives of the \ncompany,  \n(c) Where any one is to file a petition on behalf of on e or \nmore than one shareholder entitled to make petition , the \npetition has to be filed by a person who is authori zed in \nwriting for that purpose. \n(5) Unless and until the court is satisfied that th e information about the \ncontents, date, time and venue of a petition made u nder Sub-section (4) has \nalso been given to the company, the petition shall not be heard.  \n Provided, however, that if it appears from the doc uments submitted to \nthe court that the concerned company has refused to  acknowledge the notice, \nnothing shall prevent the court from hearing the petition.  \n(6) Where a petition is filed in the court pursuant  to Sub-section (4), the \namendment made to the objectives of the company sha ll not be effective \npending the final decision or order by the court in that matter. \n(7) On a petition as referred to in Sub-section (4) , the court may issue an \nappropriate order, specifying the following terms and conditions: \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 21  \n(a) Declaring the amendment made to the objectives of t he \ncompany to be fully or partly valid or void,  \n(b) Requiring the company to subscribe for a reasonable  value, \nthe shares and other rights held by the shareholder s \nmaking a petition under Sub-section (4), upon being  \ndisagreed with the making of alteration in the main  \nobjectives of the company,  \n(c) The shares have to be subscribed under Clause (b) f rom \nthe moneys as referred to in Sub-section(2) of Sect ion 61; \nand in the case  of a company which has no such mon eys, \nissuing an order to decrease the capital of the com pany as \nif the share capital were decreased to the extent o f such \nsubscription by adopting a special resolution by th e \ncompany; and where such order is issued, the compan y \nshall amend its memorandum of association and artic les of \nassociation, subject to the provisions of this Act. \n(8) Notwithstanding anything contained elsewhere in  this Act, where an \norder is issued by the court to fully or partly voi d the decision made by the \ncompany to amend its objectives, the company shall not be entitled to amend \nits memorandum of association or articles of associ ation in that matter without \npermission of the court or in a manner contrary to the order of the court. \n(9) Where the memorandum of association or articles  of association of a \ncompany is altered by an order of the court or the amendment made by the \ncompany is fully or partly endorsed by the court, s uch alteration or \nendorsement shall be enforced as if such alteration  or endorsement were made \nby the general meeting of the company on its own.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Memorandum of association and articles of associati on to be published : (1)", "content": "A public company shall publish its memorandum of as sociation and articles of \nassociation within three months after getting license to commence its business. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 22  \n(2) If any amendment is made to the memorandum of a ssociation and \narticles of association of a public company, the am ended memorandum of \nassociation and articles of association shall be pu blished within three months \nafter such amendment. \n(3) A public company shall so keep the memorandum o f association and \narticles of association published pursuant to Sub–s ection (1) or (2) at its \nregistered office that such memorandum and articles  can be made available as \nand when so demanded by the concerned.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Prospectus to be published : (1) A public company shall publish its prospectus", "content": "prior to issuing its securities publicly. \n(2) Prior to the publication of prospectus under Su b-section(1), the \nprospectus signed by all directors of the company h as to be submitted, along \nwith a written application made to the Securities B oard for approval, under the \nprevailing laws on securities. \n(3) Unless and until the Securities Board approves and gives permission \nfor the public issue under Sub-section (2) and a co py of such prospectus is \nregistered with the office, no company or no person , on behalf of such \ncompany, shall publish, or cause to be published , the prospectus of such \ncompany.  \n(4) If it appears that the prospectus submitted pur suant to Sub-section(2) \nomits any important matter or contains any unnecess ary matter the Securities \nBoard shall cause such prospectus to be amended or altered as required and \ngrant approval to publish it in accordance with law.  \n(5) If the prospectus submitted pursuant too Sub-se ction (2) is approved \nby the Securities Board, the concerned company shal l give to the Office \ninformation thereof, in writing, accompanied by a copy of the approval letter of \nthe Securities Board; and on receipt of that inform ation, the Office shall \nregister the prospectus pursuant to this Section.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 23  \nProvided, however, that if it appears that any matt er contained in this Act has \nnot been complied with, the Office may refuse to register it. \n(6) If any person demands for a copy of the prospec tus registered \npursuant to Sub-section (5), the Office shall provi de such copy by collecting \nthe prescribed fees.  \n(7) In publishing the prospectus pursuant to Sub-se ction (1), the \ncompany shall also mention that the prospectus has been approved by the \nSecurities Board and registered with the Office, and the date thereof.  \n(8) The covering page of each prospectus shall also  mention that such \nprospectus has been registered pursuant to this Sec tion and that the Securities \nBoard or the Office shall not be liable to bear any  kind of responsibility in \nrespect of the matters mentioned therein.  \n(9) Prior to the approval by the Securities Board o f the prospectus of any \ncompany, the concerned company shall make a declara tion before the \nSecurities Board that the provisions of this Act ha ve been complied with; and \nthe Securities Board may, if it deems necessary, se ek opinion of the Office on \nthat matter.  \n(10) Other procedures to be fulfilled in publishing  the prospectus and \nthe matters to be set out in the prospectus shall b e as mentioned in the \nprevailing law on securities.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Liability for matters contained in prospectus : (1) It shall be the duty and", "content": "obligation of the concerned company to abide by the  matters contained in the \nprospectus published under Section (23). \n(2) The directors who have signed the prospectus as  referred to in Sub-\nsection (1) shall be liable for the matters mentioned in that prospectus . \n(3) If any published prospectus contains false stat ements made \nmaliciously or deliberately and any person sustains  any loss or damage by \nreason of his/her subscription of securities on the  faith of that prospectus, the \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 24  \ndirectors who have signed that prospectus shall be personally liable to pay \ncompensation for the actual loss or damage so sustained . \nProvided, however, that a promoter who resigns befo re the decision made by \nthe company to publish the prospectus or whom on be coming aware of any \nfalse statement in the prospectus, publishes a noti ce of that matter to the \ninformation of the general public prior to the sale  or allotment of securities or \nwho proves that he/she did not know that the prospe ctus contained any false \nstatement shall not be liable to bear such compensation.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Duplicate copies to be issued : (1) If any shareholder or any other person", "content": "concerned demands for a duplicate copy of the memor andum of association, \nprospectus, annual accounts and audit or directors report or any document \nsubmitted by the company to the Office the concerne d company shall provide a \nduplicate copy of such document by collecting the f ees prescribed in the \narticles of association.  \n Provided, however, that any person whoever may dem and for such \ndocument in the case of a public company. \n(2) If the concerned company does not provide dupli cates of such \ndocuments pursuant to Sub-section (1), the Office s hall provide duplicates of \nsuch documents from its records by collecting the prescribed fees.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Seal of company and its use : (1) A company which intends to use a seal in its", "content": "transactions shall make the seal in its name in clear legible letters.  \n(2) The company using the seal as referred to in Su b-section (1), shall \nuse it in any reports and records to be submitted o n its behalf and business \nletters to be used in its name, statements of accoun ts, bills, invoices, requisition \norder forms, notices and official publications, neg otiable instruments, bills of \nexchange, promissory notes, and official documents s igned or issued on its \nbehalf. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 25  \n(3) If any person fails to indicate the name of the company while signing, \non behalf of the company, the documents mentioned i n Sub-section (2), such \nperson shall be personably liable for the same.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 4", "title": "Chapter 4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "27", "title": "Face value of shares and application : (1) The face value of shares of a private", "content": "company shall be as specified in its articles of association. \n(2) The face value of shares of a public company sh all be fifty rupees \nper share or shall be equivalent to such amount exc eeding fifty rupees as is \ndivisible by the figure ten as provided in the memo randum of association and \narticles of association.  \n(3) In inviting an application by a public company for the subscription \nof its shares, no amount exceeding fifty per cent o f the face value of each share \nshall be demanded with the application. \n Provided, however, that in raising capital by a co mpany which has been \nin operation since at least three years ago by publ ishing its audited fiscal \nstatements for its last three years, at the time of  publication of its prospectus, \nthis provision shall not be applicable. \n(4) A person who intends to subscribe the shares of  a public company \nhas to make an application in the format as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Allotment of shares :", "content": "(1) Where a public company invites the general pub lic to \napply for the subscription of its shares it shall a llot the shares and give the \nshareholders a notice in the format as prescribed, within a maximum period of \nthree months after the date of closure of share issue.  \n Provided, however, that in cases where at least fi fty percent of the total \nshares issued publicly cannot be sold failing a gua rantee/underwriting \nagreement on the subscription of at least fifty per cent of the publicly issued \nshares, no shares shall be allotted. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 26  \n(2) If the company makes an application,  explainin g the reasons for \nfailure to allot shares within the time-limit set forth in Sub-section(1),  owing to \nthe circumstance mentioned in the proviso to that S ub-section within seven \ndays after the expiration  of that time-limit, the O ffice may extend the time \nlimit for up to three months for the allotment of sh ares. If the shares cannot be \nallotted even within such extended time limit, the c ompany may allot such \nshares through negotiations or any other methods.  \n(3) If the allotment of shares cannot be made even within the time –limit \nas referred to in Sub-section (1) or (2) , the amou nt received for the \nsubscription of shares as well as an interest there on, as prescribed, from the day \nof expiration of such time-limit to the day of refu nd of such amount shall be \nrefunded. \n(4) If the funds are insufficient to refund the amo unt required to be \nrefunded pursuant to Sub-section (3), the shortfall  amount shall be borne by the \npromoters personally.  \n(5) Where the allotment of shares pursuant to Sub-s ection (1)or (2) is \nmade discriminatorily or with intent to cause any lo ss or damage to any \ninvestor  may file a petition, setting out the reasons for the same, in the court on \nthat matter.  \n(6) If a petition is filed pursuant to Sub-section 5), where any investor \nhas sustained any loss or damage by reason of the d eliberate violation of this \nSection by any officer of the company or permission given by such officer to \nany one to commit such violation, the court may iss ue an order for realization \nfrom such officer personally of compensation for su ch loss or damage as well \nas reasonable expenses incurred in the legal action.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "29", "title": "Power to issue shares at premium : (1) Any company fulfilling the following", "content": "conditions may, with the prior approval of the Offi ce, issue shares at a \npremium:  \n(a) The company has been making profits and distributin g \ndividends for three consecutive years,  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 27  \n(b) The company’s net worth exceeds its total liabilities,  \n(c) The company’s general meeting has decided to issue \nshares at a premium.  \n(2) Where the shares are sold at a premium pursuant  to Sub-section (1), \na sum in excess of the face value, out of the proce eds thereof, shall be \ndeposited in a premium account to be opened to that effect. \n(3) The company may use the moneys in the account a s referred to in \nSub-section (2) in the following acts:  \n(a) Paying up un-issued share capital to be issued to t he \nshareholders as fully paid bonus shares,  \n(b) Providing for the premium payable on redemption of any \nredeemable preference shares,  \n(c) Writing off the preliminary expenses made by the \ncompany, \n(d) Bearing or reimbursing the expenses of, or the commission \npaid or discount allowed on, any issue of shares of  the \ncompany.  \n(e) In making a request for approval of the Office to i ssue \nshares at a premium   pursuant to Sub-section (1), the \naudited financial statements for three years shall be \nprovided to the Office.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Shares with different rights and rights of such sha reholders", "content": ": (1) The \ncompany may, by making provisions to that effect in  its memorandum of \nassociation and articles of association, issue vari ous classes of shares with \ndifferent rights attached thereto.  \n(2) Except as otherwise provided in the articles of  association of \ncompany, approval of the shareholders of any partic ular class shall be required \nto make any alteration in the rights of those shareholders of that class.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 28  \n Provided, however, that no alteration may be made in the rights of the \nshareholders of any particular class in a manner to  adversely affect the rights of \nthe shareholders of any other class.  \n(3) If the shareholders representing at least ten p ercent share of any \nparticular class who are not satisfied with a decis ion to make alteration in the \nrights attached to the shares of that class pursuan t to Sub- section (2) file a \npetition in the court to have the decision to make such alteration void, the \ndecision made to make alteration in the rights of t he shareholders of such class \nshall not be enforced unless and until otherwise de cided or ordered by the court. \n(4) A petition shall be made pursuant to Sub-sectio n (3) within thirty \ndays after the  decision made to make alteration in  the rights attached to the \nshares of any particular class; and any decision as  referred to in Sub-section(2) \nshall not be enforced pending the expiration of that time limit. \n(5) If it appears that alteration in the rights con ferred to the shareholders \nof the class concerned is prejudicial to the rights  of the petitioner shareholders, \nthe court may quash the decision made on the altera tion in the rights of the \nshareholders of that class. \n(6) The board of directors shall submit a proposed resolution on the \nalteration in the rights of the shareholders of any  particular class pursuant to \nSub-section (2) to the general meeting of the share holders of the concerned \nclass; and such resolution has to be adopted as a s pecial resolution by the \ngeneral meeting.  \n(7) Notwithstanding anything contained elsewhere in  this Section, in \nprivatizing a company fully or partly owned by the Government of Nepal, as a \nshareholder, in accordance with the prevailing law on privatization, the \nGovernment of Nepal may have special voting right i n making decision on the \nfollowing matters, as provided in the articles of as sociation, so long as the \ninvestment to the Government of Nepal is retained in such company: \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 29  \n(a) In making decision on a resolution to relinquish th e title to \nan undertaking pursuant to Clause (a) of Sub-sectio n (1) of \nSection 105,  \n(b) In making decision on voluntary liquidation of the \ncompany,  \n(c) In making decision to amalgamate the company into \nanother company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Return of shares to be filed with office", "content": ": (1) A company shall file with the \nOffice a return of allotments stating the number of  shares issued and allotted, \ntotal amount of the shares, the names and addresses  of the allotters, and the \namount paid or due and payable on each share, withi n thirty days after the \nallotment of shares.  \n(2) if any shares have been allotted as fully or pa rtly paid up otherwise \nthan in cash, the company shall file with the Offic e a deed constituting the title \nof the allotter to the shares together with any con tract of sale or a contract for \nservices or other consideration in respect of which  that allotment was made, \nand a return stating the number and nominal amount of shares so allotted and \nthe extent to which they are to be treated as paid- up.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "Dealing in securities : (1) While issuing its securities to the general p ublic, a", "content": "public company shall deal in the securities only th rough a securities dealer \nrecognized to do securities transactions including all acts such as the sale, \nallotment and recovery of amounts of such securities.  \n(2) A public company shall file with the Office a c opy of an agreement \nmade by it on the dealing of securities through any  body, within seven days \nafter the date of making of such agreement.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Share certificate : (1) A share certificate in the prescribed format shall be", "content": "issued to every shareholder in respect of  each sha re subscribed by him/her, \nwithin two months after the allotment of shares; th e share certificate shall bear \nthe signature of any two out of a director or chief  executive of the company or \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 30  \nthe company secretary, in the case of a public comp any, and the signature of \nthe person as mentioned in the articles of associat ion or consensus agreement, \nin the case of a private company, and also bear the seal of the company, if any .  \n(2) While issuing a share certificate in respect of  any shares held jointly \nby two or more persons, the share certificate may b e issued to any one of them, \nby mentioning their names in the certificate. \n Provided, however, that, the names of all sharehol ders shall be \nmentioned in the shareholder register. \n (3) If a share certificate is lost or destroyed be cause of a divine  act or \notherwise, the shareholder shall give information t hereof to the registered \noffice the company immediately when he/she knows tha t the share certificate \nhas been so lost or destroyed because of the divine act or otherwise.  \n (4) If any application made pursuant to Sub-sectio n (3), the company \nshall ,  if the matter contained in the application  seems to be reasonable after \ninquiring into all necessary matters relating there to, issue another share \ncertificate to the applicant, by collecting the dup licate fees  for duplicate copy \nas prescribed in the articles of association; and t his matter shall also be \nrecorded in the shareholder register. \n (5) Notwithstanding anything contained elsewhere i n this Section, if a \nlisted company has caused a register to be maintain ed, pursuant to Sub-section \n(6) of Section 46, by the securities registrar auth orized to provide securities \ndeposit service under the prevailing law, provision  may be made to issue to the \nshareholder a securities deposit passbook or any ot her certificate certifying \nhim/her to be a shareholder, instead of a share certificate. \n (6) A certificate issued by a company, signed by i ts competent officer \nand under the seal of the company, if  any, to be u sed by it, specifying the \nnumber of shares or debentures held by any sharehol der or debenture-holder \nshall be prima facie  evidence of his/her title to such shares or debentures.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 31  \n (7) If any company allots any shares or debentures  or transfers such \nshares or debentures to a representative of a body licensed under the prevailing \nlaw to carry on securities dealings, the provision of Sub-section(1) shall not \napply to such shares or debentures.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Raising loans or issuing debentures : (1) If  a public company deems", "content": "necessary to raise loans or issue debentures, it ma y, specifying the reason \ntherefore, a work plan to be executed from proceeds  and budget necessary for \nthat propose raise loans or issue debentures with o r without pledging or \nmortgaging its immovable assets.  \nProvided, however, that no debentures may be issued  unless and until an \napproval to commence its business is obtained and i ts issued capital is fully \npaid up.  \n(2) Notwithstanding anything contained in the preva iling law, any \ncompany may, subject to sub- section(1) , raise add itional  loans or issue \nadditional debentures against the security already furnished by that company \nwith the already furnished by that company with the  previous creditors as a \nsecurity from such creditors, within the limit of s uch security, by clearly \nindicating the previous creditors as well as amount  of loan (amount) already \nobtained.  \n(3) Notwithstanding anything contained in the preva iling law, the \nmatters relating to the terms, repayment period and  interest of a   loan \nborrowed or lent by a company shall be governed by a deed or contract \nconcluded between the creditor and the borrower.  \n(4) If a company is to raise loans or issue debentu res pursuant to Sub- \nsection (1) or (2), the company shall give its info rmation, along with the \nreasons for the same, to the office.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "35", "title": "Procedures for issuing debentures : (1) A public company shall, in issuing", "content": "debentures pursuant to this Act, issue debentures a fter making provision of a \ndebenture trustee. Such debenture trustee has to be  a debenture trustee licensed \nby the Securities Board.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 32  \n(2) The matters relating to the creditor and the bo rrower, in issuing \ndebentures with a debenture trustee, shall be as me ntioned in an agreement to \nbe concluded between such trustee and the company.  \n(3) If the memorandum of association or the article s of association shall \nprovide that debentures can be converted into share s or such term has been \nspecified prior to the issuance of debentures, a de bentures may be converted \ninto shares, subject to the share capital related provisions of this Act.  \n(4) If any debentures are to be converted into shar es pursuant to Sub-\nsection (3), this matter has to be clearly mentioned in the prospectus. \n(5) Notwithstanding anything contained in the preva iling law, the court   \nmay, if it thinks necessary, issue an order of spec ific performance to get \nperformed a contract concluded between a public   c ompany and a person in \nrespect of the subscription of the debentures issued by that company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Agreement to be concluded between debenture trustee  and company : (1)", "content": "An agreement has to be concluded between a company issuing debentures and \na debenture trustee acting as a trustee for the pro tection of the interest of \ndebenture-holders, in respect of the debentures to be raised by such company.  \n(2) An agreement to be concluded pursuant to Sub-sec tion (1) shall set \nout the following matters: \n(a) that the debenture trustee is entitled to carry out , or cause \nto be carried out, valuation of the company’s asset s, \nproject analysis or management analysis, \n(b) the period of repayment of the principal and intere st of \ndebentures subscribed by the debenture-holder, inte rest \nrate, mode of repayment of the principal and intere st, \nmode of repayment of the principal and interest, an d \nmatter of conversion of debentures into shares, if there is \nsuch provision,  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 33  \n(c) Matters, relating to a provision made on the lights  of other \ncreditors over the assets of the company and liabil ities that \nmay arise therefrom in the future.  \n(d) A provision that, in the case of violation or non-f ulfillment \nof the terms mentioned in the agreement or for any other \nreasonable reason, if it is required to take the co ntrol of \nfinancial transactions of the company or to take po ssession \nif the security as referred to in the agreement, th e \ndebenture trustee may take in his/her possession th e assets \nor properties of such company to the property that he has \ntaken as the security of guarantee or hold the secu rity of \nguarantee with himself/herself or sell the same by auction \nor in any other appropriate manner,  \n(e) Procedures for payment by the company of the servic e \ncharges and other direct expenses of he debenture trustee, \n(f) That the debenture trustee shall not be liable to a ny loss or \ndamage caused to the company or the debenture-holde r \nfrom any act done by the trustee in that capacity, \n(g) That, in the event of occurrence of any circumstanc es \nnecessitating the liquidation of the company, the d ebenture \ntrustee is entitled to take such legal action as ma y be taken \nin behalf of the debenture- holder and exercise the  powers \nof the debenture holder. \n(h)  Other necessary matters on the protection of inter est of \nthe debenture-holder. \n(3) The debenture trustee may, for the protection o f interest of the \ndebenture-holder, take security of the assets of th e company and get such \nsecurity registered in his/her name pursuant to the prevailing law. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 34  \n(4) Prior to the taking of security pursuant to Sub -section (3), the \ndebenture trustee may, if he/she deems necessary, a lso carry out, or cause to be \ncarried out, the calculation of property or assets to taken as security and the \nproject analysis of management analysis of the company. \n(5) After the conclusion of an agreement between a debenture trustee \nand a company pursuant to this Section, such compan y has to obtain the \napproval of the debenture, trustee if any.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "Inquiry and demand of statements by debenture trust ee : Prior to", "content": "concluding an agreement with a company to act as a debenture trustee, the \ndebenture trustee may hold necessary inquiry into, and obtain or demand \nstatements, notice or information on, the following  matters; and the concerned \ncompany has to provide the same if so demanded:  \n(a)  Whether the memorandum of association or article o f association of the \ncompany has a provision that it may raise loans or debentures: and if so, \nwhether the board of directors of the company has p owers to make \ndecision to so raise debentures, \n(b) Whether the memorandum of association or articles o f association of the \ncompany has a provision that debentures may be rais ed through a \ndebentures trustee, \n(c) Whether there is a situation that the existing asse ts of the company can \ncover the value of debentures raised, \n(d) Matters relating to other creditors and liabilities of the company. \n(e) The company’s balance sheet and auditor’s report. \n(f) Such other necessary matters as the debenture trust ee may consider to be \nappropriate.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "38", "title": "Company to submit periodic statements to debenture trustee : (1) After an", "content": "agreement has been concluded between a company and a debenture trustee \nunder Section 36, the company has to submit its sta tements in financial \ntransactions to the debenture trustee in every six months.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 35  \n(2) In the event of a change in the management or a ny kind of   change \nin the ownership of the company after raising of de bentures, the company has \nto give information thereof to the debenture truste e within seven days after \nsuch change.  \n(3) In the event of necessity of any additional sta tement, notice or \ninformation submitted by the company pursuant to Su b-section(1) or (2), the \ndebenture trustee may demand such statement, notice  or information from the \ncompany; and it shall  be the duty of the company t o provide the statement, \nnotice or information so demanded to the debenture trustee.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "39", "title": "Rights and liabilities of debenture trustee : (1) If the company violates any of", "content": "the terms mentioned in the agreement concluded unde r Section 36, the \ndebenture trustee may instruct such company to fulf ill such terms as soon as \npossible or to make repayment of the principals and  interest of the debenture-\nholder within a time limit as specified by him/her.  \n(2) If it is required to take the financial transac tion of the company \nunder control or to possess the security as referre d to in the agreement by \nreason of the repayment made under Sub-section (1) or for any other reason, \nthe debenture trustee may, subject to the prevailin g law, take the assets, \nproperties or securities of such company under his/ her control and hold the \nassets or properties so possessed in his/her own or  sell such assets or properties \nby auction or otherwise or deal with the same in other manner. \n(3) Following the possession of the assets of the c ompany under Sub-\nsection (2), the amount of a debenture-holder shall  be repaid out of the \nproceeds of sale of the assets.  If any amount rema ins surplus after repayment \nof the amount payable to the debenture-holder, the debenture trustee shall \nreturn that amount to the concerned company \n(4) Notwithstanding anything contained elsewhere in  this Act, except in \ncases where the debenture trustee him/herself buys the assets taken by the \ndebenture trustee as the security, if the proceeds of sale of the property which \nthe debenture trustee has taken as security or poss essed be not sufficient to \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 36  \nrepay all the amounts to debenture holders, the deb enture trustee shall pay the \namounts to debenture-holders on pro rata;   and such shortfall amounts shall not \nbe recovered from the debenture trustee’s property.  \n(5) Any debenture-holder holding more than fifty pe rcent debentures \nmay, showing the ground of failure of a debenture t rustee to act in the interest \nof debenture-holder, make an application to the Sec urities Board to remove \nsuch debenture trustee.  \n(6) If, on examining the application made pursuant t o Sub-section (5), \nthe contents appear to be reasonable, the Securitie s Board may remove such \ndebenture trustee and arrange for another debenture trustee.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "40", "title": "Service charges to be collected by debenture truste e : (1) The debenture", "content": "trustee may collect service charge from a company f or having acted in the \ncapacity of debenture trustee. The amount of such s ervice charge shall be as \nspecified in the agreement concluded between the de benture trustee and the \nconcerned company.  \n(2) The debenture trustee may recover from the conc erned company \nsuch actual expenses incurred in doing any act on b ehalf of the company or \ndebenture-holder or in carrying out valuation, poss ession or auction sale of the \ncompany’s assets.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "41", "title": "Debenture trustee to have rights of debenture-holde r : (1) If a company", "content": "raising debentures is liquidated or becomes insolve nt for any other reasons, the \ndebenture trustee shall make representation on behalf of the debenture-holder.  \n(2) In the event of necessity to institute a lawsui t on behalf of the \ndebenture-holder for the repayment of the principal  and interest of such \ndebenture-holder or otherwise, the debenture truste e shall have the right to \ninstitute the lawsuit on behalf of the debenture-holder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "42", "title": "Sale or pledge of shares or debentures : (1) The share or debenture of a", "content": "company may be sold or pledged as good as movable p roperty, subject to this \nAct, the memorandum of association and articles of association.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 37  \n(2) Notwithstanding anything contained in Sub-secti on (1), the promoter \nof a company, other than a private company which ha s not borrowed loan from \nany other company, shall not be entitled to sell or  pledge any share held by \nhim/her  until the first general meeting of that co mpany is held and a call on the \nshare issued in his/her name is fully paid up . \n(3) where a share or debenture is pledged pursuant to Sub-section(1), the \npledge shall make an application, in such format an d along with such fees as \nmay be prescribed, to the registered office of the company to have the matter \nrecorded in the register. The applicant shall also submit the deed on pledge as \nwell as the share or debenture certificate, along w ith the application to be so \nmade.  \n(4) Where an application is made pursuant to Sub-se ction (3), the \ncompany shall record in the register the execution of such pledge and on \nreceipt of information on the redemption of the shar e or debenture so pledged, \nthe records of such pledge shall be crossed off the register.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "43", "title": "Transmission of shares or debentures : (1) If any share or debenture is sold,", "content": "subject to Sub-sections(1) and (2) of Section 42, t he buyer thereof shall make \nan application to the registered office of the comp any , in such format and \nalong with such fees as may be prescribed, to have such debenture or share \ntransmitted to his/her name. The applicant shall al so submit, along with such \napplication, a copy of the deed relating to the sal e and purchase of share or \ndebenture certificate.  \n(2) If an application is made under Sub-section (1) , the company shall \ncross off the name of transferor shareholder or deb enture holder and enter the \nname of the transferee shareholder in the register within fifteen days after the \nmaking of such application.  \n(3) Notwithstanding anything contained in Sub-secti on (1), if the \nprevailing law on securities transactions provides that no deed of transfer is \nrequired to transfer the title to the share or debe nture of a company such deed \nshall not be required to be produced along with an application to be so made.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 38  \n(4) If a person who transfers any securities makes an application, also \naccompanied by a deed of transfer of share, singed by the purchaser to get the \ntransfer of any share or debenture recorded, the co mpany shall register the \nname of share or debenture transferee in the shareh older register or debenture- \nholder register as if such application was made by the transferee him/herself.  \n(5) If any person acquires the title to any share o r debenture by \noperation of any other provision contained in the p revailing law the provision \ncontained in Sub-section(1), shall not be deemed to  prevent the company from \nregistering such person as a shareholder or debenture-holder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "44", "title": "Refusal to register share or debenture : (1) Notwithstanding anything", "content": "contained in Section 42 or 43, a company may, in th e following circumstances, \nrefuse to record any pledge of a share in the regis ter or to effect transmission of \na share or debenture where it has been disposed of:  \n(a) If a call on the share has not been paid up,  \n(b) If such transmission will be contrary to the articl es of \nassociation of the company or the agreement conclud ed \nbetween the shareholders,  \n(c) If the transfer fee is not furnished along with the  \napplication.  \n(2) In refusing to record the pledge of a share or debenture in the register \nor to effect transmission of a share of debenture un der Sub-section(1), the \ncompany shall give information thereof to both the transferor and the transferee \nor the ledger and pledge of the share or debenture within fifteen days from the \ndate of making application.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "45", "title": "Other circumstances where shares or debentures may b e transmitted : If", "content": "any person becomes entitled to the share or debentu re holded by any \nshareholder or debenture-holder because of his/her death, being insolvent or \notherwise under the prevailing law, and that person  so acquiring the title or on \nwhom the title is so devolved makes an application accompanied by an \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 39  \nevidence thereof, to the company, in such format an d accompanied by such \nfees as prescribed, the company shall transmit such  share or debenture to \nhim/her.  \n Provided, however, that notwithstanding that a sha re has not yet been \ntransferred to the successor so acquiring the title , if an instrument of transfer of \nthe share held by the previous shareholder and of h is/her other rights over such \nshare is executed by his/her heir established under  the prevailing law, such \ntransfer shall be deemed to have transferred to such successor.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "46", "title": "Shareholder and debenture-holder register : (1) Each company shall", "content": "establish a shareholder register and debenture-hold er register in the prescribed \nformat and maintain the same at its registered office.  \n(2) The following matters concerning each sharehold er shall be \nmentioned in the shareholder register as referred t o in Sub-section (1), \naccording to the serial number of shares:  \n(a) Full name and address of  the shareholder,  \n(b) Number of shares subscribed by the shareholder,  \n(c) Total amount paid by the shareholder and outstandin g \namount payable by him/her  for the share,  \n(d) Date of registration of his/her name as the shareholder,  \n(e) Date when his/her name was struck off,  \n(f) Name and address of the nominee after the death of the \nshareholder, if such nominee is appointed. \n(3) The following matters concerning each debenture -holder shall be \nmentioned in the debenture- holder register as refe rred to in Sub-section (1), \naccording to the serial number of debentures:  \n(a) Full name and address of the debenture-holder, \n(b) Number of debentures subscribed by the debenture-holder,  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 40  \n(c) Total amount paid by the debenture-holder and \noutstanding amount payable by him/her for the debenture,  \n(d) Date of registration of his/her name as the debentu re-\nholder,  \n(e) Date when the name of the debenture-holder was stru ck \noff,  \n(f) Name and address of the nominee after the death of the \ndebenture-holder, if such nominee appointed.  \n(4) If a shareholder or debenture-holder of a compa ny desires to inspect \nthe register maintained pursuant to Sub-section (1) , the company shall allow \nhim/her for the same. \n Provided, however, that in the case of a public co mpany, the company \nmay, by publishing a seven-day advance notice in a newspaper with national \ncirculation, and in the case of a private company, the company may, as \nprovided in the articles of association or consensu s agreement, close inspection \nof the register for a maximum period of thirty days  at one time, not exceeding \nin the aggregate forty-five days in a year.  \n(5) If any person desires to have a duplicate copy of the shareholder \nregister, such duplicate copy shall be issued to th at person by collecting the \nfees as prescribed, in the case of a public company , and such fees as mentioned \nin the memorandum of association, articles of assoc iation or consensus \nagreement, in the case of a private company, except  in case where inspection is \nclosed pursuant to the proviso to Sub-section (4).  \n(6) Notwithstanding anything contained elsewhere in  this Section, a \nlisted company may cause the securities registrar r ecognized under the \nprevailing law to provide securities deposits servi ce to establish and maintain a \nregister. A copy of the register so maintained shal l be kept at the registered \noffice of the company, prior to giving a notice of the general meeting each year. \nThe register shall set out the matters mentioned in Sub-sections (2) and (3) .  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 41  \n(7) If a register maintained under Sub-section (6) is found to have \nrecorded a false matter in a manner to affect the r ight and interest of a person, \nsuch securities registrar, his/her director, officer and employee shall be liable to \npunishment as mentioned in Section 160, and the con cerned person shall also \nbe entitled to have recovered the loss and damage c aused to him/her because of \nsuch false record.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "47", "title": "Information on title to share : (1) If a company asks any shareholder to", "content": "provide information as to  what capacity one has ob tained the shares with full \nvoting rights registered in his/her name or whether  any other person has \ninvestment in the shares registered in the name of such shareholder and where \nthere is another person as a the beneficiary of such shares, as to the identity and \nnature of the title of that person, it shall be the  duty of such shareholder to \nprovide such information to the company within thirty days.  \n(2) On receipt of the information sought under Sub- section (1) , the \ncompany shall record opposite the name of the conce rned shareholder, in the \nregister the date of demand of such information, da te of receipt of information \nand the contents of information received and provid e the Office with \ninformation pertaining there to within seven days.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "48", "title": "Address of shareholder : (1) Unless otherwise altered by a notice, the add ress", "content": "of a shareholder mentioned in the shareholder regis ter shall be considered to be \nhis/her real address.  \n(2) In the event of change of address of a sharehol der, a written notice of \nthe new address has to be given to the registered o ffice of the company \nimmediately after such change. \n(3) On receipt of the notice as referred to in Sub- section (2), the director \nor company secretary shall record the address so ch anged in the shareholder \nregister.  \n(4) When a notice is sent to the address supplied b y a shareholder, a \nnotice required to be sent by a company to the shar eholder under this Act shall, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 42  \nunless otherwise proved, be deemed to have been dul y sent, and received by \nthe concerned shareholder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "49", "title": "Index of shareholders : (1) Unless the shareholder register is in such form as in", "content": "itself to clearly constitute an index of the names of shareholders, every \ncompany having more than fifty shareholders shall p repare and keep a separate \nindex of the names of its shareholders.  \n(2) In the event of any alteration in the sharehold ers register, necessary \nalteration shall also be made in the index prepared  under Sub-section (1) within \nthirty days after the date of such alteration in the register.  \n(3) The index of shareholders shall be kept in such  a manner that \nnecessary information in respect of each shareholde r can be readily found from \nthe shareholder register.  \n(4) The index of shareholders shall be kept togethe r with the shareholder \nregister.  \n(5) If a company fails to comply with this Section,  the company shall be \ndeemed to have failed to comply with this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "50", "title": "Substantial shareholders : (1) If any person subscribes ordinary shares with", "content": "full voting rights that are five percent or more of  the paid up capital of any \npublic company of which shares that person has held  in his/her name or \nthrough his/her agent, that person shall be deemed to have his/her substantial \nshareholding in such company.  \nProvided, however, that in the case of a company ha ving the paid up capital of \nmore than two hundred fifty million rupees, any per son shall be deemed to \nhave the substantial shareholding despite that such  person has subscribed one \npercent or more of the total paid-up capital of such company.  \n(2) A substantial shareholder of every public compa ny shall give the \ncompany information setting out his/her name, addre ss as well as full \nparticulars of the shares registered in his/her or his/her agent’s name, within \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 43  \nthirty five days after the knowledge of being a sub stantial shareholder of that \ncompany.  \n(3) If a person ceases to be a substantial sharehol der of any public \ncompany, that person shall give the company informa tion setting out his/her \nname, the date on which he ceases to possess the st atus of a substantial \nshareholder of that company and other particulars a s well as the reason why \nhe/she has ceased to be a substantial shareholder, within thirty-five days after \nthe date of knowledge of that matter.  \n(4) Every public company shall maintain a separate register for the \npurposes of Sub- section (1), (2) and (3).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "51", "title": "Inventory of shares, debentures and loans : (1) Every company shall prepare", "content": "and maintain an inventory of the existing sharehold ers and debenture -holders \nand persons who ceased to be shareholders or debent ure-holders as at thirty \ndays prior to the holding of the........ ∝ annual general meeting.  \n(2) The inventory as referred to in Sub-section (1)  spell outs, inter alia , \nthe following particulars.  \n(a) Authorized capital and number of shares of the company,  \n(b) Issued share capital of the company,  \n(c) Paid-up  capital of the company,  \n(d) Calls made on every share,  \n(e) Total amount of installments paid,  \n(f) Total amount due and recoverable,  \n(g) Total amount paid  on share and debentures as brokerage,  \n(h) In the event of forfeiture of any shares, total num ber of \nsuch shares, reasons for forfeiture and date thereof,  \n                                                   \n∝ Deleted by the Some Nepal Act (Amendment) Act, 2064  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 44  \n(i) Loans borrowed from any bank, financial institution  or \nany other person or guarantee furnished by the company,  \n(j) Names and addresses of the existing directors.  \n(3)  The inventory referred to in Sub-section (1) s hall be signed by at \nleast one director and be submitted to the Office w ithin 30 days after the date at \nwhich the annual general meeting of the company is held and, in the case of a \ncompany not holding the annual general meeting with in one year after the date \nat which the company has obtained permission to car ry on such business as to \nrequire permission of the concerned  body pursuant to the prevailing law, if the \ncompany carries on such business, and after the dat e of registration where such \npermission is not required; and if there is any alt eration in the inventory once it \nis submitted pursuant to Sub-section (2) , only the details of such alteration can \nbe submitted.  \n(4) If any alteration is made in the inventory, as referred to in sun-\nsection (1), of a company not holding the general m eeting details thereof shall \nbe sent to the Office within six months of such alteration.  \n(5) Notwithstanding anything contained elsewhere in  this Section, if any \ncompany mentions the details as referred to in Sub- section(1), as well, in the \nreport required to be submitted pursuant to Section  78, such company shall not \nbe required to send a separate inventory to this Office under this Section .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "52", "title": "Lien on shares : A company may attach a share registered in the na me of a", "content": "shareholder and dividends payable thereon, as well,  for all moneys due and \npayable by him/her to the company in respect of tha t share or for all moneys \ndue and payable by him/her to the company under the  prevailing law and \nrecover such moneys by deducting the same from the dividends.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "53", "title": "Payment of amount for shares:  (1) An amount for a share shall be paid up", "content": "within the period of a call made in accordance with the articles of association.  \n(2) In making a call pursuant to Sub-section (1), a  company shall send \nevery shareholder a written notice, in the prescrib ed format, specifying a time-\nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 45  \nlimit of at least thirty days and the installment pa yable by him/her, the place \nand time for payment.  A public company shall also publish such notice, for at \nleast three times, in a daily newspaper with national circulation.  \n(3) If a shareholder fails to pay the sum called an d payable in respect of \nthe share within the period as referred to in Sub-s ection(2), a notice shall be \nsent to the concerned shareholder, giving an additi onal period of three months \nafter the date of expiration of that period, and sp ecifying clearly that if  \npayment is made within that period, it shall be acc epted,  along with interest at \nthe prescribed rate and if that shareholder fails t o make payment even within \nthat period, his/her  share shall be liable to be f orfeited. In the case of a public \ncompany, such notice shall also be published in a d aily newspaper with \nnational circulation for at least three times. In t he installment called is not paid \neven within the time-limit as mentioned in that noti ce, the company may forfeit \nall or the remaining shares after retaining the num ber of shares as fully paid up \nto the extent of the amount paid up on the shares i n respect of which the \ncompany has given such notice or also to the extent of the amount of dividends, \nif any, attached in respect of such shares.  \nProvided, however, that where the company has alrea dy undergone liquidation \nor insolvency prior to the forfeiture of shares, an y amount due and payable in \nrespect of the shares liable to accordance with the prevailing law.  \n(4) Where any share is forfeited under Sub-section (3), the board of \ndirectors may refund the amount already paid up in respect of the share so \nforfeited and the amount equal to the dividends, if  any attached in respect of \nsuch share, or issue the share to the extent covere d by such amount; and where \nthe amount is to be refunded, it has to be refunded  within three months after the \nforfeiture of share.  \n(5) In the event of failure to make refund within t hree months pursuant \nto sub- section (4), interest chargeable on such am ount after the expiration of \nthat period shall also be paid.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 46  \n(6) The shares forfeited under Sub-section (3) may be sold or otherwise \ndisposed of in such manner as the board of director s may, subject to the articles \nof association, thinks fit.  \n(7) A company which has been making profits for a pe riod of three \nconsecutive years or more may, by a special resolut ion adopted at its general \nmeeting determines that a call may not be made in re spect of certain portion of \nits share capital not called on except in the case of liquidation or insolvency of \nthe company. \n(8)  After a special resolution has been adopted un der Sub-section (6), a \ncall may not be made on the amount of share capital  that is yet to be called on \nas mentioned in that resolution except where the ge neral meeting, by adopting \nanother special resolution, decides to make such ca ll and except in the case of \nliquidation or insolvency of the company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "54", "title": "Payment of amount of shares held jointly : (1) Every partner shall pay the", "content": "amount of call on the shares held jointly in proportion to his /her ownership.  \n(2) Except where there exists a duly executed deed indicating specific \nportion owned by each partner in the shares held pu rsuant to Sub-section (1), \nall the holders of such shares shall be deemed to h ave equal ownership there \non .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "55", "title": "Ownership of shares and debentures : If a dispute arises about the ownership", "content": "of any share or debenture issued by any company, th e person whose name is \nregistered in the share or debenture register maint ained by the company shall, \nunless otherwise proved be regarded as the owner of such share or debenture.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "56", "title": "Power of company to alter its share capital : (1) Subject to the provisions", "content": "contained in its articles of association, any company may, by adopting a special \nresolution at its general meeting, make alteration in its share capital as follows:  \n(a) By increasing its authorized share capital by such amount \nas it thinks expedient by issuing new shares,  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 47  \n(b) By consolidating or dividing all or any of its shar e capital \ninto shares of larger or smaller amount,  \n(c) By canceling the shares which, at the date the adop ting of \nthe resolution in that behalf, have not been taken or agreed \nto be taken by any person or the shares forfeited p ursuant \nto Sub-section (3) of Section 53 and diminishing the  \namount of its share capital by the amount of the sh ares so \ncanceled.  \n(2) When a special resolution for altering the capi tal pursuant to sub- \nsection (1) is adopted, the memorandum of associati on and articles of \nassociation of the concerned company shall be deeme d to have ...... ∝ been \namended to that extent.  \n(3) A submission, accompanied by the prescribed fee s shall be made to \nthe Office for the record of the resolution adopted  pursuant to Sub-section (1) \nand the amendment to the memorandum of association and articles of \nassociation; and the Office shall accordingly recor d the alteration made in the \ncapital of the company and the amendment made to th e memorandum of \nassociation and articles of association and give in formation thereof to the \ncompany within seven days after such submission.  \n(4) A cancellation of shares, if any, made in pursu ance of Clause (c) of \nSub-section (1) shall not be deemed to have been ma de for purposes of the \nreduction of share capital of a company.  \n(5) If a company is required to increase its issued  capital to the extent of \nits authorized capital, it may increase such capita l by adopting an ordinary \nresolution at the general meeting.  \n(6) If a public company is required to increase its  share capital under \nSub-section (5) and issue its shares publicly, it s hall fulfill the procedures \nspecified in this Act and the prevailing law on securities.  \n                                                   \n∝ Deleted by the Some Nepal Act (Amendment) Act, 2064  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 48  \nProvided, however, that in so issuing bonus shares and right shares that they \nmay be subscribed by its existing shareholders and employees only or issuing \nshares pursuant to Sub-section (9), such company shall not be required to fulfill \nsuch procedures.  \n(7) A public company shall publish a notice on the issue of right shares, \nwhich may be subscribed by the existing shareholder s only, in a daily \nnewspaper of national circulation for at least thre e consecutive times prior to \nfifteen days of the issue of such shares.  \n(8) The existing shareholders shall have the first right to subscribed the \nshares issued under Sub-section (7) in proportion t o their respective \nshareholding.  \n(9) Notwithstanding anything contained in Sub-secti on (8), no \nshareholder of a company existing for the time bein g shall have the first right \nover the following shares to be issued by the company:  \n(a) Shares issued by the company for any consideration other \nthan cash,  \n(b) Shares issued to any person under any right or faci lity \nprovided in accordance with the terms of an agreeme nt \nconcluded with the company,  \n(c) Shares issued under an employee share scheme,  \n(d) Shares issued in accordance with an agreement concl uded \nbetween the company and its creditors,  \n(e) Shares existed on converting preference shares into  \nordinary shares or debentures into shares by the company,  \n(f) Shares issued in accordance with an agreement betwe en \nthe concerned parties in the course of management o f the \ncompany, restructuring of its capital or loan or in  the \ncourse of implementation of a restructuring program \nagreed upon between the relevant parties in accorda nce \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 49  \nwith the prevailing law on insolvency or in the cou rse of \nimplementation of a program of conversion of a publ ic \ncompany into another public company.  \n(10) No share capital shall be increased or bonus s hare issued by \nrevaluating the assets of a company other than from  profits made by the \ncompany or funds created out of profits.  \n(11) In issuing shares under this Section, a time l imit of at least thirty-\nfive days shall be given to the existing shareholde rs to subscribe the shares. If \nsuch shareholders fail either to subscribe the shar es or to sell or transfer the \nright to subscribe shares to any one else within th e said time limit or, such \nshares may be sold in any other manner as decided b y the board of directors of \nthe company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "57", "title": "Reduction of share capital : (1) If a company intends to reduce its share", "content": "capital , it may, by  adopting a special resolution  to that effect at its general \nmeeting, reduce its share capital by obtaining approval of the Court and making \nnecessary amendment to or alteration in the memorand um of association and \narticles of association, accordingly.  \n(2) On receipt of approval of the Court pursuant to  Sub-section (1), the \ncompany may reduce its share capital as follows:  \n(a) By reducing the capital to such amount as has been paid \nup where calls for payment of amount on shares are not \nfully paid up,  \n(b) By paying back any   paid-up share capital,  \n(c) By devaluating the face value of shares where the \ncompany has sustained a big loss or suffered a natu ral \ncalamity.  \n(3) Notwithstanding anything contained in subsectio n (2), a company \nwhich has already become insolvent in accordance with the prevailing law shall \nnot reduce its capital pursuant to this Section.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 50", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "58", "title": "Procedures for obtaining approval of Court to reduc e share capital : (1)", "content": "Where a company has adopted a special resolution for reducing its share capital \npursuant to Section 57, it shall make a petition to  the Court for an order \nconfirming the reduction.  \n(2) Where a petition is made pursuant to Sub-sectio n (1), the concerned \ncompany shall, prior to the hearing of such petitio n, publish a public notice in a \ndaily newspaper of national circulation for at leas t three times, setting out the \nvenue and date of hearing on the reduction of share capital of the company.  \n(3) Every person who is entitled to any debt or cla im under the \nprevailing law at the time of commencement of the wi nding up or insolvency \nof a company shall be entitled to submit his/her cl aim and objection to the \nreduction of share capital of the company.  \n(4) The director or company secretary of a company shall, as ordered by \nthe Court, submit to the Court a real and true list  of creditors of the company, if \nany, setting out, inter alias, their names, address es and amount of debt \nrepayable to each of them, at the commencement of h earing of the petition for \nreducing the capital of the company .  \n(5) Irrespective of whether the creditors whose deb ts are yet to be \ndischarged or determined, out of the creditors whos e names are entered on the \nlist submitted pursuant to Sub-section (4), do or do  not consent to the reduction \nof capital in the case where the company admits the  full amount of the debts or \nclaims made by the creditors, or though not admittin g it, agrees to make \nprovision of moneys required to pay such amount and  makes required \nprovision for the same by executing a bond undertak ing to pay the full amount \nwithin a certain date, then the Court may issue ord er confirming the reduction \nof the share capital .  \n(6) In taking action for approval on a proposed red uction of share capital \nwhich involves either the diminution of any liabili ty in respect of unpaid share \ncapital or the paying back to an shareholder of any  amount paid for shares, the \nCourt may, if, having regard to the circumstances a nd available evidence, it \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 51  \nthinks proper so to do, direct that the provisions of Sub-section (3) or (4) shall \nnot apply to any specific creditor.  \n(7) If the list of creditors submitted pursuant to s ubsection (4) is found \nto contain any false statement or omission, the dir ector of the company who \nsubmits such list and the officer who signs such li st shall be liable to \npunishment under this Act.  \n Provided, however, that if the officer who signs s uch list proves that any \nomission or mistake was made without his/her knowledge or immediately when \nhe/she knew such omission or mistake, he gave inform ation to the Court for the \nrectification of such omission or mistake, prior to  the making of an order by the \nCourt under this Section or he exercised all reason able care to avoid such \nomission or mistake, he shall not be liable to that punishment.  \n(8) If the Court is satisfied, with respect to the creditors who under Sub-\nsection (1) are entitled to object to the resolutio n on reduction of capital, that \neither their consent to the reduction has been obta ined or their debts or claim \nhave been discharged or have been determined and ar e at the state of discharge, \nor have been secured, it may make an order confirmi ng the reduction, \nspecifying appropriate alters and conditions.  \n(9) Where the Court makes an order pursuant to Sub- section (8), it may, \nif it thinks proper so to do, order directing that the concerned company, of \nwhich resolution to reduce capital has been co conf irmed, shall, for a specified \nperiods, add to its names the last words thereof th e words “ capital reduced” \nand publish necessary notice with a view to giving information to the general \npublic about the reasons and causes for such reduct ion and other important \ninformation in regard thereto .  \n(10) Where,  pursuant to Sub-section (9) , a compan y is ordered to add  \nto its name the words “capital reduced”, those word s shall, until the expiration \nof the period specified by the Court, be deemed to be an integral part of the \nname of the company.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 52  \n(11) The contents of the terms contained in an orde r issued by the Court, \npursuant to this Section, in the course of confirmi ng a resolution for the \nreduction of capital shall be deemed to have ipso f acto been incorporated in the \nmemorandum of association and articles of association of the company; and the \nmemorandum of association and articles of association shall be deemed to have \nbeen amended to that extent.  \n(12) Any director who knowingly conceals, hides or holds back the \nname of any creditor who, under this Section, is en titled to object to the \nresolution for reducing capital or knowingly prepar es or submits a false \nstatement on the amount of loan or clam or liabilit y or conceals, hides or holds \nback such loan or liability or prepares or causes t o prepare a false statement or \nany officer or employee of the company who abets to  such act shall be liable to \npunishment under this Act.  \n(13) Where the share capital of a company is reduce d pursuant to this \nSection, the director or company secretary of that company shall mention and \nauthenticate that matter in each share certificate issued by such company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "59", "title": "Liability of shareholders in respect of reduced sha re capital: Except as", "content": "otherwise provided for    in this Section, a shareh older of the company, past or \npresent, shall not be liable, in respect of any sha re mentioned in the order issue \nby the Court confirming the reduction of share capi tal, to pay any amount \nexceeding the difference between the amount actuall y paid on the share or the \nreduced amount, id any, which is deemed to have been paid thereon, as the case \nmay be , and the fixed amount of such share.  \nProvided, however, that where the list of creditors  entitled to object to the \nreduction of share capital submitted to the Court o mits any such creditor and, \nafter an order confirming the reduction of capital o f the company has been \nmade, the  company is unable to pay the amount of d ebt of such creditor, the \nshareholder of the company shall be bound to pay th e amount as mentioned in \nSub-section (3) or (4) .  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 53  \n(2) Notwithstanding anything contained in the proviso to Sub-section (1), \nwhere the list submitted to the Court omits the nam e or any claim of a creditor \nbecause of a fault or negligence of his/her own, th e shareholders shall not be \nbound to pay such amount.  \n(3) A person who was a shareholder of a company at the date of issue by \nthe Court of an order confirming the resolution for  reducing the capital of the \ncompany shall be liable to pay an amount not exceed ing the amount which he \nwould have been liable to pay  if the company had u ndergone insolvency and \ncommenced insolvency proceedings on the day immediate ly before the said \ndate.  \n(4) If a company is insolvent, and where an applica tion is made by a \ncreditor whose name is said to be omitted from the list of creditors  submitted \nto the Court , along with the proof of omission of his/her name, the Court may, \nif it thinks fit, settle a list of shareholders who  are liable to pay to the company \nthe amount required for the repayment of loan of su ch creditor and issue an \norder to make calls on shares held by the sharehold ers settled on such list as if \nthey were ordinary contributors in an insolvency  process of the company.  \n(5) Notwithstanding anything contained elsewhere in  this Section, no \nshare holder shall be liable to pay an amount in ex cess of the face value of a \nshare at the time of   the subscription of such share by him/her.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "60", "title": "Directors to be responsible in the case o f loss of  net worth of company:  (1)", "content": "If the net worth of a public company is reduced to half the paid–up capital or \nless than that the directors shall prepare an appro priate strategy for the interest \nof the company and shareholders, as well, within th irty five days of the \nknowledge of this matter, and present a separate re solution thereon at the \ngeneral meeting toe held immediately after the knowledge of such matter.  \nProvided, however, that where approval of the gener al meeting is required to \nimplement such strategy, the extra-ordinary general  meeting shall be called \npromptly.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 54  \n(2) The directors of company who fail to prepare st rategy or to present a \nresolution at the general meeting pursuant to Sub-s ection (1) or who knowingly \npermit the existence of the situation where such me eting is not called shall be \nliable to punishment under this Act.  \n(3) If it is held that the net worth of company has  been reduced as \nmentioned in Sub-section (1) as a result of mala fide  intention or malicious \nrecklessness of any director, the director who commi ts such act shall also be \nliable to pay compensation for the same.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "61", "title": "Prohibition on purchase by company of its own share s:  (1) No company", "content": "shall purchase its own shares (buy-back) or lend mo ney against security of its \nown shares.  \n(2) Notwithstanding anything contained in Sub-secti on (1), in the \nfollowing circumstances, a company may buy back its  shares out of its free \nreserves available for being distributed as dividen ds, by giving information to \nthe Office:  \n(a) Where the shares issued by the company are fully paid up;  \n(b) Where the shares issued by a public company have be en \nlisted in the Securities Board; \n(c) Where the buy-back of shares is authorized by the a rticles \nof association of the concerned company;  \n(d) Where a special resolution has been adopted at the general \nmeeting of the concerned company authorizing the bu y-\nback;  \n(e) Where the ratio of the debt owed by the company is not \nmore than twice the capital and general reserve fun d after \nbuy-back of shares;  \nExplanation\n: For the purposes of this Clause, “debt” \nmeans all amounts of secured or unsecured debts \nborrowed by a company.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 55  \n(f) where the value of shares to be bought back by a co mpany \nis not more than twenty percent of the total paid u p capital \nand general reserve fund of that company; \n(g) Where the buy-back of shares is not in contraventio n of \nthe directives issued by the Office in this respect.  \n(3) A resolution to be presented at the general mee ting pursuant to \nClause (d) of Sub-section (2) shall state the following matters:  \n(a) The reason and necessity for the buy-back of shares;  \n(b) A statement of the evaluation of possible impacts o f the \nfinancial situation of the concerned as a result of  the buy-\nback of shares,  \n(c) The class and number of shares intended to be bough t \nback;  \n(d) The maximum or minimum amount required to buy back \nshares as referred to in Clause (c) and financial s ource of \nsuch amount; \n(e) The time limit for the buy-back of shares; \n(f) The mode of the buy-back of shares;  \n(g) Such other necessary matters as specified by the Of fice \nand as required to be disclosed under the prevailing law, in \nrespect of the buy-back of shares.  \n(4) Where a special resolution as referred to in Su b-section (3) is \nadopted by the general meeting, the concerned compa ny may buy back its \nshares in any of the following manners within a per iod of twelve months of the \nadoption of that resolution:  \n(a) Purchasing from the stock exchange;  \n(b) Purchasing from the concerned employee of the compa ny \nthe shares allotted to him/her,  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 56 \n(c) Purchasing from the existing shareholders on a \nproportionate basis.  \n(5) Where a company buys back its own shares pursua nt to Sub-section \n(4), it shall file with the Office a return contain ing the number of shares bought \nback, amount paid for the same and other necessary details within thirty days of \nthe date of such buy-back.  \n(6) There shall be established a separate capital r edemption reserve fund, \nto which a sum equal to the nominal value of the sh ares bought back pursuant \nto Sub-section (4) shall be transferred; and the am ount of such fund shall be \nmaintained as if it were the paid-up capital .  \n(7) Where a company buys back its shares pursuant t o Sub-section (4), it \nshall cancel the shares so bought back within one h undreds twenty days of the \ndate of such buy-back .  \n(8) Once a company buys back any class of shares pu rsuant to this \nSection, the company shall not re-issue the shares of that class, except for the \nissue of bonus shares or payment of its liability, prior to the expiration of two \nyears after such buy-back.  \n(9) Notwithstanding anything contained elsewhere in  this Section, no \npublic company shall buy back its shares in a manne r that such minimum \nnumber of shareholders or minimum paid–up capital a s required to be \nmaintained by that company becomes less or lower.  \n(10) Other conditions where a company cannot buy ba ck its shares and \nother terms required to be complied with in the buy ing back of its shares shall \nbe as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "62", "title": "Prohibition on providing loan or financial  assista nce by company to", "content": "purchase its own shares : No company shall provide any loan or financial \nassistance of any kind to any person for purchasing  its own shares or the shares \nof its holding company or getting entitlement too such shares in any manner.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 57  \nProvided, however, that nothing contained in this S ection shall prevent a \ncompany from providing loans to any employees of th e company to purchase \nthe fully paid up shares of that company or its hol ding company or acquire \nownership over such share s in any manner, under a scheme of selling shares to \nits employees.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "63", "title": "To obtain approval for commencing business:  (1) No public company", "content": "incorporated under this Act shall commence its busi ness without obtaining the \napproval to carry on its business.  \n(2) A public company shall make an application, alo ng with the \nevidence showing the full payment of calls on the s hares, out of the amount of \nshares undertaken to be subscribed by its prompters , to the office for getting \napproval pursuant to Sub-section (1) \n(3)  Where an application is made pursuant to Sub-s ection (2) and it so \nproved that calls on the shares, out of the amount of shares undertaken to the \nOffice shall grant approval for carrying on the business.  \nProvided, however, that if the amount paid up on sh ares is less than the amount \nmentioned in Sub-section (1) of section 11, the Off ice shall not grant such \napproval. \n(4) without obtaining the approval to commence busin ess pursuant to \nSub-section(2), there shall not be carried out any act of publishing the except \nthose acts such as convening the extraordinary gene ral meeting, meeting of the \nboard of directors and management of the company.  \n(5) Notwithstanding anything contained in Sub-secti on (2), where in the \ncase of a company carrying on any specific business , the competent regulatory \nbody empowered to regulate such business under the prevailing law has, while \ngranting a license, specified any terms and conditi ons to be complied with prior \nto the commencement of such business, no approval t o commence business \nshall be granted unless and until an evidence showing the compliance with such \nterms and conditions is submitted.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 58  \n(6) Notwithstanding anything contained elsewhere in  this Section, a \nprivate company may commence its transactions immedia tely upon receipt of \nthe certificate of registration with the Office.  \nProvided, however,  that where an approval is to be  obtained from the \nconcerned body pursuant to the prevailing law to ca rry on any specific \ntransactions, the company shall commence its transa ctions only after obtaining \nsuch approval.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "64", "title": "Prohibition on issue or sale of shares at a discoun t:", "content": "(1) A company shall not \nissue or sell its shares at a discount. \n(2) Notwithstanding anything contained in Sub-secti on(1), a company \nmay, on the following conditions, issue or sell sha res at a discount by adopting \na special resolution at the general  meeting to tha t effect, not being less than the \npercentage specified in that resolution:  \n(a) In issuing or selling shares pursuant to a capital \nrestructuring scheme of the company,  \n(b) In issuing or selling shares pursuant to a scheme o f \nconverting loans borrowed by the company into share s \nwith the consent of creditors;  \n(c) In issuing or selling shares pursuant to an employe e share \nscheme;  \n(d) In issuing shares on such other conditions as appro ved by \nthe   Office.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "65", "title": "Preference shares", "content": ": (1) A company may issue preference shares as provided for \nin   this   Act, memorandum of association or articles of association.  \n(2) Except as provided in the articles of associati on, no shares issued \npursuant to Sub-section (1) shall be converted into ordinary shares.  \n(3) In issuing preference shares pursuant to Sub-se ction (1), the \nfollowing maters, inter alia , shall be disclosed: \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 59  \n(a) Whether preference is given to receive dividends ag ainst \nordinary shares; \n(b) Percentage of dividends receivable by preference \nshareholders; \n(c) Whether dividends get cumulated every year (cumulat ive) \nor profits are distributed only in a year wherein p rofit is \nmade (non-cumulative); \n(d) Whether preference is given while paying amount of share \nin the event of liquidation of company; \n(e) Whether voting right is attached there to;  and if voting \nright is attached, whether such right is available only in the \ncase of preference share or also in other matters;  \n(f) Whether voting right is available also in other mat ters \npursuant to Clause (e) , the proportion to which su ch right \nis exercisable;  \n(g) Whether preference shares can be converted into ord inary \nshares;  \n(h) Whether the amount of preference shares can be rede emed \n(redeemable) or cannot be redeemed (irredeemable) a fter a \ncertain period;  \n(i) Whether, in redeeming preference shares, premium is \npayable on redemption. \n(4) Where any redeemable shares are issued, the sha res shall not be \nredeemed unless they are fully paid.  \n(5) No amount of preference shares shall be redeeme d except out of \nprofits which would otherwise be available for divi dend  or out of the proceeds \nof a fresh issue of shares made by the company for the purposes of the \nredemption.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 60  \n(6) Where a premium is payable on the redemption of  any redeemable \npreference shares, there shall be provided for a se parate fund out of the profits \nof the company or out of the company’s shares premiu m account, for the \npurposes of redemption of such shares.  \n(7) Except in cases where any redeemable preference  shares are \nredeemed out of the proceeds of a fresh issue of sh ares pursuant to sun-section \n(5) , while redeeming preference shares pursuant to  this Act, a capital \nredemption reserve account shall be established and  a sum equal to the nominal \namount of the shares redeemed shall be transferred to that account, out of \nprofits which would otherwise have been available for dividend.  \n(8) The capital redemption reserve account establis hed pursuant to Sub-\nsection (7) shall be maintained as if it were the paid–up capital.  \n(9) After the completion of the redemption of any p reference shares \nredeemed pursuant to this Section, such shares shal l be deemed to have, ipso \nfacto , been cancelled.  \n(10) A company shall while redeeming any preference  shares, follow \nsuch terms and  procedures as provided by the artic les of association of the \ncompany, subject to this Section; and such redempti on of preference shares \nshall not be taken as reducing the amount of author ized share capital of the \ncompany.  \n(11) Where a company has redeemed or is about to re deem any \npreference shares, it shall have power to issue new  shares up to the nominal \namount of the shares so redeemed or to be redeemed.  \n(12) Where a company has redeemed any preference sh ares, the \ncompany shall give information thereof to the Office  within one month of such \nredemption; and on receipt of such information, the  Office shall record such \ninformation in the company register.  \n(13) Notwithstanding anything contained elsewhere i n this Section, a  \ncompany may issue new shares to its shareholders as fully paid bonus shares, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 61  \nout of the capital  redemption reserve funds establ ished pursuant to Sub-section \n(7).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "66", "title": "Restriction on minor and person disqualified under law to make contract", "content": "to be promoter : (1) A minor who has not   attained the age of six teen years \nand a person who is not qualified to make contract under the law shall not be \neligible to become the promoter of a company.  \nProvided, however, that this Section shall not be d eemed to prevent a minor or \na person who is disqualified under the law to make contract from acquiring the \ntitle to the shares of a company subscribed by the promoter, by virtue of \nsuccession or operation of law.  \n(2) Where any minor or any person who is disqualifi ed under the law to \nmake contract is to purchase or sell any shares or debentures of any company, \nthe father, mother or husband or wife or legally ap pointed protector or guardian \nof such person shall do so.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 5", "title": "Chapter 5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "67", "title": "General meetings of company : (1) The general meetings of a company shall", "content": "be as follows.  \n(a) Annual general meeting, and  \n(b) Extra-ordinary general meeting.  \n(2) A public company shall send a notice specifying  the place, date and \nagenda of meeting to every shareholder at the addre ss supplied by that \nshareholder to the company, in advance of at least twenty one days to hold the \nannual general meeting, and in advance of at least fifteen days to hold the \nextra- ordinary general meeting .  A notice thereof  shall also be published at \nleast twice in a national daily newspaper.  \nProvided, however, that while calling any general m eeting which has been \nadjourned, if such meeting is not transacting any n ew agenda, a notice of that \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 62  \nmeeting published in a national daily newspaper in advance of at least seven \ndays shall be deemed to have been duly given.  \n(3) No decision shall be taken in any general meeti ng on any matter \nwhich has not been notified in advance pursuant to Sub-section (2), except in \nthe following circumstances: \n(a) Except as otherwise provided in the other sections of this \nAct, If the shareholders representing sixty seven p er cent \nof the total shares of the company who are entitled  to vote \nat the general meeting, attend in person or by prox y and \nvote in favor of taking a decision on any matter,  \n(b) If the matter was already notified for being transa cted in \nany general meeting which has been adjourned.  \n(4) Except in cases where the Office gives prior ap proval to hold the \ngeneral meeting elsewhere, the general meeting of a  public company shall be \nheld either at the district where the registered of fice of such company is \nsituated or at such place adjoining to the district  of registered office as is \nconvenient to most shareholders .  \n(5) A list indicating the name, address of the existing shareholders of the \ncompany and the number of shares held by them shall  be kept at the meeting \nvenue for inspection by the shareholders.  \n(6) The matters included in the agenda sent along w ith a notice of the \ngeneral meeting shall be discussed and decided first at that meeting.  \n(7) The person chairing the general meeting may adj ourn the meeting as \nrequired. Any matter which is notified, pursuant to  this Act, before or after the \nday of holding the adjourned general meeting may be  discussed and decided in \nsuch adjourned meeting.  \n(8) The original meeting and the adjourned meeting shall have the same \npowers. A resolution adopted at the adjourned meeti ng shall be deemed to be \nadopted on the date of holding that adjourned meeting.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 63  \n(9) Where any corporate body has purchased shares i n a company, a \nperson appointed by such corporate body shall be en titled to attended and vote \nat the general meeting of the company, on behalf of such body.  \n(10) The proceedings at any general meeting shall n ot be void or invalid \nmerely for reason of the accidental omission to giv e notice to any shareholders \nof any listed company or the non-receipt by any sha reholder of notice sent at \nthe address which he has supplied to such company.  \n(11) Notwithstanding anything  contained elsewhere in this Section, \nmatters pertaining to the general meeting of a priv ate company and procedures \nthereof shall be as provided in the articles of ass ociation or the consensus \nagreement.  Failing such provision, the provisions of this Act shall apply.  \n(12) Other provisions relating to the procedures of  general meeting shall \nbe as contained in the articles of association of a company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "68", "title": "Directors required to be present : Every director of a company shall be", "content": "present in the general meeting as far as possible.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "69", "title": "Legality of meeting : Before every general meeting commences, the", "content": "shareholders present therein shall ascertain  wheth er it has been convened in \naccordance with this Act and the articles of associ ation; and a general meeting \nshall be deemed to have been duly called even if an y other law has not been \nobserved with respect thereto, provided a notice ha s been sent to all \nshareholders pursuant to Sub-section(2) of Section 67 and the meeting attended \nby the required quorum as referred to in Section 73 agrees to hold it .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "70", "title": "Cases where attendance or voting in meeting is rest ricted : (1) No person", "content": "shall be entitled to attend and vote in any general  meeting, in the capacity of a \nshareholder, either in person or by proxy on any di scussion to be held in \nrespect of any terms and conditions entered into or  to be entered into between \nhim/herself and the company.  \n(2) No director or his/her partner or his/her proxy  shall be entitled to \nvote on any discussion to be held at any General Me eting in respect of the \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 64  \nresponsibility for any act done or omitted to be do ne or done wrongfully by  \nhim/her or in respect of his/her own appointment, d ismissal, transfer or \nconfirmation, with respect to the provision of , or  reduction or increment in \nremuneration, allowance or bonus or in respect of a ny agreement, contract or \narrangement regarding his/her employment or anythin g in which his/her \ninterest or concern is involved.  \n(3) Any shareholder who has not paid calls on the s hares shall not be \nentitled to attend and vote in the general meeting.  \n(4) Where any shareholder appoints a director of th e concerned \ncompany as his/her proxy pursuant to Sub-section(2)  of Section 71, such \ndirector shall not be entitled to vote in the gener al meeting ,as a proxy  of any \none , on any matter in which his/her interest or co ncern is involved or on the \nmatter of his/her appointment.  \n(5) Notwithstanding anything contained in this Act or the prevailing law, \nwhere a bank or financial institution incorporated under the prevailing law, \nwhich institutes legal action against a shareholder , who has borrowed a loan \nfrom such bank or financial institution against the  pledge or security of the \nshares held by him/her, for his/her default in repa ying the loan, writes to the \nconcerned company to prevent him/her from exercisin g voting right in respect \nof shares, then the company shall prevent such shar eholder  from exercising \nvoting right in respect of the shares held by him/h er for a period until he/she \nrepays the loan.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "71", "title": "Right to vote in general meeting : (1) Except as otherwise provided in this Act", "content": "or the articles of association of a company, only t he person whose name is \nregistered as a shareholder in the shareholder regi ster shall, subject to Section \n70, be entitled to attend the general meeting and c ast votes at the rate of one \nvote for each share held by him/her.  \n(2) Except in cases where the articles of associati on of a company \nprohibit the proxy of a shareholder from exercising  the right to vote, any \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 65  \nshareholder may, subject to this Section , appoint another person as his/her \nproxy to attend the general meeting and vote instead of him/herself.  \n(3) Subject to Sub-section (1) or (2) , where a sha reholder who is \nentitled to vote is not able to personally attend t he meeting, he/she may appoint \na proxy to vote in his/her stead, by an instrument of proxy  executed in the \nprescribed format and signed by him/her and the pro xy so appointed shall be \nentitled to attend or vote in the meeting , subject  to the provisions contained in \nSection 72.  \n(4) where two or more persons jointly hold any shares, only the vote cast \nor instrument of proxy executed by the partner appo inted by such partners or \nby the proxy appointed by that partner pursuant to Sub-section (2),and failing \nsuch appointment of any partner, by the partner who se name  appears first in \nthe serial order, out of the  partners, in the shar eholder register maintained \npursuant to Section 46 shall be valid.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "72", "title": "Provision on voting in election of director : (1) Except as otherwise provided", "content": "in the articles of association, on a poll in electi on of directors, every \nshareholder shall be entitled to cast such number o f votes as may be set after \nmultiplying the number of shares held by him/her by  the number of directors  \nto be appointed; and the director who casts such votes may cast all his/her votes \nfor a single candidate or may cast votes in a manne r that his/her votes are \ndivided for more than one candidate as indicated by him/her.  \n(2) A corporate body entitled to appoint a director  pursuant to this Act \nor articles of association may appoint directors in  proportion too its \nshareholding, and in such a case, it shall but be e ntitled to cast vote in the \nelection.  \nProvided, however, that a corporate body which is n ot able to appoint even a \nsingle director in proportion to the number of shar es and the total number of \ndirectors or which fails to appoint a director in e xercise of the power conferred \nby this Sub-section may, like other shareholder, ta ke part in the election of \ndirectors representing shareholders, cast vote or f ile candidacy up to the \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 66  \nnumber of directors that can be elected in proporti on to the shares held by that \nbody in such election.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "73", "title": "Quorum : (1) A quorum for the general meeting of a private  company shall be", "content": "as specified in the articles of association of such company.  \n(2) Unless the articles of association of a public company provides for a \nlarger number for the quorum, no proceedings of the  meeting of the public \ncompany shall be conducted unless at least three sh areholders of the total \nshareholders, representing more than fifty per cent  of the total number of \nallotted shares of that company, are present either in person or by proxy.  \n(3) Where a meeting cannot be held because of quoru m as referred to in \nSub-section (2), and the meeting is called next tim e by giving a notice of at \nleast seven days, nothing shall prevent the holding  of such a meeting if at least \nthree shareholders, representing twenty five percen t of the total number of \nallotted shares of the company, are present either in person or by proxy.  \n(4) Notwithstanding anything contained elsewhere in  this Section, in the \ncase of a company incorporated under the proviso to  Sub-section (2), of \nSection 3 or a company incorporated under Sub-secti on(1) of Section 173, the \npresence of three shareholders as mentioned in Sub- section(2) or (3) shall not \nbe mandatory.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "74", "title": "Discussion and decision : (1) A general meeting shall be chaired by the", "content": "Chairperson of board of directors and, in his/her a bsence, by the person \nnominated by the directors from amongst themselves.  \n(2) Every matter to be discussed in a general meeti ng shall be presented \nin the form of resolution. The chairperson of the m eeting shall declare whether \na resolution has been adopted or not. \n(3) The opinion of majority of the shareholders pre sent in the meeting \nshall be deemed to be the decision of that meeting on every matter put to the \nvote. Such voting may be taken in such manner inclu ding a show of hands, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 67  \nvoice voting, division of shareholders in groups or  poll (use of ballet paper) as \nwell as other appropriate method as prescribed by the Chairperson.  \nProvided, however, that in the case of a special re solution, the resolution shall \nbe deemed to have been adopted by the meeting only if the shareholders \nrepresenting seventy five per cent  shares out of t he shareholders present in the \nmeeting vote in favour of the resolution.  \n(4) If the votes are evenly divided for and against  at a general meeting, \nthe Chairperson of the meeting may exercise the casting vote.  \nProvided, however, that the Chairperson shall not b e deprived of the right to \nvote in the capacity of shareholder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "75", "title": "Minutes to be kept : (1) Every company shall keep minutes of the proce edings", "content": "of general meeting, by making entries thereof in a s eparate book; and the \nminutes shall be signed by the chairperson of the me eting concerned and by the \ncompany secretary, if any. In the case of a company  which has no company \nsecretary, the minutes shall be signed by the Chair person of the meeting \nconcerned and by a representative of shareholders a ppointed by a majority of \nthe general meeting.  \n(2) While keeping the minutes as referred to in Sub -section (1), matters \nsuch as the manner in which the notice of the meeti ng was issued, the number \nof shareholders present, the percentage of  represe ntation of the total shares , \nthe result of voting, if any, shall all be set out in the minutes.  \n(3) The minutes set down pursuant to this Section sh all be sent to the \nshareholders within thirty days of the holding of the general meeting.  \n Provided, however, that if any company publishes t he minutes in a \nnational daily newspaper, it need not send the same to the shareholders.  \n(4) The minutes of proceedings of the general meeti ng kept pursuant to \nSub-section (1) shall be kept at the registered off ice of the company. If any \nshareholder wishes to inspect such minutes during o ffice hours, the company \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 68  \nsecretary or such other employee as designated by t he company shall allow \nsuch inspection.  \n(5) If any shareholder wishes to get a copy of any minutes of the general \nmeeting, the company shall provide such copy by col lecting such  fees as \nspecified by its articles of association.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "76", "title": "Annual  general meeting : (1) Every public company shall hold its first ann ual", "content": "general meeting within one year after it is permitte d to commence its business, \nand thereafter it shall hold the annual general mee ting every year within six \nmonths after the expiry if its financial year. \n(2) If any public company fails to call the annual general meeting even \nwithin three months after the expiry of the time-li mit referred to in Sub-\nsection(1), the office may give direction to call t he annual general meeting of \nsuch company. \n(3) If  the company fails to ca;; the annual genera l meeting even within \nthree months after the receipt of the direction as referred to on Sub-section(2), \nany shareholder may make a petition, setting out th e matter, to the court. Where \nsuch petition is made, the Court may either cause t o hold the annual general \nmeeting or issue any other appropriate order. \n(4) Notwithstanding anything contained in Sub-secti ons (1) and (2) of \nsection 73, the shareholders present in the general  meeting called pursuant to \nthe order of the court under Sub-section (3) shall be deemed to be a quorum.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "77", "title": "Matters to be presented and decided in annual gener al meeting : (1) The", "content": "directors shall present the annual financial statem ents as audited, auditor’s \nreport and director’s report at the annual general meeting of a public company.  \n(2) If the shareholder or shareholders representing  at least five per cent \nof the total number of votes shall so desire, he/th ey may, by submitting an \napplication to the directors prior the issue of a n otice under Sub-section (2) of \nSection 67, cause any matter to be presented at the  annual general meeting for \ndiscussion and decision. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 69  \n(3) At least twenty one days prior to the holding o f the annual general \nmeeting, every public company shall make arrangement  so that the \nshareholders can inspect and obtain copies of the a nnual financial statement, \ndirectors’ report and auditors’ report as referred to in Section 84 and publish a \nnotice in  a national daily newspapers for information thereof. \n(4) Information of the statements and reports as re ferred to in Sub-\nsection (3) may also be disseminated through electr onic communication media, \nas per necessity. \n(5) If any shareholder makes a request for a copy o f the annual financial \nstatement, directors’ report and auditor’s report a s referred to in Sub-section (3), \nthe company shall provide a copy of such reports or  statements to such \nshareholder. \n(6) Except as otherwise provided in this Act, matte rs of distribution of \ndividends to shareholders, appointment pf directors  and their remuneration, \nappointment of auditor and his/her remuneration of such other items as \nrequired by this Act or the articles of association  to be decided by the annual \ngeneral meeting of the company can be presented at the decided by the annual \ngeneral meeting of the company can be presented at and decided by that \nmeeting.  \nProvided, however, that on the rate of dividends to  be distributed to the \nshareholders shall be made in a manner to exceed th e rate of such dividends \nfixed by the board of directors.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "78", "title": "Report to be submitted to Office", "content": ": Every public company shall prepare a \nreport indicating the following matters and submit the same to the Office in \nadvance of at least twenty one days before the hold ing of the annual general \nmeeting. Such report has to be approved by the boar d of directors and certified \nby the auditor of the company.  \n(a)  The total number of the shares allotted,  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 70  \n(b) Number of fully paid up and unpaid shared out of th e \nallotted shares out of the allotted shares, \n(c) Particulars of  director,  managing  director,  aud itor,  \nexecutive chief and manager of the company, and amo unt \nof remuneration,  allowance  and facility paid to them, \n(d) The names of individuals or corporate bodies subscr ibing \nfive percent of more of the paid up   capital of th e \ncompany, and details of shares or debentures held i n their \nnames, \n(e) The total proceeds of the sale of shares, and parti culars of \nthe new shares and debentures issued and raised by the \ncompany in the financial year concerned, \n(f) The amount due and payable by the director or subst antial \nshareholder to his/her close relative to the company, \n(g) The details of payment made or to be made against t he \nsale of shares or for any other matters, \n(h) The amount of loans borrowed from banks and financi al \ninstitutions and of principal and interest due and payable, \n(i) The amount claimed to be receivable by the company or \npayable by the company to any other person to detai ls of, \nlawsuits, if any , ongoing in this respect, \n(j) The number of expatriate employees engaged in the \nmanagement of the company and at other levels, and \nremuneration, allowances and facilities paid to them, \n(k) The number of expatriate employees engaged in the \nmanagement of the company  and at other levels, and  \nremuneration, allowances and facilities paid to them,  \n(l) Where any agreement has been entered into between t he \ncompany and any foreign body or person on investmen t, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 71  \nmanagement or technical services or other matter fo r a \nperiod of more than one year, particulars thereof a nd the \nparticulars of the dividend, commission, fee, charge  and \nroyalty, as well paid under such  agreement in the financial \nyear concerned,  \n(m) A statement of the management expenditures of the \ncompany in a financial year, \n(n) The amount of dividends yet to be claimed buy the \nshareholders,  \n(o) A declaration that the company has fully observed t his Act \nand the prevailing law,  \n(p) Other necessary matters.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "79", "title": "Preparation of documents for annual general meeting :", "content": "At least twenty one \ndays prior to the holding of the annual general mee ting, every public company \nshall prepare the annual financial statements, dire ctors report, auditor’s report \nto be discussed in the meeting, the report prepared under Section 78 and the \nresolutions to be presented in the meeting and arrange to so keep the same at its \nregistered office that the shareholders can inspect  them; and  if any shareholder \nmakes and application for a copy thereof, a copy th ereof shall be provided to \nhim/her.  \n Provided, however, that the resolutions to be pres ented in the meeting as \nspecial resolution shall be sent, along with a noti ce of the meeting, at the \naddress of the shareholder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "80", "title": "Return of annual general meeting to be forwarded to  Office", "content": ": (1) Every \npublic company shall, within thirty days of the hol ding of the annual general \nmeeting, forward to the Office a return indicating the number of shareholders \npresent in the meeting, a copy of the annual financ ial statement, director’s \nreport and auditor’s report and resolution adopted by the meeting.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 72  \n(2) Except as otherwise provided in this Act, every  private company \nshall submit a copy of the annual financial stateme nt certified by the auditor to \nthe Office within six months of the completion of its financial year.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "81", "title": "Fine to be imposed in case of failure to submit ret urns : (1) Any return,", "content": "notice or information required to be provided by th e company to this Office or \ninformation required to be provided by the officer or shareholder to the \ncompany pursuant to this Act shall be provided by t he director of the company \nor the officer or shareholder who has the duty to p rovide such return, notice or   \ninformation to the Officer or the company, as the c ase may be, within the time \nlimit, if any, prescribed by this Act for the provis ion of such return, notice or \ninformation.  \n(2) The following director of a company or its offi cer who is in default \nin providing the return, notice, information or rep ly as referred to in Section \n♣51, 78, 80, 120, 131 or 156  within the time limit as referred to in Sub-section  \n(1) shall be punished by the Registrar with fine, as follows:  \n(a) A fine of one thousand rupees if the paid up capita l of the \ncompany is up to two million five hundred thousand \nrupees, a fine of two thousand rupees if the paid u p capital \nof the capital is up to often million rupees, and a  fine of \nfive thousand rupees if the paid up capital of the company \nis more than ten million rupees, for a period not e xceeding \nthree months after the expiry of the time limit;  \n(b) A fine of one thousand five hundred rupees if the p aid up \ncapital of the company is up to two million five hu ndred \nrupees, a fine of three thousand rupees if the paid  up \ncapital of the capital is up to ten million rupees,  and a fine \nof seen thousand rupees if the paid up capital of t he \ncompany is more than ten million rupees, for and \n                                                   \n♣ Amended by the Some Nepal Act (Amendment) Act, 2064  \n \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 73  \nadditional period not exceeding three months after the \nexpiry of the time limit as referred to in Clause (a); \n(c) A fine of two thousand five hundred rupees if the p aid up \ncapital of the company is up to two million five hu ndred \nthousand rupees, a fine of five thousand rupees if the paid \nup capital of the capital is up to ten million rupe es, and a \nfine of  ten thousand rupees if the paid up capital  of the \ncompany is more than ten million rupees, for an add itional \nperiod not exceeding six months after the expiry of  the \ntime limit as referred to in Clause(b); \n(d) A fine of five thousand rupees, for each year, if t he paid \nup capital of the company is up to two million five  \nhundred thousand rupees, a fine of ten thousand rup ees , \nfor each year, if the paid up capital of the capita l is up to \nten million rupees, and a fine of twenty thousand r upees, \nfor each year, if the paid up capital of the company is more \nthan ten million rupees, in cases where even the ti me limit \nas referred to in Clause (c)  has also expired.  \n(3) In the case of a company not distributing profi ts which is in default \nin providing such statement, in formation or notice  within the time limit as \nreferred to in Sub-section (1), the director or off icer of such company shall be \nliable to the same fine as is imposable on a compan y of which paid up capital is \nup to ten million rupees.  \n(4)Any director, office or shareholder who is liabl e to pay the fine as \nreferred to in Sub-section (2) shall pay it too the  Office and submit to the \nOffice or the concerned company such returns as required to be forwarded.  \n(5) In calculating the period of expiration of the time limit pursuant to \nSub-section (2), it shall be calculated from the da te of commencement of this \nAct.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 74  \n(6) Any director, officer or shareholder of a compa ny who is in default \nin providing such other statement, notice or inform ation as is required to be \nforwarded to the Office pursuant to this Act shall be punished with a fine of \ntwo hundred rupees for every month, after the expir ation of one month of the \ndate of expiry of the time limit within which such s tatement, notice or \ninformation is required to be provided.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "82", "title": "Extra-ordinary general meeting : (1) The board of directors of a company", "content": "may convene an extra-ordinary general meeting if it deems necessary.  \n(2) If, in the course of examining the account of a company, it is deemed \nnecessary to call an extra ordinary general meeting  for any reason, the auditor \nmay request the board of directors to call such mee ting; and if the board of \ndirectors fails to call the meeting accordingly, th e auditor may make an \napplication, setting out the matter, too the Office ; and if an application is so \nmade, the Office may call the extra-ordinary general meting of the company.  \n(3) If the shareholders holding at least ten percen t shares of the paid–up \ncapital of a company or at least twenty five per ce nt shareholders of the total \nnumber of shareholders make an application, setting  out the reasons therefore, \nto the registered office of the company for calling  an extra-ordinary general \nmeeting of the company.  \n(4) If the board of directors does not call the ext ra-ordinary general \nmeeting within thirty days from the date on which a n application is made \npursuant to Sub-section (3), the concerned sharehol ders may make a petition to \nthe Office setting out the matter; and if such peti tion is made, the Office may \ncause to call such meeting.  \n(5) If the Office deems necessary to call an extra-o rdinary general \nmeeting in view of the findings of any inspection o r investigation or for any \nothers reason, it any itself call or cause there bo ard of directors to call such \nmeeting.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "83", "title": "Special resolutions to be presented : Special resolutions shall be presented in", "content": "the general meeting of a company for decision on the following matters:  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 75  \n(a) Increasing the authorized capital of the company,  \n(b) Decreasing or altering the share capital of the company, \n(c) Altering the name or main objectives of the company,  \n(d) Amalgamating one company into another company,  \n(e) Issuing bonus share, \n(f) Buying back of own shares by the company,  \n(g) Selling shares at a discount, \n(h) Converting a private company into a public company or vice versa ,  \n(i) Such other matter in respect of which the company i s required by this \nAct or the articles of association to adopt a special resolution.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "84", "title": "Provisions on sending abstract of financial stateme nt to shareholders : (1)", "content": "Notwithstanding anything contained elsewhere in thi s Act, a company listed in \nthe stock exchange shall not be required to send th e annual financial statement \nand director’s report to its shareholders or debenture-holders  \nProvided, however, that an abstract of financial st atement prepared pursuant to \nSub-sections (2) and (3) shall be sent to every shareholder along with the notice \nof annual general meeting.  \n(2) The abstract of financial statement required to  be sent pursuant to the \nproviso to Sub-section (10) shall be prepared on th e basis of the annual \nfinancial statement of the company and the director ’s report. The   format of \nsuch statement shall be as specified by the Office based on the suggestions of \nthe body specified to set accounting standards under the prevailing law.  \n(3) The abstract of financial statement shall conta in, inter alia , the \nflowing matters:  \n(a) Matter indicating that the abstract of annual finan cial \nstatement is only an abstract of the annual financi al \nstatement of the company and their director’s report, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 76  \n(b) An opinion of the company’s auditor as to whether o r not \nthe abstract of annual financial statement is in co nsonance \nwith the annual financial statement of the company and the \ndirector’s  report and whether or not the abstract is \nconsistent with the format specified pursuant to th is \nSection,  \n(c) Matter as to whether or not the auditor has made an y \nremarks about the annual financial statement of the  \ncompany and, if such remarks have been made, full d etails \nof such remarks and such materials as required to \nunderstand such remarks,  \n(d) In cases where the auditor has mentioned in his/her  report \nanything about the inadequacy of the accounts and \naccounting returns or about the company’s accounts not \nbeing verifiable with the records and returns maint ained \nby the company or about the non-receipt of any such  \ninformation and explanation as sought, full details thereof.  \n(4) Instead of sending the abstract of annual finan cial statement to the \nshareholders at their personal addresses pursuant t o Sub-section (1), the \ncompany many publish it at least twice in a nationa l daily newspaper at the \ntime of publishing the notice of meeting.  \n(5) In the event of publication of the abstract of annual financial \nstatement pursuant to Sub-section (4), there shall not be required to send the \nabstract at the personal addresses of shareholders.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "85", "title": "Registration number to be mentioned", "content": ": A company shall mention its \nregistration number in all such reports, statements , records or other documents \nas required to be submitted by it to the Office for the purposes of this Act.  \n \n \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 77", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 6", "title": "Chapter 6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "86", "title": "Board of directors and number of directors : (1) The appointment and number", "content": "of directors of a private company shall be as provi ded in its articles of \nassociation.  \n(2) Every public company shall have a board of dire ctors consisting of a \nminimum of three and a maximum of eleven directors.  \n(3) In forming the board of directors pursuant to Su b-section (2), at least \none independent director,   in the case of the numb er of directors not exceeding \nseven, and at least two independent directors, in t he case of the number of \ndirectors exceeding seven, shall be appointed from amongst the persons who \nhave the knowledge as prescribed in the articles of  association of the company \nand gained knowledge and experience in the subject related with the business \nof the company concerned.  \n(4) Any one director selected by the directors from  amongst themselves \nshall be the Chairperson of the board of directors.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "87", "title": "Appointment of directors : (1) The directors of a company shall be appointed", "content": "by the general meeting of the company, subject to t he provisions contained in \nSection 89 and the articles of association.  \nProvided however, that:  \n(1)  The directors shall be appointed by the promot ers pending \nthe holding of the first annual general meeting of the \ncompany.  \n(2)  If the office of any director appointed by the  annual general \nmeeting is vacated for any reason, the board of dir ectors \nshall appoint another director in that vacancy.  \n(2) Notwithstanding anything contained in Sub-secti on (1), in the case \nof a company any shares in which a corporate body h as subscribed, the \ncorporate body may appoint a director in proportion  of the total number of \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 78  \ndirectors of the company and the number of shares s ubscribed by such  body \nand also an alternate director to attend and vote i n a meeting of the board of \ninstead of every such director in cases where such director will not be in a \nposition to attend the meeting of the board for any reason.  \n(3) Where any director appointed pursuant to Sub-se ction (2) is not able \nto attend a meeting of the board of directors, such  director shall give \ninformation thereof to his/her alternate director a nd the board of directors. In \nsuch case, the alternate director shall be entitled  to attend, and vote in, the \nmeeting of the board of directors.  \n(4) Except in the case referred to in Sub-section ( 1), any alternate \ndirector appointed pursuant to Sub-section (2) shal l not be entitled to attend, \nand vote in , a meeting of the board of directors.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "88", "title": "Shares qualification of director : If the articles of association of a company", "content": "specify any number of shares required to be held by  a person for his/her \nappointment as director of the company, the person who becomes director shall \nhold such number of shares. Failing any provision s pecifying such number of \nshares, any such person shall hold at least one hundred shares.  \n Provided, however, that any director who is appoin ted pursuant to Sub-\nsection (3) of Section 86 and  Sub-section (2) of S ection 87 shall not be \nrequired to hold such shares.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "89", "title": "Circumstances where one is disqualified to be appoi nted to, or continue to", "content": "hold, office  of director:  (1) Any of the following persons shall not be elig ible \nto be appointed to the office of director:  \n(a) Who is below Twenty one  years of age, in the case of a \npublic company;  \n(b) Who is of unsound mind or is insane; \n(c) Who is a declared insolvent and a period of five ye ars has \nnot lapsed;  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 79  \n(d) Who is convicted of an offense of corruption or of an \noffense involving moral turpitude.  \nProvided, that in the case of a private company, a period of \nthree years has not lapsed from the date of such sentence,  \n(e) who is convicted of an offense of theft, fraud, for gery or \nembezzlement or misuse of goods or funds entrust to \nhim/her, in an authorized manner, and sentenced in respect \nthereof, a period of three year has not elapsed fro m the \nexpiry of the sentence;  \n(f) who has personal interest of any kind in the busine ss or \nany contract or transaction of the concerned company;  \n(g) who is already a director, substantial shareholder,  \nemployee, auditor  or adviser of another company ha ving \nsimilar objectives or has personal interest of any k ind in \nsuch company;  \n  Provided, however, that such person of a private \ncompany may become a director of another private \ncompany having similar objectives.  \n(h) Who is a shareholder that is held to have failed to  pay any \namount due and payable by him/her to the concerned;  \n(i) In the case of a person who has been sentenced to \npunishment pursuant to Section 160, a period of one  year \nis not lapsed from the date of sentence, or in the c ase of a \nperson who has been sentenced to punishment pursuan t to \nSection 161, a period of six months has not lapsed after \nthe date of sentence;  \n(j) In the event that the prevailing laws prescribed  a ny \nqualification or disqualification in the case of a company \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 80  \ncarrying on any specific business, who does not pos sess \nsuch qualification or suffers from such disqualification;  \n(k) Who is already a director of any company  which has  not \nsubmitted such reruns and reports  as required to b e \nsubmitted to the Office under this Act, for any con tinuous \nthree financial years;  \n(l) Who is holding the office of director receiving fro m  \nanother listed company any remuneration or facility , other \nthan a meeting allowance and actual expenses to be in \ncurried in coming to, going from, and staying in, t he place \nof meeting.  \n(2) Any of the following persons shall not be eligi ble to be appointed to \nthe office of in independent director:  \n(a) Who is a person as referred to in Sub-section(1);  \n(b) Who is a shareholder of the concerned company;  \n(c) Who has not obtained at least bachelor degree in a subject \nthat is related to the business to be carried on by  the \nconcerned company and gained at least ten years of \nexperience in the related field or in the company \nmanagement affairs or who has not obtained at least  \nbachelor degree in finance, economics, management, \naccounts, statistics, commerce, trade or law and gai ned at \nleast ten years of experience  in the related field;  \n(d) Who is an officer, auditor or employee of the conce rned \ncompany or a period of three years has not lapsed a fter \nhis/her retirement from any such office;  \n(e) Who is the close relative of the office of the  con cerned \ncompany; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 81  \n(f) Who is an auditor of the concerned company or his/h er  \npartner.  \n(3) No person shall continue to hold the office of a director in any of the \nfollowing circumstances;  \n(a) If one suffers from any disqualification for appoin tment to \nthe  post  of director as mentioned in Sub-section (1) or (2);  \n(b) If the general meeting passes a resolution to remov e \nhim/her  from the office of director,  \n(c) If the resignation tendered by  the director is acc epted by \nthe board of directors;  \n(d) If one is held by a court to have done any act invo lving \ndishonesty or ulterior motive in the activities of the \ncompany;  \n(e) If one is held by a court to have done any act proh ibited by \nthis Act from being done by a director or to have f ailed to \ndo any act required to be done under this Act; \n(f) If one is blacklisted by a competent body pursuant to the \nprevailing law for his/her default in repaying a lo an of any \nbank or financial institution, and the period of su ch black \nlisting has not expired.  \n(4) Prior to holding any person to be disqualified for being appointed to \nthe office of a director or holding such office, th e company shall give \ninformation thereof to him/her and provide him/her with a reasonable \nopportunity to defend him/herself.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "90", "title": "Term of of ice of directors : (1) The tenure of office of a director of a priva te", "content": "company shall be  as provided in its articles of association  \n(2) The tenure of office of a director of a public company shall be as \nspecified in its articles of association, which shall not exceed four years.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 82  \nProvided that: \n(1) A director appointed by the Government of Nepal or a \ncorporate body shall hold office so long as the Gov ernment of \nNepal or the appointing body desires.  \n(2) A director appointed pursuant to Clauses (1) and (2 ) of the \nproviso to Section 87 shall hold office only until the holding \nof the annual general meeting.  \n(3) The term of office of a director appointed to the o ffice of any \ndirector which has fallen vacant before the expiry of his/her \nterm of office shall be only the remainder of the t enure of \noffice of that director whose office  has so fallen  vacant and \nin whose place one is appointed.  \n   (3) Notwithstanding anything contained in the pr evailing law or articles \nof association , a person retired from the office o f director on expiry of his/her \ntenure of office shall be eligible for reappointment to the office of director.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "91", "title": "Remuneration, allowance, reward etc. of directors: (1) The meeting", "content": "allowance to be receivable by the directors for att ending a meeting, their \nmonthly remuneration, daily allowance and traveling  allowance or other \nfacility shall be as determined by the general meeting.  \n(2) The general meeting of any company may, by adop ting a special \nresolution, grant a reward in a sum not exceeding t hree per cent of the net \nprofits after payment of income tax to the director s who work full time for the \ncompany so as to encourage them.  \n Provided, however, that where, on final assessment  of tax under the \nprevailing law, the company has to pay additional i ncome tax, the company \nshall recover the amount of such additional tax fro m the directors, who have \nreceived such reward, on a proportional basis up to  the extent of the amount of \nreward received by them.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 83  \n(3) Pending the holding of the first annual general  meeting, the board of \ndirectors may determine the remuneration and facilit ies of the managing \ndirector or other directors who work full time for the company.  \n(4) Except where the general meeting of a listed co mpany so permits, in \nthe event that any director of a listed company is retired from or relieves of \nhis/her office, the company shall not make any kind  of payment as \ncompensation for such relief or retirement.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "92", "title": "Disclosure by directors : (1) A director shall, no later than seven days af ter", "content": "assuming the office of director, disclose in writin g to the company the \nfollowing matters:  \n(a) If he/she or his/her close relative has direct invo lvement or \nany kind of personal interest in any kind of sale a nd \npurchase or other kind of contract related with the  \ntransactions of the company; \nExplanation \n: For the purposes of this Clause, “direct \ninvolvement” means and includes a situation where t he \ndirector or his/her close relative is a promoter of  or holds \nmore that ten per cent shares of a company or priva te firm \nor partnership firm or a director of a company invo lved in \nsuch transaction.  \n(b) If he/she has any kind of interest in the appointme nt of the \nmanaging director, company secretary, officer of th e \ncompany; \n(c) If he/she is a director of any other company; \n(d) If he/she has made any dealing in the shares or deb entures \nof the company or of its holding or subsidiary comp any, \nabout matters of such dealing.  \n(2) In making disclosure pursuant to Sub-section(1)  , a copy of the \nwritten agreement, if any, concluded between the co mpany and the director or \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 84  \nhis/she close relative shall be submitted, and failing such agreement, substantial \nand necessary matters concerning the transaction or  interest or involvement \nshall be set out.  \n(3) The company shall submit to the Office the info rmation as referred \nto in Sub-section (1) within seven days of the rece ipt of such information; and \nupon receipt of such information, the Office shall record the same in a separate \nregister maintained for this purpose.  \n(4) If any director has an interest directly or ind irectly linked to any kind \nof contract, lease, transaction or agreement entere d or to be entered with the \nconcerned company or its subsidiary company or come s to his/her knowledge \nthat such interest will be so linked, that director  shall disclose that matter to the \ncompany promptly, setting out the extent and kind o f such interest.  \n(5) If any director gives written in formation to t he company that he be \nconsidered to have his/her personal interest in a t ransaction with any certain \nperson, that director shall be deemed to have disclosed his/her  personal interest  \nin any transaction or contract to be done or made with such person.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "93", "title": "Transaction with company in which director is invol ved: (1) Except as", "content": "otherwise provided this Section, no public company shall, without approval of \nthe general meeting, do any significant transaction  with its director or his/her \nclose relative or substantial shareholder or no sub sidiary company shall, \nwithout approval of the general meeting of its hold ing company, do any \nsignificant transaction with any director or his/he r close relative or substantial \nshareholder of the holding company.  \nExplanation : For the purposes of this Section, “significant tr ansaction” means \na transaction of sale, purchase, exchange and contr act the value of which, at the \ntime of doing the transaction, exceeds one hundred thousand rupees or five \npercent of the total assets of the company, whichever is the lesser, and this term \nalso includes a rental transaction amounting to one  hundred twenty thousand \nrupees or more annually.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 85  \n(2) If any transaction is done in contravention of Sub-section (1), any \namount or benefit derived from that transaction dir ectly or indirectly shall be \nreturned to the company; and if any loss or damage is caused from such \ntransaction to the company, the person deriving ben efit from such transaction \nshall also pay compensation for such loss or damage.  \n(3) Notwithstanding anything contained elsewhere in  this Section, the \nprovision of Sub-section (1) shall not apply to the  in-kind property acquired as \nfollows:  \n(a) While acquiring such property by a holding company from \nits wholly owned subsidiary company;  \n(b) While acquiring such property by a subsidiary compa ny \nwholly owned by a holding company from another \nsubsidiary company wholly owned by the same holding  \ncompany; \n(c) While doing transaction at the prevailing market pr ice in \nthe ordinary course of business transaction of the company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "94", "title": "Directors to make disclosure in shares", "content": ": (1) If a person, while holding the \noffice of director, acquires title to any shares or  debentures of the company or \nof a company which is a subsidiary or holding compa ny of that company or of \nanother subsidiary company of the holding company, in any manner, that \nperson shall give information as follows on that matter to the company:  \n(a) Details of his/her title; \n(b) Number of shares of each class in the concerned com pany \nor another company to or in which he/she has title or \ninterest while holding the office of director and d etails of \namount of debentures of each class.  \n(2) If the following situation occurs, any director  of a company shall \ngive written information thereof to the company in which he/she is a director \nno later than fifteen days after such situation comes to his/her knowledge:  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 86  \n(a) If, for any reason, he/she is going to acquire titl e to any \nshares or debentures of the company in which he/she  is a \ndirector or of a company which is a subsidiary or h olding \ncompany of that company or of another subsidiary \ncompany of the holding company, in any manner , or \nhe/she is going to lose his/her title;  \n(b) If he enters into an agreement to sell the shares or  \ndebentures, as referred to in Clause (a), held in h is/her \nname;  \n(c) If he/she assigns to any other person the authority  granted \nby the company in which he is a director to him/her  to \nsubscribe the shares or debentures of such company; \n(d) If a company which is a subsidiary or holding  company of \nthe company in which he/she is a director or anothe r \ncompany which is a subsidiary of such company or ot her \nsubsidiary of the holding company grants authority to \nhim/her to subscribe the shareholders or debentures  of \nsuch company; \n(e) If he assigns to any other person the authority to subscribe \nthe shares or debentures or the company as referred  to in \nClause (d).  \n(3) While forwarding information to the company pur suant to Sub-\nsection (2), such information shall also clearly se tout the number of shares or \ndebentures, amount and class thereof.  \n(4) The company shall maintain a separate register to record the \ninformation receive pursuant to Sub-section (2) and (3).  \n(5) The provisions contained in this Section shall also apply to the close \nrelative of a director as if such relative were a director.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 87", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "95", "title": "Powers and duties of board of directors : (1) Subject to the provisions", "content": "contained in this Act and the articles of associati on and the decisions of the \ngeneral meeting, the directors shall manage all tra nsaction, exercise of powers \nand perform duties of the company through the board of directors collectively.  \n(2) Except in accordance with a decision of the gen eral meeting no \ndirector of a public company shall do anything yiel ding personal benefit to \nhim/her through the company.  \nProvided, however, that a private company may make a reasonable provision \non the benefit which the director may derive though t the company, as \nmentioned in the memorandum of association and arti cles of association or \nconsensus agreement.  \n(3) Except as otherwise provided in this Act, the m emorandum of \nassociation and articles of association or the cons ensus agreements, the case of \na private company, the board of directors may appoi nt any director from \namongst themselves or any employee of the company a s its representative and \nso delegate to him/her any or all of its powers, inter alia , to do any act or thing, \nmake correspondences or sign bills of exchange or c heques etc.  On behalf of \nthe company that such powers are to be exercised in dividually or jointly. In so \ndelegating the powers, at least one director and th eir company secretary, if any, \nshall certify such delegation, pursuant to a decision of the board of directors.  \n(4) A company may recover damages from a person act ing in the \ncapacity of director or representative of the compa ny for any loss or damage \ncaused to the company from any act or action done by  such person beyond \nhis/her jurisdiction.  \n(5) If any person enters into any transaction with the director or with a \nrepresentative as referred to in Sub-section (3) de spite the knowledge or having \nreason to believe that such director or representat ive is dealing with any \ntransaction for his/her personal interest or for ca using loss or damage to the \ncompany, such person shall not be entitled to make any claim against the \ncompany in respect of such transaction.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 88  \n(6) Notwithstanding anything contained in Sub-secti on (3), the board of \ndirectors shall not delegate the following powers c onferred to the company and  \nshall exercise such powers only by means of resolut ions passed at meetings of \nthe board of directors :  \n(a) The power to make calls on shareholders in respect of \namount unpaid on their shares; \n(b) The power to issue debentures; \n(c) The power to borrow loans or amount otherwise than on \ndebentures; \n(d) The power to invest the funds of the company; \n(e) The power to make loans. \n(7) The provision of Clause(e) of Sub-section(6) sh all not apply to loans \nto be let and deposits to be received in the ordina ry course of business \ntransaction by the companies carrying on banking and financial business. \n(8) If the board of directors considers necessary t o form a sub-\ncommittee for the discharge of any specific business , it may form one or more \nthan one sub-committee as required and get such business discharged.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "96", "title": "Appointment of managing directors, and management o f company : (1) The", "content": "directors may, subject to the articles of associati on, appoint one managing \ndirector from amongst themselves.  \n(2) The functions, duties and powers of the managin g director shall be \nas mentioned in the articles of association or as p rescribed by the board of \ndirectors. \n(3) While appoint a managing director and other dir ector talking \nresponsibility of the management of the company pur suant to Sub-section (1), \nthere shall be entered into an agreement in writing  stipulating the terms of \nappointment, remuneration and facilities; and no fa cilities or payment other \nthan the remuneration and facilities specified in s uch agreement and any other \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 89  \nfacilities receivable as specified by the general m eeting shall be provided or \nmade. \n(4) The term of agreement as referred to in Sub–sec tion (3) shall not \nexceed four years at a time.  \n(5) There shall be made such arrangement that the s hareholders can \ninspect, free of charge, the agreement entered into  with the directors pursuant \nto Sub-section (3).  \n(6) A director who is receiving regular remuneratio n or facilities, other \nthan meeting allowances, from any one listed compan y shall not be appointed \nto the post of managing director in another listed company, with entitlement to \nregular remuneration or facilities.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "97", "title": "Meetings of board of directors : (1) Meetings of the board of directors of a", "content": "private company shall be held as mentioned in the articles of association.  \n(2) Meetings of the board of directors of a public company shall be held \nat least six times in a year.  \n Provided, however, that the interval between any t wo meetings shall not \nexceed three months.  \n(3) The directors shall be present in personal meet ings of the board of \ndirectors of a company. The presence of the proxy o f a director in his/her stead \nshall not be held valid.  \n(4) No meeting of the board of directors shall be h eld unless it is \nattended by at least fifty one per cent of the tota l number of directors of the \ncompany.  \nProvided, however, that any director who is not ent itled to take parting any \nmatter to be discussed in a meeting of the board of  directors under this Act \nshall not be counted for the purposes of this sub- section.  \n(5) If a meeting of the board of directors cannot b e held because of the \nlack of presence of directors in the number mention ed in Sub-section (4), \nanother meeting may be called by giving a notice of  at least three days. Even if \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 90  \nsuch meting is not attended by the directors in the  number mentioned in Sub-\nsection (4), the proceedings and decisions conducte d and made by the attending \ndirectors shall be valid.  \n(6) The decision of a majority in a meeting of the board of directors \nshall be binding, and in the event of a tie, the Ch airperson may exercise the \ncasting vote, in addition to a vote cast by him/her as a director. \nProvided, however, that any director who has any pe rsonal concern or interest \nin any matter to be discussed in a meeting of the b oard of directors shall not be \nentitled to take part in such discussion and vote on the matter.  \n(7) Minutes regarding the names of directors presen t in the meeting of \nboard of directors, the subjects discussed and the decisions taken thereon shall \nbe recorded in a separate book, and such minute boo k shall be signed by at \nleast fifty one per cent  of the total directors   present in the meeting.  \n Provided, however, that, if any director puts forw ard any opinion \nopposed too or differing  from the decision in the course of discussions on any \nsubject in a meeting, he/she may mention the same in the minute book . \n(8) Any decision shall not be deemed invalid merely  for the reason that \nthere is no signature of any member.  \n(9) Notwithstanding anything contained in Sub-secti on (3), (4), (5) and \n(6),except in the cases that are so expressly prohi bited by them memorandum \nof association or articles of association, if all t he members of the board of \ndirectors or a sub-committee of directors so consen t in writing in regard to any \nact or resolution permitted to be done or adopted b y the board of directors or \nsuch sub-committee, such act may be done even withou t holding a meeting by \nrecording such consent in the minute book.  \n(10) The consent referred to in Sub-section (9) sha ll be deemed to be a \ndecision of a meeting of board of directors.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "98", "title": "Notice of meeting of board of directors : (1) Except as otherwise provided in", "content": "the articles of association of a company, the compa ny secretary or Chairperson \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 91  \nof the board or chief executive of the company shal l call a meeting of the board \nof directors of the company.  \n(2) Notwithstanding anything contained in Sub-secti on (1) if at least \ntwenty five per cent directors of the total number of directors make written \nrequisition, setting out the subject to be discussed in the meeting, for calling the \nmeeting of the board of directors, the Chairperson shall call the meeting of the \nboard no later than seven days of the receipt of su ch requisition. If the meeting \nof the board of directors is not called within that  period, such requisition \nmaking directors themselves may call the meting of the board of directors.  \n(3) The matters about the notice of a meeting of th e board of directors \nshall be as provided in the articles of association  of the company. Failing such \nprovision, a written notice of the meeting of board  of directors and agenda \nthereof shall be sent to every directors at the add ress supplied by him/her to the \ncompany; and such notice may also be given through any electronic means of \ncommunication.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "99", "title": "Responsibilities and duties of directors : (1) No director or of a company shall", "content": "do any thing to derive personal benefit through the  company or in the course of \nconducting business of the company.  \n(2) If any person has derived personal benefit in t he course of business \nof the company in contravention of Sub-section (1),  the company shall recover \nthe amount involved in the matter from such directo r as if such amount were a \nloan.  \n(3) Any person appointed as a director of a public company shall, prior \nto assuming the duties of his/her office, take an o ath of secrecy and honesty in \na format as prescribed.  \n(4) Every director and officer of a company shall, in discharging their \nduties, act honestly and in   good faith, having re gard to the interest and benefit \nof the company, and exercise such care, caution, wi sdom,   diligence and \nefficiency as a reasonable and prudent person exercises.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 92  \n(5) The company may recover damages for any loss or  damage caused \ntoo the company from a director who does any act with ulterior motive, causing \nsuch loss or damage to the company, in contravention of Sub-section (4).  \n(6) It shall be the duty of every director to compl y with this Act, \nmemorandum of association, articles of association of the company and the \nconsensus agreement.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "100", "title": "Disclosure about securities : (1) In the event that the shares or debentures of  a", "content": "company are listed in a body operating the stock ex change, after the director \nhas made disclosure to the company about the shares  or debentures of such \ncompany pursuant to Section 94, the company shall p romptly give information \nthereof   to such body.  \n(2) Such body shall publish the information receive d pursuant to Sub-\nsection (10) in such manner as it thinks fit.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "101", "title": "Prohibition on loans to officers or shareholders:  (1) No company shall make", "content": "any loan or provide any financial assistance to its  officer, substantial \nshareholders or officer, shareholder of a holding c ompany or a close relative of \nsuch person nor shall it give any guarantee or prov ide security in respect of any \nloan borrowed by such officer or shareholder or clo se relative from any other \nperson.  \n Provided, however, that this provision shall  not apply to any loan or \nfacility to be made or provided to any employee of a company  in accordance \nwith the rules of the company or to any  loan made or guarantee given  by any \nbank or financial institution in the ordinary cours e of business transaction, \nexcept as prohibited by the prevailing law.  \n(2) Any person mentioned in Sub-section (1) shall repay any loan, which \nwas borrowed by him/her prior to the commencement o f this Act, no later than \n22 Ashwin   2065 (8 December 2008).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "102", "title": "Prohibition on giving false statements by officers : If any officer, knowingly", "content": "giving false statements in a general meeting of a c ompany, about the actual \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 93  \nfinancial situation of the company, encourage to di stribute higher dividend to \nthe shareholders of the company than that can be di stributed from the profits, \nthereby affecting the capital of the company, the o fficer giving such false \nstatements shall be personally liable for such act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "103", "title": "Transaction with other person and jurisdiction of c ompany : (1) No", "content": "transaction done by a company with another person s hall be void or invalid \nmerely on the ground that such transaction is beyon d jurisdiction based on any \nmatter contained in the memorandum of association of the company.  \n(2) It shall be the duty of every director and offi cer to do such \ntransaction within the ambit of jurisdiction specif ied in the memorandum of \nassociation of the company \n(3) Except in the case mentioned in Sub-section (1) , any act or \ntransaction done by a director beyond the authority  conferred to him/her may \nbe rectified by the company by adopting a special r esolution in its general \nmeeting.  \n(4) No director, officer or other person of the com pany shall be deemed \nto have been released from any liability under this  Act for any act done or \naction taken by him/her beyond jurisdiction merely on the ground that any act \nor transaction has been ratified by a special resol ution pursuant to Sub-\nsection(3).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "104", "title": "Company to be bound : (1) Any act done or action taken by or document", "content": "signed by at least one director authorized by a com pany or any person \nauthorized to act for the company shall be valid and binding for the company.  \n(2) where any person does any transaction with a co mpany in good faith, \nsuch transaction shall be binding for the company; and nothing contained in \nmemorandum of association, articles of association of the company or in any \nresolution adopted  by the general meeting or in an y agreement concluded \nbetween the company and its shareholder shall be de emed to have made any \nlimitation in or restriction on the authority of the  director or the authorized  \nperson  to do such transaction.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 94  \nProvided, however, that if any officer does any act  or transaction mentioned in \nSub-section (1) or (2) in excess of his/her authori ty, such officer shall be \npersonally liable for such act or transaction unles s such authority is ratified by \nthe general meeting pursuant to this Act; and the c ompany may also recover \nfrom him/her the loss or damage, if any caused to t he company from such act \nor transaction.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "105", "title": "Restrictions on authority of directors : (1) The board of directors of a public", "content": "company, or of a private  company receiving loans f rom any bank or financial \ninstitution, shall not, except with a special resol ution being adopted by the \ngeneral meeting of shareholders, do or cause to be done the following act:  \n(a) selling, donating, gifting, leasing or otherwise disposing of \nmore than seventy per cent of one or more undertaki ngs \nbeing operated by it; \n(b) borrowing moneys, where the moneys to be borrowed w ill \nexceed the aggregate of the paid up capital of the company \nand its free reserves, apart from any loans and fac ulties \nwith a term of less than six months obtained by it from a \nbank or financial institution in the ordinary cours e of \nbusiness transaction; \n(c) making a contribution, donation or gift in a sum exc eeding \nfifty thousand rupees in one financial year or a su m \nexceeding one per cent of the average net profits o f the \ncompany during the last three financial years, whichever is \nthe lesser, except the contribution, donation, gift  etc. made \nfor the welfare of its employees or for the promoti on of its \nbusiness.  \n   Provided, however, that: \n(i) Nothing contained in Clause (a) shall affect the ti tle \nof a buyer who buys any property or undertaking of a \ncompany on payment of the prevailing market price \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 95  \nfrom a company which is solely engaged in the \nbusiness of buying and selling of movable and \nimmovable properties.  \n(ii)  The provision of Clause (b) shall not be applicabl e to \nthe acceptance by a company carrying on banking or \nfinancial transaction or insurance business of depo sits \nor insurance premium from the general public in the  \nordinary course of its business transaction.  \n(2) The general meeting may specify appropriate ter ms and conditions \nwhile giving approval for the purposes of Sub-section (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "106", "title": "Validity of acts already done", "content": ": If it is afterwards discovered that any provision  \nunder this Act has not been complied with in respec t of the appointment of any \ndirector, acts already done by such director him/he r before the discovery of \nsuch fact  shall not be rendered invalid by that fact.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "107", "title": "Registers of director and company secretary : (1) Every company shall", "content": "maintain a separate register of director and of company secretary, if any.  \n(2) Every company shall record the name, surname, a ddress, citizenship, \nprofession, occupation of its director or secretary , and the date of appointment \nas director or secretary as well as the date of rem oval, if applicable, in the \nregister maintained pursuant to Sub-section, (1), a nd shall send a notice of  the \nalteration, if any, made in such detail within fifteen days.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 7", "title": "Chapter 7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "108", "title": "Accounts of company : (1) Every company shall duly maintain its account s in", "content": "the Nepali or the English language.  \n(2) The accounts to be maintained under Sub-section  (1) shall be \nmaintained according to the double entry system of accounting and in \nconsonance with the accounting standards enforced  by the competent body \nunder the prevailing law and with such other terms and provisions required to \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 96  \nbe observed pursuant to this Act, in such a manner as to clearly reflect the \nactual affairs of the Company.  \n(3) The books of account of a company shall not be kept at any place \nother than its registered office, except with the approval of the Office.  \n(4) The cash balance of a company, other than the a mount specified by \nthe board of directors, shall be deposited in a ban k and transaction shall be \ndone through the bank.  \n(5) Subject to the provisions contained in this Cha pter, the directors or \nother officers shall have the final responsibility to maintain books of account \nand records of the company.  \n(6) Where there is a default in complying with the provisions made in \nthis Act in respect of the preparation of books of account and annual financial \nstatements of a company, the director or officer hi m/herself, during whose \ntenure the annual financial statements and other re ports have been prepared, \nshall be responsible under this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "109", "title": "Annual financial statement and report of board of d irectors : (1) The", "content": "following annual financial statements shall be prep ared by the board of \ndirectors of a public company every year at least thirty days prior to the holding \nof its annual general meeting, and in the case of a  private company, within six \nmonths of the expiry of its financial year: \n(a) Balance sheet as at the last date of the financial year.  \n(b) Profit and loss account of the financial year.  \n(c) Description of cash flow of the financial year.  \n(2) This annual financial statement to be prepared pursuant to Sub-\nsection(1) shall give true and  fair view of the st ate of affairs of the company as \nat the last day of the financial year concerned and  also state the account of \nprofit and loss and description of cash flow made i n that financial year. Such \nfinancial statements shall be prepared in the format prescribed by the prevailing \nlaw.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 97  \n(3) The annual financial statements as referred to in Sub-section (1)shall \nhave to be approved by the board of directors and audited.  \n(4) The board of directors of every public company or every private \ncompany with the paid –up capital of ten million ru pees or more or with an \nannual turnover of ten million rupees or more shall also prepare a separate \nreport of board of directors during that period sta ting the following matters, in \naddition to the annual financial statements require d to be prepared pursuant to \nSub-section (1):  \n(a) Review of the transactions of the previous year; \n(b) Impacts, if any, caused on the transactions of the company \nfrom national and international situation; \n(c) Achievements in the current year as at the date of report \nand opinions of the board of directors on matters t o be \ndone in the future; \n(d) Industrial or professional relations of the company; \n(e) Alterations in the board of directors and the reaso ns \ntherefore; \n(f) Major things affecting the transactions; \n(g) If there  are any remarks in the audit report, the comments \nof the board of directors on such remarks; \n(h) Amount recommended for payment by way of dividend; \n(i) In the event of forfeiture of shares, details regar ding the \nnumber of  forfeited shares, face value of such shares, total \namount received by the company for such shares prio r to \nthe forfeiture thereof, proceeds of sale of such sh ares after \nthe forfeiture  thereof, and refund  of amount ,if any, made \nfor such forfeited shares; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 98  \n(j) Progress of transactions of the company and of its \nsubsidiary company in the previous financial year a nd \nreview of the situation existing at the end of that  financial \nyear; \n(k) Major transactions completed by the company and its  \nsubsidiary company in the financial year and any ma terial \nchanges taken place in the transactions of the comp any \nduring that period; \n(l) Disclosures made by the substantial shareholders of  the \ncompany to the company in the previous financial year; \n(m) Details of shareholding taken by the directors and officers \nof the company in the previous financial year and ,  in the \nevent of their involvement in share transaction of the \ncompany, details of information received by the com pany \nfrom them in that respect; \n(n) Details of disclosures made about the personal inte rest of \nany director and his/her close relative in any agre ements \nrelated with the company during the previous financ ial \nyear; \n(o) In the event that the company has bought its own sh ares \n(buy-back), the reasons for such buy-back ,number a nd \nface value of such shares, and amount paid by the \ncompany for such buy-back; \n(p) Whether there is an internal control system in  pla ce or not; \nand details of such system, if it is in place;  \n(q) Details of total management expenses during the pre vious \nfinancial year; \n(r) Name-list of the members of audit committee, \nremuneration, allowances and facilities received by  them, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 99  \ndetails of the functions performed by that committe e, and \ndetails of suggestions, if any, made by that committee;  \n(s) Amount, if any, outstanding and payable to the comp any \nby any director, managing director ,chief executive , \nsubstantial shareholder or his/her close relative o r by any \nfirm company, corporate body in which he/she is involved; \n(t) Amount of remuneration, allowances and faculties pa id to \nthe director, managing director, chief executive and officer; \n(u) Amount of dividends remaining unclaimed by the \nshareholders ; \n(v) Details of sale and purchase of properties pursuant  to \nSection 141; \n(w) Details of transactions carried on between the asso ciated \ncompanies pursuant to Section 175; \n(x) Any other matters required to be set out in the rep ort of \nboard of directors under this Act and the prevailing law; \n(y) Other necessary matters. \n(5) While preparing the annual financial statements  pursuant to Sub-\nsection (1), such statement shall  also contain, in  the case of the year of \nincorporation of the company, the accounts from the  date of its incorporation  \nto the last day of that financial year, and thereafter, the accounts of the previous \nfinancial year.  \n(6) The annual financial statements prepared pursua nt to this Section \nshall be kept open for inspection by any shareholder, if he/she so desires.  \n(7) The annual financial statements and the report of board of directors   \nprepared pursuant to this Section shall be approved  by the board of directors \nand signed by the Chairperson of the board of direc tors and at least one director.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 100  \n(8) The accounts and annual financial statements prepared by a company \npursuant to this Chapter shall be kept safely for a t least five years after the date \nof expiry of the financial year concerned.  \n(9) The officers who prepare any false annual finan cial statements, \nreports of board of directors and other returns and  reports required to be \nprepared pursuant to this Act and the directors who  approve the same shall be \nliable to punishment under this Act.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 8", "title": "Chapter 8", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "110", "title": "Company to appoint auditor : (1) Every company shall appoint an auditor", "content": "under this Act to have its accounts audited.  \n(2) In cases where any company has a branch office outside Nepal, the \nauditor appointed pursuant to Sub-section (1) may a lso audit the accounts of \nthat branch office except as otherwise provide in t he prevailing law of the \ncountry where such branch office is situated.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "111", "title": "Appointment of auditor : (1) The auditor of accompany shall be appointed,", "content": "from amongst the auditors licensed to carry out aud it under the prevailing law, \nby the general meting, subject to Chapter-18 ,in th e case of a public company, \nand,  in accordance with the provision as contained  in the memorandum of \nassociation, articles of association or consensus a greement, any failing such \nprovision, by the general meeting, in the case of a  private company; and his/her  \nname shall be forwarded to the Office within fiftee n days from the date of such \nappointment.  \n Provided, however, that the board of directors may  appoint the auditor \nprior to the holding of the first annual general meeting,  \n(2) The auditor appointed pursuant to Sub-section ( 1) shall hold office \nonly until the next annual general meeting.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 101  \n(3) No auditor or his/her partner or ex-partner or employee or ex-\nemployee shall be appointed as auditor for more tha n three consecutive terms \nto perform the audit of a public company.  \n Provided, however, that this restriction shall not  apply to any partner \nwho ended partnership or any employee who left the service of such auditor \nthree years before.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "112", "title": "Disqualifications of auditor", "content": ": (1) None of the following persons or the firms or \ncompanies in which such persons are partners shall be qualified for \nappointment as auditor and shall, despite appointme nt as auditor, continue to \nhold office: \n(a) A director, advisor appointed with entitlement to r egular \nremuneration or cash benefit, a person or employee or \nworker involved in the management of the company or a \npartner of any of them or and employee of any of su ch \npartners or a close relative of a director or partn er, out of \nthem, or and employee of such relative; \n(b) A debtor who has borrowed moneys from the company i n \nany manner, or a person who has failed to  pay any dues \npayable to the company within the time limit and is in \nsuch arrears or close relative of such person; \n(c) A person who has been sentenced to punishment for a n \noffense pertaining to audit and a period of Three y ears has \nnot elapsed thereafter; \n(d) A person who has been declared insolvent; \n(e) A substantial shareholder of the company or a share holder \nholding one percent or more of the paid up capital of the \ncompany or his/her close relative; \n(f) A person who has been sentenced to punishment for a n \noffense of corruption, fraud or a criminal offense \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 102  \ninvolving moral turpitude and a period of five year s has \nnot elapsed thereafter; \n(g) A person referred to in Sub-section (3) of Section 111; \n(h) In the case of a public company , any person who wo rks, \nwhether full time or part time , for any government al body \nor any body owned fully or partly by the Government  of \nNepal or any other company or a partner of such per son or \na person who is working as an employee of such part ner or \na person who is authorized to sign any documents or  \nreports to be prepared by the management of the company; \n(i) A company  or corporate body with limited liability; \n(j) A person having interest in any transaction with th e \ncompany or his/her close relative or a director, of ficer or \nsubstantial shareholder of another company having a ny \ninterest in any transaction with the company.  \n(2) The auditor shall, prior to his/her appointment  ,give information in \nwriting to the company that he/she is not disqualif ied pursuant to Sub-\nsection(1).  \n(3) Where any auditor becomes disqualified to audit  the accounts of a \ncompany or there arises a situation where he/she be comes disqualified for \nappointment or can no longer continue to act as an auditor of the company, \nhe/she shall immediately stop performing audit which is required to be \nperformed or is being performed by him/her and give information thereof to the \ncompany in writing.  \n(4) The audit performed by an auditor who has been appointed in \ncontravention of this Section shall be invalid.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "113", "title": "Power of Office to appoint auditor : Where the annual general meeting of a", "content": "company fails to appoint an auditor for any reason or where the annual general \nmeeting itself cannot be held or where the auditor appointed pursuant to this \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 103  \nAct ceases to continue his/her office for any reaso n, the Office may, at the \nrequest of the board of directors of the company, appoint another auditor.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "114", "title": "Accounts and records to be furnished : The books of accounts and records of", "content": "a company shall on his/her demand, at any time duri ng office hours be \nfurnished to the auditor for the purposes of audit;  and the concerned director or \nemployee shall also forthwith give oral explanation s on such matter as may be \nasked by him/her, within a reasonable period of time.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "115", "title": "Functions and duties of auditor : (1) The auditor shall, addressing the", "content": "shareholders or the appointing authority, submit to  the company his/her report, \ncertifying the balance sheet, profit and loss accou nt and cash flow statement \nbased on the books of account, records and accounts audited by him/her.  \n(2) The audit report shall be prepared in accordanc e with the prevailing \nlaw or in consonance with the audit standards presc ribed by the competent \nbody; and such report shall state the matters to be  set out under this Act, as per \nnecessity.  \n(3) The audit report as referred to in Sub-section (2) shall also indicate \nthe following matters, inter alia :  \n(a) Whether such information and explanations have been  \nmade available as were required for the completion of \naudit;  \n(b) Whether the books of account as required by this Ac t have \nbeen properly maintained by the company in a manner  to \nreflect the real affairs of its business; \n(c) Whether the balance sheet, profit and loss account and \ncash flow statements received have been prepared in  \ncompliance with the accounting standards prescribed  \nunder the prevailing law and whether such statement s are \nin agreement with the books of account maintained b y the \ncompany; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 104  \n(d) Whether, in the opinion of the auditor based on the  \nexplanations and information made  available in the  course \nof auditing, the present balance sheet properly ref lects the \nfinancial situation of the company, and the profit and loss \naccount and cash flow statement for the year ended on the \nsame date properly reflect the profit and loss, cas h flow of \nthe company, respectively; \n(e) Whether the board of directors or any representativ e or \nany employee has acted contrary to law or \nmisappropriated any property of the company or cause d \nany loss or damage to the company or not; \n(f) Whether any accounting fraud has been committed in t he \ncompany  \n(g) Suggestion, if any.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "116", "title": "Audit report to bear auditor’s signature", "content": ": (1) An audit report prepared by the \nauditor appointed by any company this Act shall be signed and dated by the \nauditor him/herself.  \n(2) Whether any company has appointed any accountin g institution \nlicensed under the prevailing law to carry out audi t, the member who has been \nauthorized by a decision of the partners of such in stitution shall sign and date \nthe audit report.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "117", "title": "Information to be provided : The Company shall, subject to the provisions", "content": "contained in this Act, send a copy of the report ma de by the auditor to the \nshareholders. Whether there is a provision of forma l trade union in such \ncompany, the company shall, at the request in writi ng of such trade union, \nprovide one copy of such report to that trade union.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "118", "title": "Remuneration of auditor : The remuneration of an auditor shall be as", "content": "prescribed by the appointing authority; and such re muneration shall be borne \nby the company.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 105", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "119", "title": "Provision relating to removal of appointed auditor : (1) No auditor appointed", "content": "pursuant to this Chapter shall be removed pending t he completion of audit of \naccounts of any financial year for which he/she was appointed as the auditor.  \n(2) Notwithstanding anything contained in Sub-secti on (1) , if any \nauditor  breaches the code of conduct of auditors o r does any act against the \ninterest of the company which has appointed him/her  as the auditor or commits \nany act contrary to the prevailing law, such audito r  may be removed through \nthe same process whereby he/she was appointed as au ditor, by giving prior \ninformation to the Nepal Chartered Accountants Inst itute, and  with the \napproval  of the regulatory authority, if any autho rized by the prevailing law for \nthe regulation of business of the company concerned  , and failing such \nauthority, with the approval of the Office.  \n(3) While removing an auditor pursuant to Sub-secti on (2), the auditor \nshall be provided with a reasonable opportunity to defend him/herself.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 9", "title": "Chapter 9", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "120", "title": "Power of Office to call for explanation : (1) Where any matter is unclear in", "content": "the documents submitted by a company, and such matt er has to be set out or \nany explanation is necessary in respect of any matt er, the Office may call on \nthe company to furnish explanation on such matter w ithin such reasonable \nperiod of time as specified by it.  \n(2) The management of the company shall, within the  specified period \nof time, send proper replies the specified period o f time, sent proper replies to \nthe matters with respect to which explanation has b een called on pursuant to \nSub-section(1).  \n(3) If, in the course of perusing explanation, the Office notices any \nirregularity in the business of a company, it may g ive necessary directive to the \ncompany to regularize, or cause to be regularized, it, and it shall be the duty of \nthe company to obey such directive.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 106", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "121", "title": "Power of Office to depute inspector : If the shareholders representing not less", "content": "than ten percent of the paid up capital or not less  than one –fourth of the total \nnumber of shareholders  of the company or the conce rning creditors make an \napplication, accompanied by the supporting evidence  and reasonable grounds, \nstating that the company has acted in contravention  of this Act, the \nmemorandum of association, articles of association,  prospectus, consensus \nagreement or prevailing law, the Office may, as per  necessity, depute one or \nmore inspectors. Such inspector shall be an expert in any of the subjects viz. \naccounts, law, finance, management, commerce, indus try or company \nadministration or any business which a company carr ies on the applicant shall \ndeposit with the Office such amount of estimated co st required for such \ninvestigation as specified by the Office.  \n(2) Notwithstanding anything contained in Sub-secti on (1), where the \nOffice is of opinion that the following circumstance  does exist, it may, as per \nnecessity, even if no application is made pursuant to Sub-section (1), appoint \nan inspector in possession of the qualification ref erred to in Sub-section (1), to \ninvestigate the transactions or business of any company: \n(a) on  the receipt of information that the business or \ntransaction of the company is being carried on to d efraud \nthe shareholders or creditors of the company or oth erwise \nfor a fraudulent or illegal purpose or it is carryi ng out acts \nagainst public interest; or  \n(b) any public company has not furnished such informati on \nabout its transactions as is required to be furnished.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "122", "title": "Functions, duties and powers of inspector", "content": ": (1) The functions, duties and \npowers of the inspector deputed or appointed pursua nt to Section 121 shall be \nas follows:  \n(a) in course of investigation, to require those office rs or \nshareholders or the company, where existing or form er, \nwhom he/she considers appropriate ,or any other per sons \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 107  \nwho are considered to have information relevant to the \nmatter into which investigation is to be carried to  appear \nbefore him/her and to record their statements; to o btain \nnecessary information or other reasonable assistance; \n(b) to inspect the documents which are relevant  for th e \npurposes of investigation, or to seize or control  any other \nthings, or require any concerned person to produce such \ndocuments or things to him/her, or to take custody of such \ndocuments; \n(c) To investigate, or cause to be investigated, into w hether \nthe books of account of the company have been kept \nproper.  \n(2) Notwithstanding anything contained in the peril ing law, any matter \nor deposition expressed or made by any person befor e the inspector in the \ncourse of investigation pursuant to this Chapter sh all be admissible as an \nevidence against that person.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "123", "title": "Assistance to be rendered to inspector", "content": ": (1) If any person makes a false \ndeposition, fails to produce such statements or doc uments or other things as \nrequired to be submitted under Section 122 or fails  to answer any question \nasked which is put to him/her by the inspector or f ails to provide such \ninformation as asked by the inspector for the purpo ses of investigation, the \ninspector may file a compliant report in writing in the Court.  \n(2) On receipt of a report under Sub-section(1), th e Court may, if, on \nnecessary inquiry made into the matter under the pr evailing law, any person is \nfound guilty, impose such punishment on that person as it considers appropriate \nunder Section 162.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "124", "title": "Report to be submitted : (1) The inspector appointed pursuant to this Chap ter", "content": "shall, on conclusion of the investigation, submit a  report, accompanied by \nhis/her opinions, to the Office. The Office shall g ive a copy of such report to \nthe applicant if any shareholder makes an applicati on to get a copy of such \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 108  \nreport, the office shall issue a copy thereof to hi m/her, by collecting the \nprescribed fees.  \n(2) If, from any report made by the inspector under  Sub-section (1), It \nappears to the Office that any directors, managing directors, managers, \nemployees or any other officers of the company have  knowingly caused any \nloss or damage to the company or have defrauded, ch eated the shareholders or \ncreditors or committed any other illegal acts, the O ffice shall, notwithstanding \nanything contained in the prevailing laws, order th e company to file a lawsuit \non behalf of the company against them. \n(3) Where the Office thinks that the company may su ffer further loss or \ndamage if its business is left further in the hand of directors, managing \ndirectors, managers, employees or any other officer s who have committed any \nact as referred to in Sub-section (2), the Office m ay give necessary direction to \nthe company to suspend such directors managing dire ctors, managers, \nemployees or officers and carry on its business through any other means. \n(4) Notwithstanding anything contained in the preva iling law on \nevidence, any matter contained in and any fact expr essed in a report submitted \nby an inspector pursuant to Sub-section(1) shall be admissible as an evidence.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "125", "title": "Expenses of investigation : (1) The expenses incurred in an investigation", "content": "carried out by the Office pursuant to this Chapter shall be borne by the \nconcerned company. \n Provided, however, that if, in the course of carry ing out investigation, \nany director, managing director, manager or officer  of a company appears to \ncommitted a malice, deception, fraud or cheating, su ch director, managing \ndirector, manager or officer shall pay the expenses  of investigation no later \nthan seven days of the completion of investigation. \n(2)  If the concerned director, managing director, manager or officer \ndoes not pay the expenses of investigation pursuant  to the expenses of \ninvestigation pursuant to the proviso to Sub-sectio n(1), the expenses shall be \nrecovered as governmental dues. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 109  \n(3) An inspector appointed pursuant to this Chapter  may give suggestion \nin his/her report as to the payment of expenses.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 10", "title": "Chapter 10", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "126", "title": "Liquidation of company able to pay its debts : (1) Expect in case where a", "content": "company has become insolvent in accordance with the  prevailing law on \ninsolvency, the shareholders of the company may liq uidate the company either \nby adopting a special resolution in the general mee ting or memorandum of \nassociation, articles of association or consensus agreement.  \n(2) A company may be liquidated under this Act in t he following \ncircumstance: \n(a) If the company is able to pay its debts or other li abilities in \nfull; \n(b) If there exists no situation where an application f or the \nreview of insolvency of the company is pending unde r the \nprevailing law on insolvency or where the company w ould \nbe in any manner subject to an insolvency proceedin g \nunder the prevailing law on insolvency; \n(c) If the directors of the company, have, after due in quiry, \nmade a declaration in writing that the company is a ble to \npay its debts and other liabilities in full and tha t the debts \nand liabilities to be paid on behalf of such compan y can be \npaid up or can be fully settled in any other proces s within \none year from the date of the adoption of the resol ution to \nliquidate the company; \n(d) If the written declaration made by the directors pu rsuant to \nClause (c) was presented in the general meeting cal led to \ndiscuss the matter of liquidation of the company or  such \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 110  \ndeclaration was made at the time of discussions on that \nmatter in the general meeting. \n(3) A copy of the special resolution adopted with r espect to the \nliquidation of a company pursuant to this Section a nd a written declaration of \ndirectors shall be submitted to the Office in later  than seven days after the date \nof adoption of the resolution.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "127", "title": "Appointment of liquidator and auditor : (1) While adopting a resolution to", "content": "liquidate a company pursuant to Section 126, the co mpany shall appoint a \nliquidator.  \n(2) While appointing a liquidator pursuant to Sub-s ection (1), a \npractitioner licensed under the prevailing law on i nsolvency shall be appointed \nas liquidator to conduct the liquidation proceeding s and fix remuneration \nreceivable by such liquidator . \n(3) The company shall give information of the appoi ntment of a \nliquidator pursuant to Sub-section (2) to the Offic e no later than seven days \nafter the date of such appointment. \n(4) After a liquidator is appointed pursuant to Sub -section (2), the \ndirectors and officers of the company shall relieve d of their office and the \nliquidator shall exercise all such powers with resp ect to the operation and \nmanagement of company as may be exercisable by the directors and officers of \nthe company. \n(5) The service of employees of a company shall, ipso facto , be \nterminated after the liquidator commences the opera tion and management of \nthe company pursuant to Sub –section (4). \nProvided, however, that the liquidator may retain o r appoint necessary \nemployees for his/her support and assistance.  \n(6) The liquidator appointed pursuant to this Secti on shall complete the \nliquidation proceedings of the company within the p eriod of time specified at \nthe time of his/her appointment.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 111  \n Provided, however, that in the case where the liqu idation proceedings \ncannot be complete for any reason within the specif ied period of time, a \nreasonable time limit may be extended by following t he same procedure as \nfollowed in his/her appointment.  \n(7) While appointing a liquidator pursuant to Sub-s ection (1), an auditor \nshall also be appointed subject to provisions contained in this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "128", "title": "Application of prevailing law on insolvency : While liquidating a company", "content": "under this Chapter, the issue of whether any person  is a creditor of a company \nin liquidation shall be determined in accordance wi th the prevailing law on \ninsolvency.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "129", "title": "Application to be made in the event of inability of  company to pay", "content": "liabilities:  If, after the liquidator has commenced proceedings  of liquidation of \naccompany under this Chapter, he/she is satisfied t hat the company is insolvent \nand is not able to pay debts required to be paid or  discharge liabilities required \nto be discharged in full he/she shall make an appli cation to have a review of \ninsolvency of the company in accordance with the pr evailing law on insolvency.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "130", "title": "Power of liquidator too take into custody and under  control property of", "content": "company : After a liquidator has commenced his/her act, the  liquidator shall \ntake into his/her custody and under his/her control all property, accounts and all \nrecords and documents of the company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "131", "title": "Powers and duties of liquidator : (1) The liquidator appointed under this Act", "content": "shall, mutatis mutandis , exercise and perform all the powers and duties wh ich \nmay be exercised and performed by a liquidator unde r the prevailing law on \ninsolvency.  \n(2) It shall be the duty of the liquidator to do th e following acts, without \nprejudice to the generality of Sub-section (1):  \n(a)  To prepare and submit to the office, the state ments and \naccounts of incomes and expenditures in the course of \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 112  \nliquidation in every six months after the appointme nt of \nthe liquidator; \n(b)  To inform the shareholders of the company abou t the \nprogress on the liquidation proceedings in every si x \nmonths after the appointment of the liquidator; \n(c)  To obtain and recover all properties or amount s required to \nbe obtained and recovered on behalf of the company and \nrepay and discharge the debts and other liabilities of all the \ncreditors of the company; \n(d)  Following the completion of the act as referre d to in \nClause (c) , to call the general meeting of shareho lders and \npresent therein a proposed report and return on the  \ndistribution of the remaining properties of the com pany to \nthe shareholders; \n(e)  If the shareholders holding at least seventy f ive per cent of \nthe paid up share capital consent to the return as referred \nto in Clause (d), to make payment of amounts to the  \nshareholders accordingly;  \n(f)  At the completion of liquidation proceedings, to prepare a \nreport on the properties recovered, payments made t o the \ncreditors and distributions made to the shareholder s, on \nbehalf of the company, and submit such report, cert ifying \nthat the company has been liquated, accompanied by the \nauditor’s report, to the Office.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "132", "title": "Cancellation of registration of company : (1) Upon receipt by the Office of a", "content": "report on the liquidation of a company pursuant to Clause (f) of Sub-section (2) \nof Section 131, the Office shall strike the name of  the company off the \ncompany register and issue an order that the regist ration of the company has \nbeen canceled.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 113 \n(2) After the issue of an order on the cancellation  of registration of a \ncompany pursuant to Sub-section (1), the Office sha ll strike the name of such \ncompany off the company register and publish in a n ational daily newspaper a \nnotice that such company has been dissolved.  \n⊕(3) Notwithstanding contained anything in this sect ion, liquidator \nappointed as per Insolvency Act, 2063, shall send t o the office regarding the \ninformation completion of cancellation process of the cancel such company.   \n⊕(4) Upon receiving the information pursuant to Sub- section (3) the \noffice, shall keep record of cancellation such comp any and after such record \nthe company shall deemed to be cancelled.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "133", "title": "Power of creditor and shareholder to make complaint :  If any creditor or", "content": "shareholder of a company thinks that there is any i rregularity in respect of any  \nact or action of the liquidator, while liquidating the company pursuant to this \nChapter, such creditor or shareholder may make a co mplaint to the court \nagainst such act or action within fifteen days of t he receipt of information \nthereof .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "134", "title": "Action to be taken in cases of fraud or deception : If a liquidator thinks that", "content": "any director, employee or shareholder of a company has committed a fraud or \ndeception against the company, the liquidator may t ake necessary legal action \nagainst such person in accordance with the prevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "135", "title": "Right of secured creditors not to be affected : The commencement of", "content": "liquidation proceedings of a company pursuant to th is Chapter shall not be \ndeemed to prejudice in any manner the right of the secured creditors who have \nlent moneys against the security of any property of  the company to enforce or \notherwise deal with such secured property under the prevailing law. \n \n                                                   \n⊕ Inserted by the Some Nepal Act (Amendment) Act, 2064  \n \n \n \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 114", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 11", "title": "Chapter 11", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "136", "title": "Power of Office to cancel registration : (1) The Office may cancel the", "content": "registration of a company in the following circumstance:  \n(a) If the promoter of the company makes an application , \nshowing a reason for the failure to commence the bu siness \nof the company, and accompanied by the prescribed f ees, \nfor the cancellation of the registration of the company: \n(b) If the company is in default in submitting to the O ffice the \nreturns as referred to in Section 80 or fails pay t he fine as \nreferred too in Section 81 for three consecutive fi nancial \nyears; or  \n(c) If based on the proofs received in the course of \nadministration of the company, the Office has a reasonable \nground to believe that the company is not carrying on its \nbusiness or the company is not in operation.  \n(2) If it is required to cancel the registration of  any company pursuant to \nSub-section (1), the Office shall, prior to the can cellation of registration, give a \nnotice, accompanied by the reason for such registra tion, to the concerned \ncompany.  \n(3) While sending a notice to a company pursuant to  Sub-section (2), the \nnotice shall be sent to the company at its register ed office or to any office or \nsuch company if the address of the registered offic e of such company is not \nregistered with the Office or if the office of the company is not located at the \naddress registered and to the memorandum of associa tion of the company if \neven address of such officer is not available to the Office or is not known.  \n(4) A notice given pursuant to Sub-section (2) shal l also be published in \na national daily newspaper, as per necessity.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 115  \n(5) If the company fails to make an application, sp ecifying the reasons \nthat the registration of the company should not be canceled, within two months \nfrom the date of receipt by the company of a notice  pursuant to Sub-section (2) \nor, despite the making of such application, the rea sons specified are not found \nreasonable, the registration of such company may be canceled.  \n(6) If the registration of a company is canceled pu rsuant to Sub-section \n(5), information thereof shall be given to the conc erned directors and shall also \nbe published in a national daily newspaper.  \n(7) If the registration of a company is canceled pu rsuant to Sub-section \n(5), if there exists any kind of liability of the c ompany, the liability of the \nofficer or shareholder of the company shall continu e to exist; and nothing \ncontained in this Section shall be deemed to bar th e instituting of necessary \nlegal action against them to have such liability fulfilled.  \n(8) The assets, rights, benefits or liabilities hel d in the name of the \ncompany at the tine of cancellation of its registration pursuant to Sub-section (5) \nshall devolve on its shareholders in the proportion of their shareholding.  \n Provided, however, that the title and ownership of  any property which \nhas been held by the company as a trustee in favor of any other person shall to \ndevolve on the shareholders.  \n (9) If any debt to be repaid by or any liability t o be \nperformed/discharged by the company of which regist ration has been canceled \npursuant to this Section cannot be settled from the  assets, rights, or benefits \ndevolved on the shareholders pursuant to Sub-sectio n (8), the shareholders, \ndirectors or officers who were involved in the mana gement of such company \nand responsible for giving rise to the  situation a s referred to in Sub-section (1) \nshall personally bear such remaining loan or liability.  \n(10) A company of which registration is canceled pu rsuant to this \nSection shall not be allowed to carry on any busine ss by the name of the same \ncompany.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 116  \n(11) Following the cancellation of registration of any company pursuant \nto this Section, the Office shall return to the sha reholders only such property, if \nany, remaining after deducting therefrom the expens es incurred in the \ncancellation of the registration of that company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "137", "title": "Restoration of registration of company of which reg istration was canceled:", "content": "(1) In the case of cancellation of the registration  of a company pursuant to Sub-\nsection (5) of Section 136, where the company or it s shareholder or creditor \nmakes a petition , setting out the reasons, to the Court to have the company \nrestored, no later than five years after the date o f publication of the notice of \ncancellation of registration of the company, the Co urt may, if the following \ncircumstance, order to restore the company and resto re its name in the \ncompany register:  \n(a) If it appears that the registration of the company was \ncanceled while such company was carrying on its bus iness;  \n(b) If the Court considers it to be just to restore the  name of \nthe company for the proper management of the assets  and \nliabilities of such company.  \n(2) In the event of restoration of a company by vir tue of an order of the \nCourt pursuant to Sub-section (1), the company shal l be considered to have \nbeen in existence from the date of its registration.  \n(3) In issuing an order pursuant to Sub-section (1)  , the court may issue \nsuch orders and make an order to make such arrangem ents as it  may consider \nappropriate and necessary for restoring the company  and all other persons into \nthe status quo ante  as if the registration of the company were not canceled.  \n(4) Where a company is restored pursuant to Sub-sec tion (1) and any \nfine as referred to in Section 81 is to be paid, th e company shall be restored and \nits name reentered in the company register only aft er such fine is paid to the \nOffice.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 117  \n(5) Where a company of which registration has been canceled pursuant \nto Section 136 is restored pursuant to this Section , such company shall have the \nfollowing property reverted to it:  \n(a) Any property received by its shareholders in such c apacity \npursuant to Sub-section (8) of Section 136 by virtu e of the \ncancellation of registration of the company; \n(b) Where the property as referred to in Clause (a) has  already \nbeen sold and disposed of, the proceeds of such sal e and \ndisposal.  \n Provided, however, that no property or amount \nalready employed in the payment of debt or liabilit y of a \ncreditor shall be returned.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 12", "title": "Chapter 12", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "138", "title": "Power to prevent directors and officers from doing unauthorized act:  (1) If,", "content": "on behalf of a company, any director or officer of the company does any act \nbeyond his/her jurisdiction, any shareholder of suc h company may make a \npetition to the Court to prevent such act.  \n Provided, however, that no petition may be made un der this Section in \nconnection with any act or action done or taken or intended to be done or taken \nfor the fulfillment of any liability created from a ny act or action already done \nor taken by the company.  \n(2) If, based on the report received by the Office pursuant to Section 124 \nin respect of any company, the Office thinks that t he business of such company \ncould be carried on or is being carried on in such a manners to be prejudicial to \nthe rights and interests of any of or all sharehold ers of the company or any \nspecific class or group of its shareholders or that  any act done or intended to be \ndone by the company or the failure of the company t o do any act required to be \ndone has resulted in or would result in a prejudice  to the interests of such \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 118  \nshareholders, the Office may make a complaint/ peti tion to the Court against \nsuch company or its directors or officers.  \n(3) On receipt of a petition as referred to in Sub- section (1) or (2), the \nCourt may inquire into the concerned company or its  directors or officers and \nissue an appropriate order.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "139", "title": "Remedy for act done against rights and interests of  shareholders : (1) Based", "content": "on the ground that the business of a company is car ried on or is likely to be \ncarried on in such a manner as to be prejudicial to  the rights and interests of \nany shareholder of the company or that any act done  or intended to be done on \nbehalf of the company or the failure of the company  to do any act required to \nbe done has resulted in or would result in a prejud ice to the rights and interests \nof any shareholder, such shareholder may make a com plaint/ petition to the \nCourt for an appropriate order.  \n(2) A shareholder who makes a petition pursuant to Sub-section (1) shall \nprove that the director, managing director, manager  or any officer who \nmanages and controls the company has done or intend s to do any act with \nulterior motive or made or intends to make undue di scrimination, in \ncontravention of the memorandum of association or a rticles of association or \nconsensus agreement.  \n(3) On receipt of a petition as referred to in Sub- section (1), the court \nmay if, upon inquiring into the concerned company, director or officer, the \nclaim set forth in the petition appears to have rea sonable, issue such order in \nthe name of the company as it thinks appropriate for providing remedy thereto. \n(4) In issuing an order pursuant to Sub-section (3) , notwithstanding \nanything contained in the memorandum of association , articles of association \nor consensus agreement, the Court may, without prej udice to the generality of \nthe said Sub-section, also issue the following order, namely: \n(a) Preventing the act and action done and taken agains t the \nrights and interests of any or all shareholders and  carrying \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 119  \nof the business of the company in the future in a d ue \nmanner; \n(b) Preventing any act and action being done and taken or \nrequiring to do any act not done or intended not to  be done \nby the company; \n(c) Requiring to institute, on behalf of the company a  civil \ncase against any one, in pursuance of a direction g iven by \nthe court; \n(d) Requiring to buy back the shares of any shareholder  in \naccordance with the procedures set forth in this Ac t, by \nreducing the capital of the company, and to return the \namount of such shares; \n(e) In the event of any loss and damage being suffered any \nshareholder from a discrimination made against him/h er, \nrequiring the company or the person making such \ndiscrimination to pay compensation to the shareholde r for \nthe same;  \n(f) Liquidating the company; \n(g) Requiring the company itself or any other sharehold er of \nthe company to purchase the shares held in the name  of \nany shareholder;  \n(h) Recovering the loss and damage caused to the compan y or \nits shareholders from the director or officer who h as \ncaused such  loss and damage; \n(i) Where the company is to buy back its own shares, is suing \nan order to reduce the share capital of such compan y as if \nthe share capital of such company were reduced by i t by \nadopting a special resolution on reduction of share  capital; \nwhere the memorandum and articles of association of  the \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 120  \ncompany is to be amended by virtue of such order, i ssuing \nother appropriate order also to make necessary amendment \nthereto.  \n(5) Notwithstanding anything contained in Sub-secti on (1) or (2), the \nremedy available to a person who suffers any loss o r damage because of the \nfact that a company or its director or any person r esponsible for the \nmanagement or control of the company or its employe e has failed to do any act \nrequired to be done or done any act required not to  be done or otherwise done a \ndiscriminatory treatment shall not be deemed to be l imited to this Section only; \nand such person may institute an action, whether in dividually or jointly, on \nbehalf of him/herself or other shareholder, as well , to have any remedy \navailable under other prevailing law.  \n(6) Where a collective remedy is demanded pursuant to Sub-section (5), \nthe court may issue appropriate order with or witho ut making necessary inquiry \ninto some or all shareholders of that class.  \n(7) Notwithstanding anything contained elsewhere in  this Act, where the \ncourt has issued an order in a manner that the comp any shall not make any \namendment to its memorandum of association or artic les of association or shall \nmake an amendment to any specific matter for the pr otection of the rights and \ninterests of any or all shareholders, in such a case, no amendment shall be made \nto the memorandum of association or articles of ass ociation without obtaining \nprior approval of the Court.  \n(8) If a company makes any amendment to its memoran dum of \nassociation or articles of association by or pursua nt to an order of the Court \nunder Sub-section (7), such amendments shall be dee med to be an amendment \nadopted by a special resolution in the general meeting of the company.  \n(9) The Office shall make entry of the following or ders issued by the \ncourt pursuant to this Section in the company register: \n(a) An order issued for the reduction of share capital of a \ncompany; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 121  \n(b) An order issued requiring any amendment to the \nmemorandum of association or articles of associatio n of \nthe company.  \n(10) The provisions of this Section shall also appl y to any person who \nhas not yet been registered as a shareholder of a c ompany but the shares have \nalready been transmitted to his/her name through le gal procedures as if such \nperson were a shareholder of the company.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "140", "title": "Right to shareholder to institute case on behalf of  company", "content": ": (1) A company \nmay file in the Court a case against any director, office or shareholders or any \nperson having control over the company pursuant to the consensus agreement \nto have any rights and interests of the company enforced.  \n(2) If the company concerned fails to institute a c ase under Sub-section \n(1), any share holder holding two and half percent or more of the shares in the \npaid-up capital of the company separately or jointl y with two or more \nshareholders holding five percent shares may, on be half of the company, file in \nthe Court a case against any such director or offic er or the person having \ncontrol over the company or any other person.  \n(3) While filing a case by a shareholder pursuant t o Sub-section (2), \nhe/she shall state about what sort of effort he/she  has made to persuade the \ncompany to institute the case by itself.  \n(4) Where a case is filed pursuant to Sub-section ( 2), the Court may \ndecide whether it would be appropriate to keep on t he case being run by the \nshareholder or to get the company to take over the case, and if it is found \nappropriate to get the company to take over the cas e, it may order the company \nto take over the case.  \n(5) Any case once filed pursuant to Sub-section (1)  or (2) shall not be \ncapable of being dismissed or being compromised exce pt in cases where such \ncompromise contains such terms ad conditions as specified by the Court.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 122  \n(6) Where a case file pursuant to Sub-section (2) i s adjudged sustaining \nthe claim made by the claimant shareholder, the exp enses incurred by him/her \nin the institution of such case and reasonable expe nses made for the services of \nlegal practitioner shall be reimbursed by the compa ny. Where such claim is not \nsustained, such amount out of the expenses incurred  by the defendant in \ndefending such case as the Court thinks appropriate  shall be reimbursed from \nthe complainant shareholder.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "141", "title": "Acquisition or sale of property : (1) A public company or its subsidiary", "content": "company shall, if the purchase or sale of any prope rty by it results in the \nfollowing situation, give information thereof to the Office:  \n(a) If the purchase of any property results in an incre ase in the \nvalue of its property or the value of consolidated property \nmentioned in the audited latest annual financial st atement, \nby more than fifteen per cent ; \n(b) If the income to be earned from the property sold o r \nintended to be sold exceeds by more than fifteen pe r cent \nof the consolidated income before making payment fo r tax \nas mentioned in the audited latest books of account  of the \ncompany. \n(2) Any information to be given to the Office pursu ant to Sub-section (1) \nshall set out the following matters; and where such  matters are also applicable \nin the case of transaction of the company, such mat ters shall also be stated in \nthe report of board of directors:  \n(a) date of, and parties involved  in, the transaction; \n(b) Details about the nature of property, and if that p roperty \nincludes, wholly or partly, any shares issued by an y other \ncompany, the name of company issuing such shares an d \nthe nature of business to be carried on by that company; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 123  \n(c) Value of the transaction , and other terms and cond itions \nof the transaction; \n(d) The ground pursued for the valuation of property, w hile \nbuying or selling any property; \n(e) In the event of sale of any property, matter whethe r the \nproceeds of such sale is more or less than the book  value \nof such property as shown in the records thereof.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 13", "title": "Chapter 13", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "142", "title": "Control over subsidiary company : (1) A holding company may control its", "content": "subsidiary company as follows:  \n(a) By holding direct or indirect control over the form ation of \nthe board of directors; \n(b) By holding majority shares of the company. \n(2) If any company becomes a subsidiary company of any other \nsubsidiary company, the former company shall also b e a subsidiary company of \nthe holding company controlling the later company.  \n(3) Despite that the shares of a company are subscr ibed by any agent on \nbehalf of the holding company or its subsidiary com pany or that the right to \nappoint directors of such company is exercised by a ny person nominated on \nbehalf of the holding company or its subsidiary com pany, the conditions \nmentioned in Sub-section (1) shall be deemed to have been fulfilled.  \n Provided, however, that while determining a holdin g company and a \nsubsidiary company, the shares possessed in the fol lowing circumstances shall \nnot be recognized for this purpose: \n(a)  In cases where any company is entitled to exer cise any power on \nthe basis of holding  debentures or a trust deed on  the issue of \ndebentures or having subscribed shares; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 124  \n(b)  In cases where a company lending credit has ac cepted the  \n  shares by way of security.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "143", "title": "Documents to be enclosed : (1) Any holding company shall enclose the", "content": "following documents of its subsidiary company in its balance sheet:  \n(a) One copy of the annual accounts of the subsidiary \ncompany for the immediately expired financial year a nd  \nthe report of its board of directors during that period; \n(b) Auditor’s report; \n(c) Details of the investment of the holding company in  the \nsubsidiary company at he end of the financial year; \n(d) In cases where the financial year of the holding co mpany \nand that of the subsidiary company are different, t he \nmatter of change, if any, in any manner, of the rig ht of the \nholding company over the subsidiary company during \nsuch different periods.  \n(2) The details as referred to in Clause (b) of Sub -section (1) shall also \ncontain the net profits derived after deducting the loss suffered in the concerned \nfinancial year of the subsidiary company and the pr ofit and loss as well which \nhas not been mentioned in the accounts of the compa ny after it has become the \nsubsidiary company but which may be the concern of the shareholders of the \nholding company.  \n(3) In cases where the board of directors of the ho lding company fails to \nobtain the information as mentioned in Clause (b) o f Sub-section (1), and Sub-\nsection (2) due to any reason, the balance sheet of  the holding company shall \ncontain a written report thereof.  \n(4) The details as referred to in Clause (c) of Sub -section (1) shall also \nshow the loans borrowed against the mortgage of any  immovable property of \nthe subsidiary company or the loans borrowed for an y purpose other than \ndischarging the existing liabilities.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 125", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "144", "title": "Prohibition on investment in holding company : No subsidiary company;", "content": "shall purchase these shares or debentures of the ho lding company or make \ninvestment in the holding company in any other manner.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 14", "title": "Chapter 14", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "145", "title": "Consensus agreement : (1) Except as otherwise provided in this Act, the", "content": "following matters may be provided for in a consensu s agreement of a private \ncompany:  \n(a) Management, business and transaction of the company; \n(b) Restriction, if any, on the transfer of shares; \n(c) Power of one or more shareholders to liquidate the \ncompany owing to any specific or incidental event o r \nvoluntarily; \n(d) Division or use of voting right; \n(e) Terms of appointment of officers, employees , workers of \nthe company,  \n(f) Matter as to who will be the directors, officers, o r the \npersons bearing the ultimate responsibility or the chief \nexecutive, of the company; \n(g) Mode of payment or distribution of dividends; \n(h) Matter that there shall be no board of directors; \n(i) Matter that , if there shall be no board of directo rs, who \nshall perform such functions as required to be perf ormed \nby the board of directors under this Act; \n(j) If the annual general meeting is not required to be  held, \nprovisions pertaining thereto; \n(k) Types of shares and the provision of shares with di fferent \nright, if any.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 126  \n(2) The consensus agreement may be amended with the  consent in \nwriting of all parties to the agreement.  \n(3) The shareholders who, after the conclusion of a consensus agreement, \nhave obtained the shares as follows shall be deemed  to have consented to the \nagreement and become party thereof: \n(a) where the shares have been obtained by way  of dona tion \nor gift; \n(b) Where the shares have been obtained in any other ma nner, \nwith the knowledge of the existence of such agreeme nt at \nthe time of obtaining the shares.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "146", "title": "Power of shareholder to inspect books of account : (1) Any shareholder of a", "content": "private company or his/her  proxy may inspect the f ollowing documents or \nrecords related with the transactions of the company during office hours:  \n(a) Minute books of the general meeting and board of \ndirectors; \n(b) Annual financial statements; \n(c) Share register; and  \n(d) Accounts of the company. \n (2) The director or officer of a private company s hall make adequate \narrangement so that the shareholders could inspect the documents and records \nas referred to in Sub-section (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "147", "title": "Return of transactions", "content": ": (1) Any shareholder of a private company may \ndemand the company for a return of transactions of the company for any \nfinancial year.  \n(2) The director, managing director or officer carr ying on the \ntransactions of the company shall provide a return accompanied by the certified \nannual financial statement no later than fifteen da ys of the demand of return \npursuant to Sub-section (1).  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 127", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "148", "title": "Holding of annual general meeting not required : (1) Notwithstanding", "content": "anything contained elsewhere in this Act, where a c onsensus agreement \nconcluded between the shareholders of a private com pany has a provision that \nthe annual general meeting of the company shall not  be held, such private \ncompany shall not be required to hold its annual ge neral meeting during the \nperiod of such agreement.  \n(2) Where a consensus agreement is concluded with a  provision that the \nannual general meeting shall not be held pursuant t o Sub-section (1), the \ncompany shall also make provisions on the procedure  of making decision on \nsuch matters as required to be decided by the gener al meeting under this Act \nand on the authority of making such decision", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "149", "title": "Adoption of written resolution by private company :  (1) Notwithstanding", "content": "anything contained elsewhere in this Act, except as  otherwise provided in the \narticles of association  ,any act which  can be done by adopting a resoluti on \nincluding a special resolution in the general meeti ng of a private company or \nby adopting a resolution in the meeting of any part icular class of shareholders \ncan be done by a written resolution executed and si gned by  all shareholders \nrepresenting at least seventy five percent shares, who are entitled to vote in \nholding discussion on such resolution on the same d ate on which such \nresolution is deemed to have been adopted.  \n(2) Where separate written resolutions have been re corded for any \nreason for the purposes of a Sub-section (1) and al l such documents have the \nsame contents, it shall not be necessary that all s hareholders sign the same \ndocument;; and despite the fact that every sharehol der has signed a separate \ndocument, such document shall be valid as if one wr itten resolution were \nsigned.  \n(3) Every shareholder signing a written resolution pursuant to this \nSection shall date the same; and the last date on w hich the resolution is signed \nby the shareholder shall be deemed to be the date o n which the resolution has \nbeen adopted.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 128  \n(4) Any document attached to any written resolution  shall be deemed to \nhave been presented in a meeting of shareholders signing the resolution.  \n(5) Any resolution accepted pursuant to this sectio n shall be recognized \nfor any purpose whatsoever as it were a decision ad opted by a general meeting \nof a company or a meeting of any specific class of shareholders.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "150", "title": "Deemed participation in general meeting : (1) Notwithstanding anything", "content": "contained elsewhere in this Act, if, except, as oth erwise provided in the articles \nof association of a private company, any shareholde r of the company makes \ncommunication contact with all shareholders through any communication \nmeans and takes part in communication contact with other shareholders in such \na manner that the other shareholders can hear or re ad whatever is spoken by \nevery shareholder, every shareholder who so takes p art in such communication \ncontact shall be deemed to have taken part in the g eneral meeting along with \nother shareholders.  \n(2) Notwithstanding anything contained elsewhere in  this Section, where \nany shareholder makes a complaint/petition accompan ied by the prescribed \nfees , to the Office no later than three months aft er the holding of a general \nmeeting, mentioning that he/she has not taken part in the general meeting, the \nOffice shall inquire into the concerned company; an d, in holding such inquiry, \nwhere the company fails to prove that the complaina nt shareholder has taken \npart in such meeting, the decision made by that meeting shall not be valid.  \n(3) A meeting of shareholders conducted pursuant to  Sub-section (1) \nshall be deemed to have been conducted in the place  where the chairperson of \nthe meeting is present.  \n(4) The provisions of Sub-section (1), (2) or (3) a pplicable to the general \nmeeting of a company shall also apply, mutatis mutandis , to the meeting of \ndirectors or a sub-committee of directors of the company.  \n(5) After the completion of the general meeting pur suant to Sub-section \n(1), the chairperson of the meeting shall prepare m inutes of the proceedings \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 129  \nand decisions conducted and taken in the meeting an nually and authenticate the \nsame.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "151", "title": "Special exemption companies carrying on prescribed transaction : The", "content": "Government of Nepal may, by a notification in the N epal Gazette, exempt the \nprivate company having turnover within the prescrib ed limit from the \nprovisions contained in Chapter-8.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 15", "title": "Chapter 15", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "152", "title": "Single shareholder company not required to call mee ting of the board of", "content": "director and general meeting : Notwithstanding anything contained elsewhere \nin this Act, except as otherwise provided in the ar ticles of association of a \nsingle shareholder company, all acts and decisions required to be done and \nmade by the board of directors or general meeting o f the company shall be as \ndecided in writing by such shareholder; and no meet ing of the board of \ndirectors or general meeting shall be required to be called.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "153", "title": "Transfer and transmission of shares of single share holder company:  (1) In", "content": "the event of death of the shareholder of a single s hareholder company, his/her \nheir or the person acquiring the title to his/her s hares shall acquire the right of \nshareholder, and such heir or person shall do all s uch acts inclusive of the \ntransfer and transmissions of shares as the single shareholder can do under this \nAct. While making a decision to transfer and transm it shares, the person so \nacquiring the title shall make such decision in writing.  \n Provided, however, that if no heir to such shareho lder is found, the \nOffice shall appoint a liquidator and liquidate the  company in accordance with \nthe prevailing law.  \n(2) A person acquiring the title to shares pursuant  to Sub-section (1) \nshall give information thereof, accompanied by the evidence of such title, to the \nOffice no later than one month after the acquisition of such title.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 130  \n(3) On receipt of the information as referred to in  Sub-section (1), the \nOffice shall record the information by collecting t he prescribed fees and give \ninformation thereof to the person who acquires the title to shares.  \n(4) Where the number of person acquiring the title to shares pursuant to \nSub-section (1) is more than one, they shall be con sidered to be the directors of \ncompany for the time being, except where the other heirs transfer the title to \nonly one heir, and the memorandum of association an d articles of association \nof the company shall be amended on that basis.  \nProvided, however, that where there arises a questi on of entitlement, such \nmatter shall be governed by a judgment of the competent court.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 16", "title": "Chapter 16", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "154", "title": "Registration of foreign company : (1) No foreign company shall carry on any", "content": "business or transaction in the Nepal without having  a branch office of such \ncompany registered with the office of such company registered with the office \npursuant to this Section or establishes such office  without having a liaison \noffice registered.  \n Provided, however, that making investment in share s in any company \nestablished pursuant to law, lending moneys to such  company or participating \nin the operation or management of  such company, wi th the approval of the \ncompetent body, shall not be deemed to be the carry ing on of a business or \ntransaction  for the purposes of this Chapter .  \nExplanation \n: Where any foreign company carries on any transact ion for a \nperiod of one month or more through an office estab lished in Nepal or used \ntherefor or appoints any person for regular contact  or avails its service, such \ncompany shall be deemed to have done a transaction or established an office in \nNepal for the purpose of this Chapter.  \n(2) A foreign company desiring to have its branch o ffice registered \npursuant to Sub-section (1) shall make to the Offic e an application, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 131  \naccompanied by the permission obtained from the con cerned body pursuant to \nthe prevailing law, and the prescribed fees and in such format as prescribed, for \nthe registration of such company.  \n(3) A foreign company desiring to have its liaison office registered \npursuant to Sub-section (1) shall make to the Offic e an application, \naccompanied by the permission, if any, required to be obtained from the \nconcerned body pursuant to the prevailing law for t he registration of such \noffice, and the prescribed fees and in such format as prescribed, for the \nregistration of such company.  \nExplanation \n: where any foreign company is selected by any comp etent body \npursuant to the prevailing law o r enters into cont ract with any competent body, \nfor any business in Nepal, the making of such selec tion entering into such \ncontract shall, for the purposes of Sub-sections (1 ) and (2) , be deemed to be \nthe permission given by the concerned body.  \n(4) On receipt of an application made for the regis tration of a foreign \ncompany pursuant to Sub-section (2) or (3), the Off ice shall make necessary \ninquiry, register such company and give the registr ation certificate, as \nprescribed, no later than thirty days after the mak ing of the application for \ncarrying on a business or transaction in or establi shing a liaison office in the \nNepal.  \n(5) Where a foreign company cannot be registered pu rsuant to an \napplication made under Sub-section (2) or (3), the Office shall give information \nthereof, setting out the reasons for the same, to t he concerned applicant within \nthirty days.  \n(6) A foreign company registered pursuant to Sub-se ction (4) may open \nits branch office and carry on the concerned busine ss or transaction in or open \nits liaison office in the Nepal.  \n Provided, however, that a foreign company register ed as a liaison office \nshall not be entitled to do any income earning activity in Nepal.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 132  \n(7) Where the name of a foreign company making appl ication pursuant \nto Sub-section (2) or (3) or the objective to be im plemented by such company \nis of such a nature that it cannot be registered pu rsuant to this Act, such foreign \ncompany shall not be registered in Nepal.  \n(8) A foreign company registered pursuant to Sub-se ction (4) shall be \ndeemed to have been registered to carry on only the  same type of business or \ntransaction as is being carried on by it in the cou ntry where its registered office \nis situated or it has been incorporated. \n(9) A foreign company registered pursuant to this S ection shall put its \nname board in the place of its business in a manner  conspicuous to all,, and the \nname of country where the company has been establis hed and the registration \nnumber of the company registered in Nepal shall be clearly mentioned in such \nboard and bills, receipts , invoices, etc or letter  head to be used by the company.  \n(10) The office shall maintain a separate register for the registration of \nforeign companies registered pursuant to this Secti on and make arrangements \nfor the inspection of such register by the general public and for getting a copy \nthereof by paying the prescribed fees.  \n(11) Notwithstanding anything contained elsewhere i n this Act, a \nforeign company registered pursuant to this Section  shall not issue shares or \ndebentures within the Nepal. \n(12) Notwithstanding anything contained elsewhere i n this Act , a \nforeign company which is carrying on a business or transaction or which has \nestablished its liaison office  in the Nepal withou t having been registered at the \ntime of commencement of this Act shall get it regist ered with the Office \npursuant to this Act no later than six months after the date of commencement of \nthis Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "155", "title": "Submission of documents by foreign companies : (1) A foreign company", "content": "which makes an application for its registration or for the establishment of its \nliaison office pursuant to Section 154 shall submit  to the Office the following \ndetails, along with the application: \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 133  \n(a) Permission obtained by the foreign company from the \ncompetent authority to carry on its business or tra nsaction \nin Nepal; \n(b) Copies of the charter, certificate of incorporation , \nmemorandum  of association, articles of  associatio n of the \ncompany, and  Nepalese translation thereof; \n(c) Full name, address of the registered office and pri ncipal \nplace of business of the company, date of incorpora tion of \nthe company, description of the paid up capital and  major \nobjectives of such company; \n(d) Names, addresses  of directors, manage, company \nsecretaries or main officers of the company and \ndescription of their citizenship; \n(e) Name and address of the person residing or  staying  in the \nNepal ,who is authorized by the company to receive,  on its \nbehalf, any summons, notice etc. issued in the name  of the \ncompany; \n(f) Full address of the principal place where the compa ny \ncarries on its transaction or business in Nepal and  of the \noffice  of the company situated in that place; \n(g) Where the company is to carry on any transaction or  \nbusiness in the State of Nepal, details of the prop osed \ninvestment and transaction; \n(h) Where the company is to commence its transaction in \nNepal, the proposed date thereof; \n(i) A declaration made by a director of the company or \nhis/her representative, on behalf of the company, t hat the \nmatters contained in the returns submitted by the c ompany \nare true and correct; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 134  \n(j) Power of attorney as referred to in Section 157.  \n(2) Where any amendment or alteration is made to or  in the contents of \nany document submitted by any foreign company pursuant to Sub-section (1), a \nnotice, accompanied by the details of such amendmen t or alteration, shall be \ngiven to the Office no later than thirty five days.  \n(3) While submitting any such documents issued outside Nepal or copies \nthereof as required to be submitted pursuant to Sub -section (1), they have to be \ncertified pursuant to the law of the country of reg istration of the foreign \ncompany.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "156", "title": "Books of account, audit and annual report of foreig n company : (1) Every", "content": "foreign company registered pursuant to Section 154 shall prepare an annual \nfinancial statement, along with the balance sheet a nd profit and loss account, in \nsuch a manner as to reflect the real situation of i ts transaction in Nepal, get it \naudited and submit the same to the Office no later than six months after the \nexpiration of a financial year as if such company w ere a company incorporated \nunder this Act.  \n(2) Every foreign company shall submit to the Offic e a copy of the \nannual financial statement, audit report and report  of board of directors \nprepared for every financial year pursuant to the l aw of the country where its \nregistered office is situated no later than three m onths after such statement and \nreports have been finally prepared.  \n(3) The annual financial statement to be prepared b y a foreign company \npursuant to Sub-section (1) shall include the following details:  \n(a) Statements prepared in a manner to show classifying  the \nparticulars of the fixed, running and other propert ies held \nin the name of the foreign company within Nepal;  \n(b) clear details of cash held in the name of the forei gn \ncompany with a bank and financial institution situa ted in \nNepal; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 135  \n(c) Clear details of cash held in the name of the forei gn \ncompany with a bank and financial institution situa ted in \nNepal; \n(d) Total amount of loans and liabilities, if any, due and \npayable by the foreign company to any person who is  a \nresident of Nepal or a Nepalese company registered under \nthis Act.  \n(4) Where any report and statement required to be s ubmitted to the \nOffice pursuant to Sub-section (2), and any documen t required to be attached \ntherewith, are in a language other than the Nepali or English language, a copy \nof authentic translation of such document into the Nepali or English language \nshall also be attached therewith.  \n(5) A foreign company which has got its liaison off ice registered in \nNepal pursuant to Section 154 shall get certified b y an auditor the statements of  \nsalary, allowance and amounts paid to the employees , consultants or liaison \npersons serving in such office, statements of deduc tion of tax from such \npayment pursuant to the prevailing law, payment of rental and expenses for the \noperation of such office and statements of deductio n of tax  from such payment \npursuant to the prevailing law, and submit the same to the Office no later than \nthree months after the expiration of a financial year.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "157", "title": "Power of attorney: (1) A foreign company to be registered pursuant to  Section", "content": "154 shall submit  office copy of a power of attorne y executed in the specified \nformat in accordance with the legal requirements of  the country where the \ncompany has been incorporated or its registered off ice is situated, hereby \nappointing a person residing in Nepal as its author ized representative for the \npurposes of  the service of any summons or notice or  authorizing such person \nto receive any other lawful notices on a lawsuit or  legal action  instituted on \nbehalf or legal against the company .  \n(2) A power of attorney executed pursuant to Sub-se ction (1) shall state, \ninter alias that where any summons or notice on a lawsuit inst ituted on behalf \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 136  \nof or against the company or other legal notice is delivered to the authorized \nrepresentative, it shall be binding on the company for any purpose whatsoever.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "158", "title": "Cancellation of registration and liquidation of a f oreign company : (1)", "content": "Where a foreign company registered pursuant to Sect ion 54   wishes to  close \ndown the transaction which it is carrying on in Nep al and get its registration \ncanceled or where the competent authority, acting i n accordance with the \nprevailing law, prohibits such company from carryin g on the transaction or \nbusiness within Nepal, such company shall make an a pplication, accompanied \nby the prescribed fees, o the Office for the cancellation of its registration.  \n(2) A foreign company which makes an  application p ursuant to Sub-\nsection (1)  shall also submit, along with the appl ication, an evidence and proof \nconfirming that there is no liability due and payab le by  such company too any \nperson, organization or governmental or non-governmental body in Nepal. \n(3) In order to inquire whether the evidence and pr oof as referred to in \nSub-section (2) are true or not, the Office shall p ublish at least twice in a \nnational daily newspaper a notice inviting a claim,  accompanied by evidence, \non any liability, if any due and payable by the com pany to any one, within a \nperiod of twenty one days.  \n(4) Where any person makes a claim in pursuance of the notice \npublished pursuant to Sub-section (3), the concerne d company shall submit to \nthe Office evidence or proof showing the settlement  of such claim.  Where the \nclaim made against such company pursuant to Sub-sec tion (1) cannot be settled \nfrom the assets of such company situated in Nepal, such company shall settle \nthe same from its assets situated outside Nepal.  \n(5) Where no claim is made by any one within the ti me limit as referred \nto in Sub-section (3) or a proof is submitted showi ng than the claim made has \nbeen settled pursuant to Sub-section (4), the Offic e shall strike the name of \nsuch company off the foreign company register and g ive information thereof to \nthe concerned company.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 137  \n(6) Where an insolvency process is initiated in res pect of a foreign \ncompany, which has been registered in Nepal pursuan t to this Chapter, in \naccordance with the law of any country out of the  countries where such \ncompany has been carrying on its transaction, the r epresentative authorized by \nsuch foreign company pursuant to Section 157 shall promptly give a notice in \nwriting thereof to the Office, and he/she shall als o publish such notice in a \nnational daily newspaper to be published from Nepal for the  information of the \ngeneral public.  \n Provided, however, that where an order for the can cellation of \nregistration of such company has already been issue d, such foreign company \nshall close its transaction or business in Nepal.  \n(7) Where any foreign company closes its transactio n or business \npursuant to the proviso to Sub-section (6) , the pr evailing law on insolvency \nshall govern the transaction or business carried on  by such company in the \nState of Nepal .", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter- 17", "title": "Chapter- 17", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "159", "title": "Complaints and proceedings relating to cases under this Act : (1) In respect", "content": "of any matter under this Act, a case may be filed a nd proceedings taken only \nwith a complaint made by the Office or the director , officer, shareholder or \nmember or creditor of a company or any other concerned person.  \n(2) Except in cases where jurisdiction is expressly  given to the Office on \nany matter under this Act, the Court shall have pow er to hear and settle the \ncases on offenses punishable under this Act, the ma ttes on which a complaint \nor application can be made to the Court as mentione d in various Sections of \nthis Act and matters of compensation for amounts in controversy.  \n(3) In hearing and settling cases under this Act, t he Court shall follow \nthe procedures as referred to in the Summary Procedure Act, 2028 (1972).  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 138  \n(4) An appeal against any decision or order made or  issued by the Office \nof Court under Sub-section (2) may be made to the C ourt as specified by the \nGovernment of Nepal with the consent of the Supreme  Court, within thirty-five \ndays.  \n(5) Notwithstanding anything contained in Sub-secti on(2), pending the \nspecification of the Court by the Government of Nep al by a notification in the \nNepal Gazette for hearing cases, suits and taking o ther actions pursuant to this \nAct, the Company Board formed pursuant to Section 1 691  shall assume the  \njurisdiction of the concerned Court.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "160", "title": "Punishment with fine not exceeding fifty thousand r upees or with", "content": "imprisonment for a term not exceeding two years or with both : The \nfollowing person who commits the following offense shall be punished with a \nfine from twenty thousand rupees to fifty thousand rupees or with \nimprisonment for a term not exceeding two years or with both punishments:  \n(a) Where any director or officer of a company has caus ed any loss or \ndamage to the company or any person by mentioning a ny false matter in \nany document of the Company, with mala fide  intention or malicious \nrecklessness, such director or employee; \n(b) Where any director or officer of a company fails to  maintain, or cause to \nbe maintained, hides or conceals or damage such boo ks of account or \naccounts as required to be maintained pursuant to this Act, such person; \n(c) Where the auditor of a company states a  false matt er in his/her report in \nthe course of carrying out his/her duty or omits ne cessary comments \nwhile making audit, with mala fide  intention or malicious recklessness, \nsuch auditor; \n(d) Where, a liquidator does not convene the meting of creditors, or makes \npayment of loans or liabilities contrary to the ord er of priority or fails to \nmaintain such books of account and accounts as requ ired to be \nmaintained under this Act or fails to take over suc h books of accounts \nand documents as required to be taken over, or main tains false accounts, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 139  \nor fails to submit any report required to be submit ted or fails to hand \nover cash, goods in-kind or books to be handed over  by him/her on the \ntermination of  his/her assignment, with ulterior m otive, recklessness or \nmala fide  intention, such liquidator; \n(e) Where any director or officer or employee fails to hand over the \ndocuments, accounts, cash goods in –kind in this ch arge on the \ntermination of his/her office or on receipt of a or der to liquidate the \ncompany, to the successor or where the successor fa ils to take over them \npursuant to this Act, such director, officer and em ployee who do not \nhand over or take over them; \n(f) Any director or officer who issues the prospectus o f a company prior to \nits being registered with the Office who gives fals e details in the \nprospectus; \n(g) Where any act is done beyond the jurisdiction of th e board of directors \nor beyond the scope of work of the company, any director or officer who \ndoes or orders to do such act; \n(h) Any shareholder who does not provide any returns pu rsuant to this Act \nor gives false returns; \n(i) Any director or officer or employee who misappropri ates or embezzles \ncash or goods in-kind of the company or uses the ca sh or goods in-kind \nof the company for his/her personal use without the  approval of the \nboard of directors or the general meeting or does n ot settle advances \naccording to the rules of the company or does not a bide by any order \nissued by the Office or fails to submit any returns of the company; \n(j) Where any director or officer who has the duty to g ive any statements or \ninformation to the company, Office, Court or other body pursuant to this \nAct fails to give such statements of information, such director or officer; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 140  \n(k) An auditor who knowingly carries out auditing of th e concerned \ncompany even after that he/she is not qualified to carry out auditing of \nany company; \n(l) An director or officer who exercises the powers not  conferred to him/her \nor acts beyond the authority conferred to him/her; \n(m) An director or officer who maintains account in con travention of this \nAct; \n(n) Any director of officer who fails to provide such e xtracts of financial \nstatement, annual financial statement or report as required to be \nprovided to the shareholders pursuant to this Act; \n(o) Any director or substantial shareholder or company who receive or give \nany loan facility or remuneration from the company in a manner to be \ncontrary to the provisions contained in this Act; \n(p) An company, officer, employee or any other person w ho, in seeking \napproval of the Court to reduce the share capital o f the company, lies or \nhides the name of any creditor or gives false state ments as to the loans \nborrowed by the company; \n(q) An private company which sells shares or debentures in contravention of \nthis Act, directors and shareholders of such company; \n(r) An foreign company which carries on business or tra nsaction in Nepal \nin contravention of this Act, directors, employees or representatives of \nsuch company; \n(s) A debenture trustee who acts contrary to the intere st of the holders of \ndebenture, directors or officers of such trustee; \n(t) A person who acts contrary to Sub-section (7) of Section 26; \n(u) An director or officer who fails to do any act requ ired to be done \npursuant to Section 60; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 141  \n(v) An person who carries on transaction by using the w ord “company” \nwithout getting a company registered pursuant to this Act; \n(w) An company, director or officer who fails to provid e the information or \nnotice as referred to in Section 141 or Section 175; \n(x) An shareholder of a company who does not provide su ch information as \ndemanded pursuant to Section 47 or the company, dir ector and officer \nwho does not submit to the Office the information r eceived from the \nshareholder pursuant to that Section; \n(y) An director or officer who acts contrary to Section 105; \n(z) The managing director, director or officer of a com pany who fails to \nprovide the address of registered office of the com pany despite the \nissuance of written order by the Office at various times or giving of such \nnotice through communication media, where such issua nce was not \npossible; \n (z1) A company, director, substantial shareholder and officer who acts \ncontrary to Section 50.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "161", "title": "Punishment with fine not exceeding fifty thousand r upees : The following", "content": "person who commits the following offense shall be pu nished with a fine from \nten thousand rupees to fifty thousand rupees:  \n(a) Where any shares are allotted in contravention of t he provisions of this \nAct, the officer or person who makes such allotment; \n(b) Where a company purchases, out of the company’s cap ital in stock, its \nown shares or the shares of its holding company con trary to this Act or \nmakes investment in contravention this Act, every d irector of that \ncompany; \n(c) In the event of failure to show or provide the book s if account to the \nauditor as and when so required, the officer or per son who has the duty \nto do so or provide the same; \n(d) An auditor who does not present a report as specified in the Act; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 142  \n(e) An director, manager and officer who  does not make  arrangements as \nreferred to in Sub-section(3) of Section; 172; \n(f) An director and officer who violates the provisions  of Section 146 or \n147 or who does not maintain such records books or returns as required \nto be maintained pursuant to this Act; \n(g) An company, director, auditor, officer and employee  who violate the \nprovision contained in Chapter-18 or who fail to fu lfill the duty and \nobligations specified in that Chapter; \n(h) In the event of failure to call the general meeting  or a meeting of the \nboard of directors required to be called pursuant t o this Act or failure to \nsend a notice of the general meeting or a meeting o f the board of \ndirectors or failure to prepare the documents to be  made available to the \nshareholders before the holding or the general meeti ng or failure to \npresent in the general meeting such documents as re quired to be \npresented, the director, officer  or person who has  the duty to maintain \nor do such act or to call the meeting or to send such notice; \n(i) An officer who sets down any false deed or content of document stating \nthat any matter which was neither done or happened to have been done \nor happened and vice versa  in the minutes as referred to in Sub-section(1) \nof Section 75 and Sub-section (7) of Section 97 or such other return or \nreport as required to be prepared an submitted to t he company or Officer \nin such notice or information as required to be pro vided pursuant to this \nAct; \n(j) In the event that an declaration made by the direct ors pursuant to Sub-\nsection(2) of Section 136 is held to be false, the director who makes \nsuch false statement; \n(k) An person who does false or wrong translation of an y deed or document \nrequired to be submitted by a foreign company to th e Office pursuant to \nthis Act or any person who certifies the same.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 143", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "162", "title": "Punishment with fine not exceeding twenty thousand rupees : Except in", "content": "matters contained in Sections 160 and 161, the Cour t may impose a fine of five \nthousand rupees to twenty thousand rupees on any co mpany or every \nconcerned director, managing director, manger, comp any secretary or \nemployee of the company who fails to perform any act which he/she is required \nto perform under this Act or commits any act  prohib ited by this Act, or fails to \nperform his/her duty, or performs even any permissi ble act upon the expiry of \nthe time-limit or without following the procedures,  or fails to give such \ninformation to the Office as required to be given, or fails to submit such returns \nto the Office as required to be submitted.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "163", "title": "Realization of amount of loss : If a director, officer of an company or a person", "content": "causes any loss or damage to the company or shareho lder or creditor or any \nother person by committing an offense punishable un der this Act or by \nviolating any provision contains in this Act or the  memorandum of association \nor articles of association or consensus agreement, the aggrieved company, \nshareholder, creditor or any person shall be entitl ed to have realized the amount \nof such loss or damage. He /She shall personally be ar the amount of such loss \nor damage.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 18", "title": "Chapter 18", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "164", "title": "Audit Committee : (1) A listed capital with paid up capital of thir ty million", "content": "rupees or more or a company which is fully or partl y owned by the \nGovernment of Nepal shall form an audit committee un der the Chairpersonship \nof a director who is not involved in the day-to –da y operations of the company \nand consisting of a least three members .  \n(2) A person who is a close relative of the chief e xecutive of a company \nshall not be eligible to be a member of the audit c ommittee formed pursuant to \nSub-section (1).  \n(3) At least one member of the audit committee shall  be an experienced \nperson having obtained professional certificate on accounting or a person \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 144  \nhaving gained experience in accounting and financia l field after having \nobtained at least bachelor’s degree in accounts, co mmerce, management, \nfinance or economics.  \n(4) The report of board of directors required to be  prepared by a \ncompany shall set out a short description of the ac tivities of the audit \ncommittee, working policies adopted by the board of directors to implement the \nsuggestions, if any, given by the audit committee, the allowances or facilities ,if \nany, received by the members or the audit committee and the names of the \nmembers of audit committee.  \n(5) The audit committee may, for inquiring into any matter, notify the \nmanaging director of the company, chief executive o r the company or other \ndirector, auditor, internal auditor and accounts ch ief involved in the day-to-day \noperations of the company to attend its meeting; an d it shall be their duty to be \npresent in the meeting of that committee if they are so notified.  \n(6) The board of directors shall implement the sugg estions given by the \naudit committee in respect of the accounts and finan cial management the \ncompany; and where any suggestion cannot be impleme nted, the board of \ndirectors shall also mention the reasons for the same in its report.  \n(7) A company shall arrange for such means and reso urces as may be \nadequate for the fulfillment of responsibilities of  the audit committee; and the \naudit committee may fix its internal rules of procedures on its own.  \n(8) The chairperson of the audit committee shall be present in the annual \ngeneral meeting of the company.  \n(9) The audit committee shall meet as per  necessity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "165", "title": "Functions, duties and powers of audit committee : The functions, duties and", "content": "powers of the audit committee formed pursuant to Su b-section (1) of Section \n164 shall be as follows:  \n(a) To review the accounts and financial statements of the company and \nascertain the truth of the facts   mentioned   in such  statements; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 145  \n(b) To review the internal financial control system and  the risk management \nsystem of the company; \n(c) To supervise and review the internal auditing activity or the company; \n(d) To recommend the names of potential auditors for th e appointment of \nthe auditor of the company, fix the remuneration an d terms and \nconditions of appointment of the auditor and presen t the same in the \ngeneral meeting for the ratification thereof; \n(e) To review and supervise as to whether the auditor o f the company has \nobserved such conduct, standards and directives det ermined by the \ncompetent body pursuant to the prevailing law as re quired to be \nobserved in the course of doing auditing work; \n(f) Based on the conduct, standard and directives deter mined by the \ncompetent body pursuant to the prevailing law, to f ormulate the polices \nrequired to be observed by the company in respect o f the appointment \nand selection of the auditor; \n(g) To prepare the accounts related policy of the compa ny and enforce, or \ncause to be enforced, the same; \n(h) Where any regulator body has provided for the long  term audit report to \nbe set out in the  audit report o f the company, to  comply with the terms \nrequired to prepare such report; \n(i) To perform such other terms as prescribed by the bo ard of directors in \nrespect of the accounts, financial management and audit of the company.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter- 19", "title": "Chapter- 19", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "166", "title": "Establishment of company not distributing profits : (1) Notwithstanding", "content": "anything contained elsewhere in this Act, any compa ny may be incorporated to \ndevelop and promote any profession or occupation or  to protect the collective \nrights and interests of the persons engaged in any specific profession or \noccupation or to carry on any enterprise for the at tainment of any scientific, \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 146  \nacademic, social, benevolent or public  utility or welfare objective on the \ncondition of  not distributing dividends.  \n(2) Any person or trustee of a public trust registe red pursuant to the \nprevailing law or any other corporate body incorpor ated pursuant to the \nprevailing law who wishes to register  a company fo r the attainment or the \nobjective mentioned din Sub-section(1) may make an application to the Office \npursuant to Section 4.  \n(3) The number of promoters promoting a company pur suant to  sub- \nsection  (1)  shall  be  at least five; and after  the  incorporation  such  company,   \nit may have  any number of its members, with a minimum of five members.  \n(4) The membership of a company incorporated pursua nt to Sub-section \n(1) shall not be transferable in any manner.  The m embership of any person or \nbody shall ipso facto  be terminated in the event of death, cancellation of \nregistration or dissolution of such member or amalg amation of such member \nwith another body or company.  \n(5) Except with the prior approval of the Office, a company incorporated   \npursuant to Sub-section (1) shall not add words suc h \"company\", \"limited\" or \n\"private limited\" at the end of its name.  \n(6) A company registered pursuant to Sub-section (1 ) shall obtain \napproval of the Office to expand its branch.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "167", "title": "Special provisions relating to company not distribu ting profits:  (1)", "content": "Notwithstanding anything contained in this Act or t he prevailing law, the \nfollowing matters of a company incorporated pursuan t to Section 166 shall be \nas follows:  \n(a) There shall not be required share capital to incorp orate a \ncompany not distributing profits.  \n Provided, however, that the company may receive \nmembership fees from its members and receive any \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 147  \ndonation, gift pursuant to law for the accomplishme nt of \nits objectives.  \n(b) No member of the company shall be liable for the de bts \nand liabilities of the company except in the case where any \nmember accepts such liability in writing the liabil ity of the \ncompany, with specification of the limit of such li ability; \nhis/her liability shall be limited to the extent of that limit.  \n(c) All the provisions of this Act as applicable to the  listed \ncompany, other than those provisions which may be \napplicable only to the company with share capital, shall \nalso apply to the company, its director, officer, a uditor and \nemployee. \n(d) The company shall not distribute dividend, bonus or  any \nother amount, from the profits earned by it, to its  members \nor employees; and the profits earned by the company  shall \nbe used to increase the capital of the company or f or the \nattainment of its objectives.  \n(e) The company  shall  obtain  prior  approval  of  th e Office \nto change objectives. \n(f) Any company not distributing profits shall not be m erged \nwith any company distributing profits. \n(g) The members of a company incorporated under this \nChapter shall elect the directors from amongst them selves \nin such number as fixed in the articles of associat ion, on \nthe basis of one member one vote.  \n(h) The meeting allowance, salary, facility receivable by the \nofficers or a company incorporated under this Chapt er and \nthe incorporation and operational expenses of the company \nshall not exceed the amount as specified by the Office; and \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 148  \nin  so specifying  expenses, the Office shall have regard to \nthe capital situation and profits of such company.  \n(i) In the event of liquidation of or cancellation of r egistration \nof a company incorporated under this Chapter ,the a ssets \nof the company, if any , remaining after the settle ment of \nthe debts and liabilities of the company shall be d ealt with \nas per the provision, if any, contained in its articles of  \nassociation, and failing such provision, such asset s shall \ndevolve on the Government of  Nepal .  \nProvided, however, that such assets shall, in no wa y, \ndevolve on any body or company where a promoter or \nmember of such company or his/her close relative or  close \nrelative of such relative is a promoter or member.  \n(2) In the event of violation of any provision cont ained in Sub-section \n(1), the Office may cancel the registration of the company committing such \nviolation.  \n Provided, however, that the company shall be provi ded with an \nopportunity to defend itself, prior to such cancellation of registration.  \n(3) A person who is not satisfied with a decision o n cancellation of \nregistration made by the Office pursuant to Sub-sec tion (2) may file a \ncomplaint in the Court within thirty five days afte r the receipt of information of \nsuch decision.  \n(4) While canceling the registration pursuant to Su b-section (2), the \nOffice shall appoint a liquidator and an auditor to  complete the liquidation \nproceedings of such company, specifying the period for completion of such \nliquidation proceedings.  \n(5) The liquidator and auditor appointed pursuant t o Sub-section (4) \nshall discharge their functions in accordance with the provisions contained in \nthis Act and the prevailing law.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 149", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter- 20", "title": "Chapter- 20", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "168", "title": "Formation of Company Advisory Board : (1) The Government of Nepal shall,", "content": "by a notification published in the Nepal Gazette, f orm a Company Advisory \nBoard comprising a maximum of nine members consisti ng of one person from \neach of the fields of law, accounting profession, t ax administration, commerce \nor trade administration, from amongst those who have  done at least master’s \ndegree in the respective fields  and gained experti se after having served for at \nleast seven years in such fields in the government and private sectors, as well \nas a representative of the Federation of  Nepalese Chamber of Commerce and \nIndustries, so as to study the practical problems c oming across in the field of \nimplementation of this Act and prevailing law relat ing to company \nadministration and give advice, as required, to the  Government of Nepal on \ntimely reforms to be made in the prevailing companie s law and reforms in the \ncompany administration. The Registrar shall be the member secretary of the \nCompany Advisory Board.  \n(2) While forming the Company Advisory Board pursua nt to sub –\nsection (1), the notification shall designate any o ne of the members of the \nBoard also to act as its chairperson.  \n(3) The Company Advisory Board shall submit to the concerned \nMinistry of the Government of Nepal, an annual repo rt on the activities carried \nout by it pursuant to Sub-section (1).  \n(4) The concerned Ministry shall publish the report  submitted pursuant \nto Sub-section (3) and make arrangement so that the general public can obtain a \ncopy of such report at a reasonable price.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "169", "title": "Provisions relating to Company Board : (1) Pending the designation of a", "content": "court by the Government of Nepal pursuant to the pr ovisions contained in this \nAct, the Government of Nepal shall, by a notificati on published in the Nepal \nGazette, form a three–member Company Board, consisting the Chairperson and \nmember, as follows:  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 150  \n(a) A person who is a District Judge or  who has \nalready been a District Judge or who is qualified \nfor appointment as District Judge, with each \nsuch person, having done bachelor degree in \nlaw and gained experience in commercial law      \n -Chairperson \n(b) A person who, after being registered as an \nadvocate pursuant to the prevailing law, has \ndone legal practice in the field of commercial   \nlaw for a least ten years or  who has served in \nthe post  of Gazetted Class Two of Nepal \nJudicial Service for at least four years  -Member \n(c) A person who has done bachelor degree in \nmanagement, commerce or accounting and \nworked in the field of company management, \ntax administration or accounting for at least ten \nyears or an accounting professional who has \nobtained a professional certificate in  \naccounting and gained at least five years of \nexperience in accounting profession -Member \n(2) Notwithstanding anything contained in Clauses ( a) , (b), (c), or (d) of \nSub-section (1), the Government of Nepal may, by a notification published in \nthe Nepal  Gazette , designate any member, out of t he members of the \nCompany Advisory Board formed pursuant to Section 1 68, who has the \nqualification as mentioned in the said Clauses, also to act as the  Chairperson or \na member  of the Company Board to be formed pursuant to this Section.  \n(3) The Board formed pursuant to Sub-section (1) or  (2) shall exercise \nthe jurisdiction conferred to the Court pursuant to this Act.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 151  \n(4) The company Board formed pursuant to Sub-sectio n (1) or (2) shall, \nwhile hearing and settling the cases pursuant to Su b-section (3) ,exercise its \njurisdiction as follows:  \n(a) Three members shall jointly exercise their jurisdiction.  \n Provided, however, that, where the Chairperson and  \nanother one member are present, the case may be hea rd \nand settled, and where other two members except the  \nChairperson are present, the case may be heard.  \n(b) In the event of the presence of all the three membe rs, the \nunanimous opinion of all the three members or the \nmajority opinion of two members shall be deemed to be \nthe decision of the Company Board.  \n(c) In the event of the presence of two members only, w here \nthe two members have the same opinion, that opinion  shall \nbe the decision of the Company Board.  \n(d) In the event of the presence of two members, where they \nlack unanimity in opinion, the opinion of the Chair person, \nwhere the Chairperson as well is present, and where  the \nother members except the Chairperson are present, t he \nopinion of the senior member shall prevail in the m atters \nof proceedings; and in the case of judgment or fina l order, \nit shall be submitted to the member who was absent earlier \non the opinion supported by him/her shall be deemed  to be \nthe decision of the Company Board.  \n(e) Where all the three members are present and each ha s a \ndifferent opinion or where majority cannot be estab lished \neven after making submission to the member who was \nabsent earlier pursuant to Clause (d), the opinion of the \nChairperson shall prevail in the case of proceeding s, and \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 152  \nin the case of the judgment or final order, a refer ence shall \nbe made to the Court hearing appeal.  \n(5) The Company Board may, considering the workload  of cases, locate \nitself in any other place in Nepal for any specific  period and hear and settle the \ncases.  \n(6) The Company Board shall follow the procedures r eferred to in the \nSummary Procedure Act, 2028 (1972) while hearing and settling the cases.  \n(7) A party who is not satisfied with a decision ma de by the Company \nBoard on any case pursuant to this Section may make  an appeal to the \nconcerned Appellate Court within thirty five days a fter the date of the receipt \nof information of such decision.  \n(8) The remuneration, facilities and other terms an d conditions of \nservice of the Chairperson and member appointed or designated pursuant to \nthis Section shall be as prescribed.  \nProvided, however, that the terms and conditions of  service shall not be \nprescribed in manner to reduce the remuneration and  facilities once already \nprovided.  \n(9) Notwithstanding  anything contained in Sub-sect ion (1), the \ncompany board  formed pursuant to the Companies Act , 2053 (1996) an \nexisting at the time of the commencement of this Ac t shall continue to exist \npending the formation of the Company Board as referred to in this Act.  \n(10) The cases, and petitions related thereto, file d in and under \nconsideration of or yet to be decided by the compan y board as referred to in \nSub-section (9) at the time of commencement of this Act shall , after the \ncommencement of this Act, be transferred to the Comp any Board as referred to \nin this Section; and such cases shall be heard and settled by  such Board.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "170", "title": "Provisions relating to secretariat and employee of Company Advisory", "content": "Board and Company Board : (1) The secretariat of the Company Advisory \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 153  \nBoard to be formed pursuant to Section 168 shall be  situated in the Company \nRegister’s Office.  \n(2) The secretariat o the Company Board to be forme d pursuant to \nSection 169 shall be situated in the Ministry of  Industries.  \n(3) The secretariat of the Company Board shall have  such number of \nemployees as specified by the Government of Nepal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "171", "title": "Dissolution of Company Board : (1) The Company Board formed pursuant to", "content": "Section 169 shall ipso facto  be dissolved on the date on which the Government \nof Nepal designates the Court as referred to in thi s Act, by a Notification \npublished in the Nepal Gazette.  \n(2) On the dissolution of the Company Board pursuan t to Sub-section \n(1), the appointment of the Chairperson, members an d other employees serving \nin the Board shall ipso facto  be terminated; and no compensation or additional \namount shall be paid to them for such termination w here any employee were \ndeputed by other offices to the Board, their deputa tion shall ipso facto  be \nterminated.  \n(3) On the dissolution of the Company Board pursuan t to  Sub-section \n(1), all cases, and petitions related thereto, file d in and under consideration of \nor yet to be decided by the Board under this Act sh all be transferred to the \nCourt .", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter- 21", "title": "Chapter- 21", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "172", "title": "Record of company and use of computer : (1) The records of any minute", "content": "book, shareholders or debenture holders register, i ndex of shareholders, books \nof account, accounts etc. required to be maintained  by a company pursuant to \nthis Act may be maintained either by making entries  thereof in separate books \nor by recording the same by any electronic communic ation device and \ncomputer in a non-legible form or in any other mann er, without prejudice to the \nprovisions contained in this section.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 154  \n(2) In case where the records of any minute books, s hareholder or \ndebenture holder register index of shareholder, boo ks of account, accounts etc. \nhave not been maintained by making entries thereof in a record book but \nmaintained in any other manner, the following provisions shall be applicable.  \n(a) If it is easily accessible to the place where the r ecords of \nsuch minute book shareholder or debenture register index \nof shareholder books of account, accounts, etc. are  \nmaintained and where such records can be inspected or \ncopes thereof can be obtained, such records shall b e \ndeemed to have been maintained in any specific place. \n(b) The company shall make adequate arrangements that n o \none can destroy or alter the records as referred to  in Clause \n(a) and that the matters recorded therein can be ea sily \ntraced and inspected and copies thereof can be obtained. \n(c) Where any matter has been so recorded that it is no t \nlegible, the matter shall be capable of being repro duced in \na legible form. \n(3) Where the records of any minute book, shareholde r or debenture-\nholder register, index of shareholders, books of account, accounts etc. are put in \nan web site by using any electronic communication de vice or computer \npursuant to this section, arrangements shall be mad e so that the date of such \npreparation of documents as well as the date of ame ndment thereto can be \neasily seen. \n(4) Where a company has maintained the records of a ny minute book, \nregister, index, books of account, accounts etc. ma intained pursuant to this Act \nin a non-legible form and any law establishes the o bligation of the company to \nallow such records for inspection or to submit copi es thereof, then it shall be \nthe obligation of the company to make such arrangem ents that the relevant \nportions of such records can be inspected and that copies thereof can be \nsubmitted in a visible or legible form. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 155", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "173", "title": "Conversion of corporation owned by government of Ne pal into Company:", "content": "(1) If the Government of Nepal wishes to convert a public corporation \nincorporated under the prevailing law, fully or par tly owned by the \nGovernment of Nepal, or a development board formed under the Development \nBoard Act, 2013 (1956) into a company, such corpora tion or board can be \nconverted into a public company and incorporated under this Act.  \n(2) Not withstanding anything contained elsewhere i n this Act, there \nshall be no restriction on the number of promoter, shareholders, in the \nincorporation of a company as referred to in Sub-section (1). \n(3) The movable and the immovable properties of the corporation or \nboard as referred to in Sub-section (1) may be valu ated and converted into the \nshare capital of the company to be incorporate d pu rsuant to Sub-section (1), \nand where such conversion is made, all assets and l iabilities of such \ncorporation or board shall devolve on such company,  except as otherwise \nprovided in the articles of associations.  \n(4) Not withstanding anything contained elsewhere i n this Act, the \nnumber of directors of a company incorporated under  this section shall be as \nspecified in the articles of association of the com pany; and no such directors \nshall be required to subscribe any shares to become a director. \n(5) A company as referred to in this section may se ll its shares in bulk to \nthe private sector through the stock exchange or directly by negotiations.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "174", "title": "Predecessor to handover charge to successor : Any director or any other", "content": "officer or employ of a company shall, on the expiry  of his/her term of office, \nhand over the documents in his/her charge to the su ccessor director or officer \nor employ who is appointed to replace him/her to pe rform his/her functions, \nwithin thirty days from the date of such expiry; an d if such predecessor hands \nover such documents, the successor shall take charge thereof accordingly.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "175", "title": "Transactions between associated companies : (1) Where an agreement or", "content": "arrangement is made between the following companies  whereby any company \ndirectly or indirectly provides loan or other kinds  of financial assistance, pays \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 156  \nany liability, provides guarantee or any other kind  of security to another \ncompany or any other transactions other than an ord inary business transaction \nis done between them, it shall be deemed to be a tr ansaction between the \nassociated companies:  \n(a) Any company and its holding company; \n(b) Any company and any subsidiary company of its holdi ng \ncompany; \n(c) A subsidiary company of any company and the holding  \ncompany of such company; \n(d) A subsidiary company of any company and another \nsubsidiary company of its holding company. \n(2) Where any transactions as referred to in sub se ction (1) is carried on , \nthe associated company shall give a notice on such transactions, also setting out \na following details to its shareholders and the Office as soon as possible: \n(a) Date of transaction and the parties involved in the  \ntransactions; \n(b) Nature of transaction and where transaction such as  \nprovision of a loan, provision of financial assista nce and \nfurnishing security has taken place under such tran saction, \nthe amount or the value thereof.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "176", "title": "Restriction on transaction between companies", "content": ": (1) No company shall, where \ndirectly or indirectly, lend money to another compa ny in excess of an amount \nthat is sixty percent of its paid-up capital and fr ee reserves or an amount to be \nset by hundred percent of its free reserves, which ever is the higher, give \nguarantee for a loan borrowed by another company or  make investment in the \nsecurities of another company in excess of the said amount. \n  (2) Provided, however, that this provision shall not apply to a \ncompany carrying on banking or financial transactio n, insurance company, \ncompany with main objective to buy and sell securit ies, private company which \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 157  \nhas not borrowed any loan from a bank or financial intuitions, company with \nobjective to provide infrastructure facility, and i nvestment made by the holding \ncompany in its fully owned subsidiary company, mone y lent by such holding \ncompany to such subsidiary and guarantee  given by such holding company for \na loan borrowed by such subsidiary and investment  made in right shares issued \nunder this Act. \n(3) Subject to Sub-section(1) , a company shall mai ntain the details, as \nprescribed, on the moneys lent by it to another company, investment made by it \nin such company or guarantee given by it for a loan  borrowed by such another \ncompany.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "177", "title": "Merger of a company : (1) A public company may, by adopting a special", "content": "resolutions in its general meeting to that effect, be merged with another \ncompany subject to Sub-section (3).  \n Provided, however, that, in the case of a private company it shall be as \nprovided in its memorandum of association, articles of association or consensus \nagreement. \n(2) A public company, upon merging into a private company or a private \ncompany, upon merging into a public company shall s tand as a public company. \n(3) If a resolution for merger is adopted pursuant to Sub-section(1),such \ncompany shall, within thirty days , make an applica tion, setting out the \nfollowing matters to the Office for approval: \n(a) In the case of a public company, a copy of the deci sion of \nthe general meeting as referred to in sub- section (1) ,and \nin the case of private company , copies of the  rel ated \nprovisions contained in the memorandum of the \nassociations, articles of the associations, or cons ensus \nagreement authorizing the merger; \n(b) Last balance sheet and auditors report of the mergi ng \ncompany; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 158  \n(c) A copy of the letter of consent in writing, of the creditors \nof the merging company and of the merged company; \n(d) Valuation of the movable and immovable properties o f , \nand actual details of the assets and liabilities of , the \nmerging company; \n(e) If the merging company and merged company have made  \na decision as to the creditors and employees and wo rkers \nof the merging company, a copy of such decision; \n(f) The scheme of arrangement concluded between the \ncompanies for merger with each other. \n(4) Where the information as referred to in Sub-sec tion (3) is given to \nthe Office, it shall study the matter given informa tion and give its decision \nwithin three months.  \n(5) On receipt of an approval from the Officer for merger pursuant to \nSub-section (4), all the assets and liabilities of the merging company shall be \ndeemed to have been transferred to the merged company. \n(6) The office shall maintain separate records of t he merging company \nin the company registration book.  \n(7) Except as otherwise provided in the memorandum of association, \narticles of association or consensus agreement of t he company, a shareholder  \nwho does not express his/her consent in writing to the unification or merger or \nalteration in, or transfer of, shares of the compan y or the sale of entire assets of \nthe company shall be entitled to  get the company’s  assets valuated prior to \nsuch unification, merger or alteration in or transf er of shares or sale of assets \nand get return of the amount in proportion to the s hares held by him/her from \nthe merging company.  \n(8) Notwithstanding anything contained elsewhere in  this Section, the \nOffice shall not give approval for the merger of a company if such merger \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 159  \nappears to create a monopoly or unfair trade restri ction or to be contrary to \npublic interest.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "178", "title": "Power to give directive : If the office receives information through any so urce", "content": "that any company, its director or officer or other employee has not done any \nsuch act as required to be done pursuant to this Ac t or the memorandum of \nassociation or articles of association or the conse nsus agreement, in the case of \na private company, or has committed or is going to c ommit any act in \ncontravention of this Act or the articles of associ ation of the company, the \nOffice may ,by making or causing to be made an inqu iry into the matter, give \nnecessary directive to the concerned company , its director, officer or employee \nto do, or cause to be done, any act required to be done accordingly or to refrain \nfrom doing any prohibited act; and it shall be the duty of the concerned person \nto comply with such directive .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "179", "title": "Bonus share : (1) A company may, by adopting a special resoluti on in the", "content": "general meeting, issue bonus shares to its sharehol ders, out of the amount \navailable for the distribution as dividend.  \n(2) Where a company is to issue bonus shares pursua nt to Sub-section \n(1), the company shall give information thereof to the Office before issuing \nsuch shares.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "180", "title": "Act done or action taken in contravention of this A ct or the articles of", "content": "association  to be void : Except as otherwise provided in this Act or the \nmemorandum of association or articles of associatio n, where any act or action \nrequired to be done or taken under this Act or the memorandum of association \nor articles of association has not been done or tak en or any act or action \nprohibited the under has been done or taken by any company or in respect of \nsuch company, such act or action shall be void.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "181", "title": "Notice on business of company : (1) Where any notice is required to be given", "content": "pursuant to this Act, memorandum of association, an d the person entitled to \nsuch notice expresses, before or after the specifie d time, in writing that the \nnotice is not necessary, the notice shall be deemed to have been received.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 160  \n(2) If any shareholder is present in any Meeting in  person or by proxy, \nhe shall be deemed to have given up his/her right t o receive a notice required to \nbe given to him/her pursuant to this Act, the memor andum of association or \narticles of association.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "182", "title": "Dividend:  (1) Except in the following circumstance, dividend shall be", "content": "distributed to the shareholders within forty five d ays of the decision made to \nprovide dividend:  \n(a) If any law prohibits the distribution of dividend; \n(b) If the right to receive dividend is subject to any dispute; \n(c) If, in a circumstance beyond control of the company  or for \nany reason, dividend cannot be distributed within t he said \ntime-limit.  \n(2) A company  fully or partly owned by the Governm ent of Nepal may \ndistribute dividend only after obtain in  prior app roval of the Government of \nNepal; and the Government of Nepal may give necessa ry directive on the \nmatter of dividend to be distributed by such company.  \n(3) In the event of failure to distribute a dividen d within the tine limit as \nreferred to  in Sub-section(1), the dividend shall be distributed together with \nthe interest thereon at such rate as may be prescribed.  \n(4) The person whose name is maintained in the shar eholder register at \nthe time of declaration of a dividend or his/her le gal heir shall be entitled to \nsuch dividend.  \n(5) A company shall not pay or distribute a dividen d in any other \nmanner except out of the amount of profits set asid e for the distribution of \ndividend.  \n(6) Before paying or declaring a dividend out of th e profits for any \nfinancial year, a company shall have fully deducted  the pre operation expenses, \nthe amount  required to be depreciated in accordanc e with the accounting \nstandards fixed by the competent authority under th e prevailing law, any \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 161  \namount required to be paid or set aside out of the profits under the prevailing \nlaw or the amount or accumulated loss in previous financial years.  \n Provided, however, that if the prevailing law requ ires the establishment \nof a reserve or consolidated fund of any amount pri or to distributing dividend, \nany company which is required to comply with such l egal requirement shall not \ndistribute divided without establishing such reserve or consolidated fund.  \n(7) Subject to the various provisions contained in this Section, the board \nof directors of any company may, in the following c ircumstance, distribute \ninterim dividend out of the profits for the previous financial year: \n(a) where the articles of association contain a provisi on on the \ndistribution of interim dividend;  \n(b) where the annual financial statement for the financ ial year \nout of the profits of which year interim dividend i s to be \ndistributed has already been certified by the audit or and \napproved by the board of directors.  \n(8) No company shall pay or distribute any amount i n cash or kind, \nchargeable on its funds, to its shareholders, excep t a dividend approved by the \ngeneral meeting.  \n(9) The amount of  dividend not claimed/received by  any shareholder \neven after the empery of a period of five years aft er the date of resolution \nadopted by the company in its general meeting to di stribute dividend shall be \ncredited to the investor protection fund to be established under Section 183.  \n(10) In crediting the amount as referred to company  shall, prior to the \nexpiry of the period mentioned in that Sub-section,  publish a notice in a \nnational daily newspaper inviting the concerned to receive the dividend, within \nthe tie limit of at least on month.  \n(11) A company shall credit the amount of a dividen d to be distributed \nto its shareholders pursuant to this Act to a separ ate account within forty five \ndays after the date of approval by the general meet ing and pay the amount of \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 162  \ndividend out of that a account; and the company sha ll not use such amount for \nany  other purpose.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "183", "title": "Investor protection fund : (1) Where any investor does not present a claim t o", "content": "have refunded the amount invested in the shares of a company even within five \nyears, there shall be established an investor prote ction fund to which such \namount shall be credited.  \n(2) The amount credited to the fund established pur suant to Sub-section \n(1) may be spent for the improvement in the capital  market, investment policy, \ncompanies law or law relating to trade, business an d profession, training to the \nemployees of the Office or the company or in any ot her activity relating to the \ncompany administration.  \n(3) The management an operation of the fund establi shed pursuant to \nSub-section (1) shall be as decided by a committee c onsisting of the Registrar, \nthe Chairperson of the Securities Board or his/her representative and one \nrepresentative appointed by the Securities Board fr om amongst the \norganization operating the stock exchange.  \n(4) The Office shall maintain the records of expens es made out of the \nfund established pursuant to Sub-section (1) and have the fund audited.  \n(5) Any amount obtained from the Government of Nepa l, any donor \nagency or any person or body may also be credited t o the fund established \npursuant to Sub-section (1).  \n(6) Where any investor does not present a claim pur suant to Sub-\nsection(1) ,prior to crediting the amount to the in vestor protection fund, a \nnotice shall be published in a national daily newsp aper inviting the concerned \nto receive such amount, within the time limit of at least one month.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "184", "title": "Office of company : (1) Every company shall place a signboard contain ing its", "content": "name and address in the Nepali language outside its  registered office in a \nmanner conspicuous to all. \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 163  \n(2) Every company shall have the address of its reg istered office \nregistered with the Office within three months of its incorporation.  \n(3) A company may change the address of its registe red office by giving \na prior notice to the Office.  \n(4) A company shall, after its registration, shall give information of its \ncontact address such as telephone, fax, email, etc. to the Office; and where such \naddress is changed, the changed address shall be ma de available to the Office \npromptly.  \n(5) The Office may gradually prepare an index of ad dresses of the \nregistered offices of companies and addresses as re ferred to in Sub-section (4) \nand keep such index open for inspection by the general public.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "185", "title": "Appointment of company secretary : (1) A public company with the paid –up", "content": "capital of ten million rupees or more shall appoint  to the pot of company \nsecretary a Nepalese citizen who has the qualification mentioned in Sub-section \n(2).  \n(2) A Nepalese citizen who has worked in the relate d field for at least \ntwo years after obtaining the professional certific ate of company secretary \nissued by a native or foreign body authorized to is sue the professional \ncertificate of company secretary pursuant to the pr evailing law or who has \nworked in the related field or in the field of comp any management for at least \nthree years after doing at least bachelor degree in  law, management ,commerce \nor economics may be appointed to the post of company secretary.  \nProvided, however, that this provision shall not ap ply to the company secretary \nwho is incumbent at the time of commencement of this  Act for three years after \nthe date of commencement of this Act.  \n(3) No director of the concerned company shall be e ligible to be \nappointed as the company secretary of such company.  \n(4) A person shall not be appointed to the post of company secretary of \nmore than one company at the same time.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 164  \nProvided, however, that this provision shall not ba r the appointing of the \ncompany secretary of any principal company to the p ost of company secretary \nof the subsidiary company of such company.  \n(5) Where it is provided by this Act, the prevailin g law or articles  of \nassociation that any act has to be done by or throu gh the company secretary, \nand the post of  company secretary remains vacant i n the company or any \nreason the incumbent company secretary fails to do such act or shows has \ninability to do such  act, then any such employee o f the company, who has the \nqualification referred to in this Act, as designate d by the board of directors to \ndo such act  may perform such act in the capacity of company secretary.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "186", "title": "Functions, duties and powers of company secretary : (1) It shall be the duty", "content": "of the company secretary to implement, or cause to be implemented, the \ndecisions made by the board of directors and the general meeting ad the matters \ndirected by the Office or the concerned bodies and to submit such returns, \ndocuments, decisions etc. as required to be submitt ed by the company to the \nOffice or any other body  pursuant to this Act or t he prevailing law within the \nspecified period.  \n(2) Subject to this Act, the memorandum of associat ion and articles of \nassociation, the company secretary shall perform the following functions:  \n(a) To call the meeting of the board of directors or th e general \nmeeting; \n(b) To prepare the agenda to be discussed in the meetin g of \nthe board of directors or the general meeting and s end it to \nthe concerned directors  or shareholders; \n(c) To maintain the records of, authenticate and take c harge of, \nthe decisions of the meeting of the board of direct ors or \nthe general meeting; \n(d) To send a notice of the allotment of shares and a c all on \nshares pursuant to the decision of the board of directors; \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 165  \n(e) To accurately an properly maintain, take charge of ,and \nauthenticate, the shareholder register and the reco rds of \nshareholders and debenture-holders; \n(f) To refer the matter to the board of directors or th e chief \nexecutive to record the pledge or mortgage of, and execute \nthe transferal or transmission of any shares or debentures; \n(g) In cases where a claim, petition, grievance, sugges tion, \nadvice etc.  has been made by any shareholder or \ndebenture-holder in writing ,to transmit such matte r to the \nboard  of directors or chief executive or Office or  other \nbodies; and to inform in writing the concerned shar eholder \nor debenture-holder of the results of any act and a ction \ndone and taken in regard thereto; \n(h) To perform such other functions as specified to be \nperformed by the company secretary under the prevai ling \nlaw or such other functions as prescribed.  \n(3) Except as per the decision of the general meeti ng, the company \nsecretary shall not do, or cause to be done, any su ch act from or through the \ncompany as is to yield benefits to him/her.  \n(4) The company secretary shall observe the code of  conduct as \nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "187", "title": "Validity of agreement between shareholders", "content": ": (1) An agreement entered into \nbetween the shareholders of a company in respect of  the management, \noperation of the company and the use of voting righ t conferred to them shall be \nbinding on them.  \n Provided, however, that if any provision of such a greement is prejudicial \nto the interest of the company or its minority shar eholders, such provision shall \nipso facto  be invalid to the extent.  \nwww.lawcommission.gov.np \n \nwww.lawcommission.gov.np 166  \n(2) The concerned shareholder shall submit two copi es of the agreement \nentered into under Sub-section (1) to the company w ithin fifteen days after the \ndate on which such agreement was entered into. The company shall submit a \ncopy of the agreement so received from the sharehol der to the Office within \nfifteen days after the receipt of the same.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "188", "title": "Effect of inoperativeness of the Companies Ordinance , 2062(2005) : With", "content": "the Companies Ordinance, 2062 (2005)  being inopera tive, unless a different \nintention appears, the inoperativeness shall not:  \n(a) revive anything not in force or existing at the tim e at \nwhich the Ordinance became inoperative; \n(b) affect the matter in  operation as per  the Ordinance or \nanything duly done or any punishment suffered there under. \n(c) affect any right, privilege, obligation or liabilit y \nacquired ,accrued or incurred under the Ordinance; \n(d) affect any penalty, punishment or forfeiture incurr ed under \nthe Ordinance; \n(e) affect any action or remedy made or taken in respec t of \nany such right, privilege, obligation, liability, p enalty or \npunishment as aforesaid; and any such legal proceed ing or \nremedy  may be instituted, continued or enforced as  if the \nOrdinance were in force.", "children": []}]}]$CODEx384c298a9e24$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
